export const CURATED_CARDS=[{"card":{"adaptation_notes":"三分支为游戏改编；把爬崖与特定堂口改成已有招录制度；资格复核需要档案与申诉状态，传闻不能直接判定作弊。","category":"宗门与派系","choices":[{"action_hint":"interact:ask","continuation":"若执事肯说明，可据公开标准准备下一次考核。","label":"询问复试标准与负责者","requires_extension":false,"tradeoff":"需要当场承认暂时落后，争取的只是明确程序。"},{"action_hint":"custom:申请资格复核","continuation":"若档案支持疑点，可能获得补考，而非直接顶替他人。","label":"请执事复核年龄与资格记录","requires_extension":true,"tradeoff":"提出异议可能令推荐方不悦，也需承担举证工作。"},{"action_hint":"interact:decline","continuation":"若组织允许自由退出，可回乡或另寻师承。","label":"拒绝候补并领取返程凭证","requires_extension":false,"tradeoff":"放弃眼前门路，已有考核投入无法追回。"}],"conflict":"执事要保住选才程序的权威，候补者要公平机会，领路者又怕议论上层招祸。","dedupe_key":"conditional_admission_patronage","exclusions":["玩家已任该组织高层，或没有任何替代去处。"],"followups":[{"closure":"资格落实或玩家撤回申请后结束。","development":"执事按事先说明的条件决定正式接纳或分流。","trigger":"复试日期到来且玩家仍保留候补资格"}],"id":"WD-FR-001","npc_motives":["考核执事：愿留能吃苦者，却不愿重审核心名额。","领路弟子：对偏袒不满，希望听者不要公开引用自己。"],"preconditions":["玩家处于凡俗或初阶，已参加组织招录。","考核结果尚未最终落实，存在候补或外门去处。"],"situation":"入门考核结束，你获得附带复试的候补资格。另一个条件存疑的考生直入核心堂口，领路者私下提到他与高层的关系。","tags":["入门考核","人情门路","试用身份"],"title":"迟到者的入门名额","variation_slots":["考核可换为采办、守夜或技艺试演","候补可换为外院、客卿试用或学徒"]},"content_version":"2026-10-31.1","id":"WD-FR-001","metadata":{"category":"宗门与派系","dedupe_key":"conditional_admission_patronage","source_card_id":"WD-FR-001","source_chapter_ids":["FR-0005"],"tags":["入门考核","人情门路","试用身份"]},"retrieval_text":"迟到者的入门名额\n宗门与派系\n入门考核 人情门路 试用身份\n入门考核结束，你获得附带复试的候补资格。另一个条件存疑的考生直入核心堂口，领路者私下提到他与高层的关系。\n执事要保住选才程序的权威，候补者要公平机会，领路者又怕议论上层招祸。\n考核执事：愿留能吃苦者，却不愿重审核心名额。\n领路弟子：对偏袒不满，希望听者不要公开引用自己。\n玩家处于凡俗或初阶，已参加组织招录。\n考核结果尚未最终落实，存在候补或外门去处。\n玩家已任该组织高层，或没有任何替代去处。\n三分支为游戏改编；把爬崖与特定堂口改成已有招录制度；资格复核需要档案与申诉状态，传闻不能直接判定作弊。"},{"card":{"adaptation_notes":"三分支为游戏改编；毒丸替换为已建立且可查证的控制状态；不把威胁写成自动死亡，撤离也不自动消除既有约束。","category":"师徒与控制","choices":[{"action_hint":"custom:协商限期担保","continuation":"若对方接受中间人见证，可能减轻家属被牵制的风险。","label":"以阶段验收换取家属不受接触","requires_extension":true,"tradeoff":"必须让出部分修炼隐私，口头保证本身并不可靠。"},{"action_hint":"custom:安排亲属转移","continuation":"若亲属自愿且路线安全，控制者可用的把柄会减少。","label":"争取独处后安排家属转移","requires_extension":true,"tradeoff":"需要可信接应者，也可能因调动财物暴露准备。"},{"action_hint":"evade:withdraw","continuation":"若摆脱看守，可暂缓正面对抗并另找解制办法。","label":"沿已知退路撤离会面","requires_extension":false,"tradeoff":"现有约束不会自动解除，仍需处理亲属安全。"}],"conflict":"授业者急于借成果解决自身危机，你需要时间自救，却不能只顾自己而忽略亲属暴露。","dedupe_key":"mentor_deadline_family_leverage","exclusions":["没有亲属关系，或控制手段已被证实无效。"],"followups":[{"closure":"控制解除、另行和解或双方失去接触后结束。","development":"其根据真实进展与担保执行情况调整条件，玩家可继续谈或脱离。","trigger":"控制者约定的阶段期限临近"}],"id":"WD-FR-002","npc_motives":["授业者：怕期限到来前等不到成果，用控制弥补不信任。","知情亲友：愿协助转移家属，但需要可信说明与路费。"],"preconditions":["师徒关系已有秘密目标或严重失信。","亲属确实可被联系，且玩家有可行撤退路线。"],"situation":"授业者怀疑你隐瞒进展，要求在期限前达到指定修为，并亮出能控制你的手段，还暗示掌握亲属行踪。谈话已转为胁迫。","tags":["师徒失信","限期修炼","家属牵制"],"title":"以亲人为限期担保","variation_slots":["约束可换为债契、禁制或扣押证件","亲属可换为受照顾的同伴"]},"content_version":"2026-10-31.1","id":"WD-FR-002","metadata":{"category":"师徒与控制","dedupe_key":"mentor_deadline_family_leverage","source_card_id":"WD-FR-002","source_chapter_ids":["FR-0031"],"tags":["师徒失信","限期修炼","家属牵制"]},"retrieval_text":"以亲人为限期担保\n师徒与控制\n师徒失信 限期修炼 家属牵制\n授业者怀疑你隐瞒进展，要求在期限前达到指定修为，并亮出能控制你的手段，还暗示掌握亲属行踪。谈话已转为胁迫。\n授业者急于借成果解决自身危机，你需要时间自救，却不能只顾自己而忽略亲属暴露。\n授业者：怕期限到来前等不到成果，用控制弥补不信任。\n知情亲友：愿协助转移家属，但需要可信说明与路费。\n师徒关系已有秘密目标或严重失信。\n亲属确实可被联系，且玩家有可行撤退路线。\n没有亲属关系，或控制手段已被证实无效。\n三分支为游戏改编；毒丸替换为已建立且可查证的控制状态；不把威胁写成自动死亡，撤离也不自动消除既有约束。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著药物依赖仅转为真实持续需求；交换、授课范围和权限需独立记录，不凭询问动作授予技能。","category":"交易与信用","choices":[{"action_hint":"custom:重订互助条款","continuation":"若找到可学部分，可改成有限课程而非无限供给。","label":"共同试练后重订交换内容","requires_extension":true,"tradeoff":"试练会耗费精力，也可能证明无可适配的技艺。"},{"action_hint":"interact:ask","continuation":"若同门确有线索，可获得查阅方向而非立即学成。","label":"询问传授权限内的冷门技艺","requires_extension":false,"tradeoff":"冷门内容可能缺少成功先例，需自行判断可行性。"},{"action_hint":"interact:decline","continuation":"若旧账结清，双方仍可能保留私人友谊。","label":"拒绝继续交换，说明适配问题","requires_extension":false,"tradeoff":"眼前援助与授课同时停止，需要各自寻找替代。"}],"conflict":"传授者只能接触少数技艺，却需要持续援助；你要能用的本领，不愿为无效课程长期付出。","dedupe_key":"restricted_skill_reciprocity_mismatch","exclusions":["相关技艺本已公开，或双方没有继续交易的意愿。"],"followups":[{"closure":"交换结清、正式改约或双方终止后结束。","development":"按新范围核对已授内容与援助，不以友情强迫追加。","trigger":"双方再次约定授课或交付时"}],"id":"WD-FR-003","npc_motives":["同门：想维持帮助，也不愿承认自己并非什么都能教。","守阁人：要防止禁传内容外流，未必反对普通经验交流。"],"preconditions":["双方已有一次以上可信交换。","玩家拥有可持续援助，但所学存在明确适配障碍。"],"situation":"一位同门愿以本门受限技艺交换你能持续提供的帮助。几次试学后，你发现他擅长的路数并不适合自己，双方仍珍惜这段互助。","tags":["私下互助","受限技艺","能力适配"],"title":"私授技艺的互惠","variation_slots":["援助可换为修补器具、护送或翻译","受限知识可换为阵图或行业经验"]},"content_version":"2026-10-31.1","id":"WD-FR-003","metadata":{"category":"交易与信用","dedupe_key":"restricted_skill_reciprocity_mismatch","source_card_id":"WD-FR-003","source_chapter_ids":["FR-0033"],"tags":["私下互助","受限技艺","能力适配"]},"retrieval_text":"私授技艺的互惠\n交易与信用\n私下互助 受限技艺 能力适配\n一位同门愿以本门受限技艺交换你能持续提供的帮助。几次试学后，你发现他擅长的路数并不适合自己，双方仍珍惜这段互助。\n传授者只能接触少数技艺，却需要持续援助；你要能用的本领，不愿为无效课程长期付出。\n同门：想维持帮助，也不愿承认自己并非什么都能教。\n守阁人：要防止禁传内容外流，未必反对普通经验交流。\n双方已有一次以上可信交换。\n玩家拥有可持续援助，但所学存在明确适配障碍。\n相关技艺本已公开，或双方没有继续交易的意愿。\n三分支为游戏改编；原著药物依赖仅转为真实持续需求；交换、授课范围和权限需独立记录，不凭询问动作授予技能。"},{"card":{"adaptation_notes":"三分支为游戏改编；把超常记忆转为已建立的熟人辨认能力；怀疑、证据、被发现状态分别记录，不能让片段自动揭晓整场阴谋。","category":"身份与秘密","choices":[{"action_hint":"interact:observe","continuation":"若观察到可核对的交接点，可提高后续报告可信度。","label":"辨认两人当下的离去方向","requires_extension":false,"tradeoff":"只能看到当下动向，风声与树影可能妨碍判断。"},{"action_hint":"custom:提交未核实警讯","continuation":"若主管愿核查出入记录，可形成独立证据而非立即定罪。","label":"抵达安全处提交限定范围的警讯","requires_extension":true,"tradeoff":"报告会让自己成为知情者，主管也可能要求进一步说明。"},{"action_hint":"evade:withdraw","continuation":"若未暴露，可保留记忆，之后自行决定是否报告。","label":"趁风声掩护退出密谈范围","requires_extension":false,"tradeoff":"会放弃当场获取更多内容的机会。"}],"conflict":"密谈者要保密行动，你想判断威胁；直接指认缺乏证据，继续尾随又可能暴露。","dedupe_key":"fragmentary_conspiracy_familiar_voice","exclusions":["已取得完整命令，或对方已明确发现玩家。"],"followups":[{"closure":"线索证伪、调查移交或玩家明确不再追查后结束。","development":"旧片段可与新事实互相印证，也可能证明最初误认。","trigger":"名单相关人员出行，或守卫查到可疑往返记录"}],"id":"WD-FR-004","npc_motives":["往返管事：凭日常差事传递消息，害怕真实身份被核实。","守卫负责人：愿防袭，却不愿凭一句传闻处置熟人。"],"preconditions":["玩家有辨认该熟人声音的既有经历。","现场有遮蔽物与通向安全地带的退路。"],"situation":"夜路上有人低声谈及敌方与一份名单，你藏身后只听到片段，其中一个声音像常往返内外的熟人。来人尚未发现你。","tags":["片段情报","熟人嫌疑","夜路潜听"],"title":"风声中的半份密谋","variation_slots":["声音可换为惯用暗号或旧伤姿态","名单可换为轮值表或货运清单"]},"content_version":"2026-10-31.1","id":"WD-FR-004","metadata":{"category":"身份与秘密","dedupe_key":"fragmentary_conspiracy_familiar_voice","source_card_id":"WD-FR-004","source_chapter_ids":["FR-0038"],"tags":["片段情报","熟人嫌疑","夜路潜听"]},"retrieval_text":"风声中的半份密谋\n身份与秘密\n片段情报 熟人嫌疑 夜路潜听\n夜路上有人低声谈及敌方与一份名单，你藏身后只听到片段，其中一个声音像常往返内外的熟人。来人尚未发现你。\n密谈者要保密行动，你想判断威胁；直接指认缺乏证据，继续尾随又可能暴露。\n往返管事：凭日常差事传递消息，害怕真实身份被核实。\n守卫负责人：愿防袭，却不愿凭一句传闻处置熟人。\n玩家有辨认该熟人声音的既有经历。\n现场有遮蔽物与通向安全地带的退路。\n已取得完整命令，或对方已明确发现玩家。\n三分支为游戏改编；把超常记忆转为已建立的熟人辨认能力；怀疑、证据、被发现状态分别记录，不能让片段自动揭晓整场阴谋。"},{"card":{"adaptation_notes":"三分支为游戏改编；宝玉改成可核验的解除资源；婚约不作为报酬，第三人意愿须独立成立，遗书不自动建立玩家承诺。","category":"机缘与代价","choices":[{"action_hint":"custom:重谈遗嘱委托","continuation":"若双方认可对等条件，可形成限时护送而非承接全部旧债。","label":"持信登门重谈救助与护送","requires_extension":true,"tradeoff":"会暴露自己知道死讯，并卷入遗属内部争论。"},{"action_hint":"interact:ask","continuation":"若发现替代方案，可减少亡者遗嘱对自己的束缚。","label":"询问独立知情者对解除办法的看法","requires_extension":false,"tradeoff":"知情者可能只掌握片段，询问也会暴露自己的困境。"},{"action_hint":"interact:decline","continuation":"若找到其他帮助，可在不承担家族事务的情况下继续求生。","label":"拒绝接手并另寻解决渠道","requires_extension":false,"tradeoff":"放弃遗产与现成线索，已有隐患仍须自行处理。"}],"conflict":"亡者要延续对家属的保障，你要解决隐患；遗属未必承认其安排，也未必愿搬离故业。","dedupe_key":"posthumous_remedy_escrow_obligation","exclusions":["书信已证伪，或遗属明确拒绝全部接触。"],"followups":[{"closure":"委托结清、遗属拒绝或玩家转向其他办法后结束。","development":"重新界定可提供的帮助，遗属可自行选择留守或迁出。","trigger":"遗属确认信物或独立核验得到结果"}],"id":"WD-FR-005","npc_motives":["遗属主事者：希望保住家人，也担心来客借信夺产。","旧部首领：想确认主人死讯，趁权力空缺扩大自己地盘。"],"preconditions":["玩家已持有可信遗书或信物。","自身隐患确实存在，遗属所在地与其他求助方向已知。"],"situation":"一位已死的控制者留下书信，称能解除你隐患的物件在其家属手中，并用财产与身份凭证邀请你接手保护家属的责任。","tags":["遗嘱交易","身后托付","连环约束"],"title":"亡者留下的救急条件","variation_slots":["救急物可换为解契文书或修复材料","遗属可换为旧部与受托学徒"]},"content_version":"2026-10-31.1","id":"WD-FR-005","metadata":{"category":"机缘与代价","dedupe_key":"posthumous_remedy_escrow_obligation","source_card_id":"WD-FR-005","source_chapter_ids":["FR-0062"],"tags":["遗嘱交易","身后托付","连环约束"]},"retrieval_text":"亡者留下的救急条件\n机缘与代价\n遗嘱交易 身后托付 连环约束\n一位已死的控制者留下书信，称能解除你隐患的物件在其家属手中，并用财产与身份凭证邀请你接手保护家属的责任。\n亡者要延续对家属的保障，你要解决隐患；遗属未必承认其安排，也未必愿搬离故业。\n遗属主事者：希望保住家人，也担心来客借信夺产。\n旧部首领：想确认主人死讯，趁权力空缺扩大自己地盘。\n玩家已持有可信遗书或信物。\n自身隐患确实存在，遗属所在地与其他求助方向已知。\n书信已证伪，或遗属明确拒绝全部接触。\n三分支为游戏改编；宝玉改成可核验的解除资源；婚约不作为报酬，第三人意愿须独立成立，遗书不自动建立玩家承诺。"},{"card":{"adaptation_notes":"三分支为游戏改编；死契只转为有明确签署门槛的规则争议；拒绝不施加全世界追杀，人数与敌方底牌须由世界已有状态支持。","category":"势力博弈","choices":[{"action_hint":"custom:核验决斗条款","continuation":"若发现异常援手，可推动缩小决斗范围或补设限制。","label":"要求公开规则并核对出场名单","requires_extension":true,"tradeoff":"可能拖慢停战，也让首领觉得锐气受损。"},{"action_hint":"custom:提出撤军担保","continuation":"若双方接受监督与分批交接，可将复仇争执留待另议。","label":"提出以撤军担保替代集体决斗","requires_extension":true,"tradeoff":"首领可能认为复仇未获满足，需拿出可信执行办法。"},{"action_hint":"evade:withdraw","continuation":"若撤离路线畅通，可保全自身并等待战争结果。","label":"拒绝参战并撤至安全位置","requires_extension":false,"tradeoff":"可能失去首领信任，也无法左右仍选择参战者。"}],"conflict":"首领要报仇并除去敌魁，敌方要借规则歼灭精锐，普通成员希望活着结束冲突。","dedupe_key":"vendetta_duel_rule_asymmetry","exclusions":["死斗已开始，或玩家被设定为无法拒绝的祭品。"],"followups":[{"closure":"停战完成、决斗另行成立或玩家离开战区后结束。","development":"双方根据对方履约情况继续谈判，不能自动推定隐藏底牌。","trigger":"出场名单确定或撤军第一批抵达交接点"}],"id":"WD-FR-006","npc_motives":["己方首领：认为敌魁不死就没有长久安宁，低估对手隐藏力量。","敌方谈判者：愿用决斗代替继续围攻，暗中掌握更多战力情报。"],"preconditions":["玩家与参战组织有关系，但尚未签下决斗约束。","撤军协议存在可执行草案，双方仍能谈判。"],"situation":"两方已接近达成撤离协议，己方首领却要求在撤军前决斗复仇。对手同意，但提出由自己确定人数与混战规则。","tags":["停战谈判","规则争夺","私仇公义"],"title":"撤军前的复仇决斗","variation_slots":["复仇对象可换为叛徒或失地守将","担保可换为中立关卡或交换俘虏"]},"content_version":"2026-10-31.1","id":"WD-FR-006","metadata":{"category":"势力博弈","dedupe_key":"vendetta_duel_rule_asymmetry","source_card_id":"WD-FR-006","source_chapter_ids":["FR-0085"],"tags":["停战谈判","规则争夺","私仇公义"]},"retrieval_text":"撤军前的复仇决斗\n势力博弈\n停战谈判 规则争夺 私仇公义\n两方已接近达成撤离协议，己方首领却要求在撤军前决斗复仇。对手同意，但提出由自己确定人数与混战规则。\n首领要报仇并除去敌魁，敌方要借规则歼灭精锐，普通成员希望活着结束冲突。\n己方首领：认为敌魁不死就没有长久安宁，低估对手隐藏力量。\n敌方谈判者：愿用决斗代替继续围攻，暗中掌握更多战力情报。\n玩家与参战组织有关系，但尚未签下决斗约束。\n撤军协议存在可执行草案，双方仍能谈判。\n死斗已开始，或玩家被设定为无法拒绝的祭品。\n三分支为游戏改编；死契只转为有明确签署门槛的规则争议；拒绝不施加全世界追杀，人数与敌方底牌须由世界已有状态支持。"},{"card":{"adaptation_notes":"三分支为游戏改编；把原著突显实力转为已有功劳与威胁感；高层恶意需线索支持，谈判不能凭一句话自动产生庇护关系。","category":"宗门与派系","choices":[{"action_hint":"custom:协商离任交易","continuation":"若条款可执行，首领可能公开宣布和平离任以约束部属。","label":"提出有限交接换取离任保障","requires_extension":true,"tradeoff":"须交付自己愿意让出的资源，保障仍需能被核查。"},{"action_hint":"interact:ask","continuation":"若出现矛盾，可据此调整交接地点与时间。","label":"询问会面安排并试探安全顾虑","requires_extension":false,"tradeoff":"过于直白可能令首领戒备，含糊回答不能当作保证。"},{"action_hint":"evade:withdraw","continuation":"若安全脱身，可自行决定是否重开谈判。","label":"暂停谈判，撤离可能设伏的会面区","requires_extension":false,"tradeoff":"暂时放弃安置旧关系的协议，之后仍可托中间人联系。"}],"conflict":"首领要稳定权威且避免反噬，你要安全离开并照顾留在组织中的关系，双方都不愿公开撕破脸。","dedupe_key":"indispensable_benefactor_exit_bargain","exclusions":["组织已失去谈判代表，或玩家无任何可交换利益。"],"followups":[{"closure":"交接结束、协议撤销或双方停止接触后结束。","development":"首领用公开安排表现其履约程度，留任关系人可独立反馈。","trigger":"正式大会召开或交接期限届满"}],"id":"WD-FR-007","npc_motives":["组织首领：愿用利益交换换取安稳离任，但不愿承认高层起过恶念。","激进长老：想借庆功接触秘密，担心首领先独占好处。"],"preconditions":["玩家已为该组织立功，并有离开的真实意愿。","双方尚无不可调和的公开死仇，私会处有退路。"],"situation":"你为组织解围后，部分掌权者开始担忧你难以控制，也觊觎你的本领。正式庆功会将近，首领留出了一次私下商谈的机会。","tags":["功高难制","秘密会面","离职安排"],"title":"功臣离山的私下和解","variation_slots":["功劳可换为镇灾、解围或关键技术","交接物可换为疗伤资源或防护图纸"]},"content_version":"2026-10-31.1","id":"WD-FR-007","metadata":{"category":"宗门与派系","dedupe_key":"indispensable_benefactor_exit_bargain","source_card_id":"WD-FR-007","source_chapter_ids":["FR-0097"],"tags":["功高难制","秘密会面","离职安排"]},"retrieval_text":"功臣离山的私下和解\n宗门与派系\n功高难制 秘密会面 离职安排\n你为组织解围后，部分掌权者开始担忧你难以控制，也觊觎你的本领。正式庆功会将近，首领留出了一次私下商谈的机会。\n首领要稳定权威且避免反噬，你要安全离开并照顾留在组织中的关系，双方都不愿公开撕破脸。\n组织首领：愿用利益交换换取安稳离任，但不愿承认高层起过恶念。\n激进长老：想借庆功接触秘密，担心首领先独占好处。\n玩家已为该组织立功，并有离开的真实意愿。\n双方尚无不可调和的公开死仇，私会处有退路。\n组织已失去谈判代表，或玩家无任何可交换利益。\n三分支为游戏改编；把原著突显实力转为已有功劳与威胁感；高层恶意需线索支持，谈判不能凭一句话自动产生庇护关系。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著修仙与凡俗寿命差转为已知的远行及时间成本；离开只结束现场互动，远行另走已声明路线。","category":"凡俗与旧情","choices":[{"action_hint":"custom:安排迟来的团聚","continuation":"若家人愿意，可留下联络方式而不承诺常驻。","label":"等仪式结束再现身问候","requires_extension":true,"tradeoff":"会占用启程时间，也要面对归期与去向的追问。"},{"action_hint":"custom:转交家书","continuation":"若亲属回信，可慢慢修复关系并决定日后见面。","label":"托可信旧识送上可核实的家书","requires_extension":true,"tradeoff":"中间人会知道行踪，文字也无法替代当面解释。"},{"action_hint":"interact:leave","continuation":"若日后仍有联系条件，可由玩家自行决定是否重访。","label":"不打扰喜事，按原计划离开","requires_extension":false,"tradeoff":"错过当次相见，心中的遗憾不会自动化解。"}],"conflict":"家人希望团圆并理解你的去向，你想告别却难以许诺归期；贸然出现也可能打乱今日安排。","dedupe_key":"unannounced_homecoming_life_divergence","exclusions":["亲属已全部亡故，或已有明确不愿见面的拒绝。"],"followups":[{"closure":"一次告别完成或玩家停止联络后结束。","development":"亲属讲述其真实生活变化，不因玩家缺席自动怨恨或获利。","trigger":"家书得到回复，或玩家自愿再次回乡"}],"id":"WD-FR-008","npc_motives":["年长亲属：惦念远行者，却不愿喜事中的晚辈承担自己的失落。","成家的晚辈：盼亲人祝福，也希望新生活不受额外要求束缚。"],"preconditions":["玩家有长期未见的凡俗亲属，关系未断绝。","玩家能自主决定是否露面，现场没有必须救援的危险。"],"situation":"多年未归，你在家门外撞上一场亲人的喜事。家人已习惯没有你的生活，而你即将踏上去期不定的旅程，尚无人注意到你。","tags":["归乡","亲缘疏离","远行选择"],"title":"家门外的喜事","variation_slots":["喜事可换为迁居、寿宴或孩子入学","亲属可换为养育者或凡俗旧友"]},"content_version":"2026-10-31.1","id":"WD-FR-008","metadata":{"category":"凡俗与旧情","dedupe_key":"unannounced_homecoming_life_divergence","source_card_id":"WD-FR-008","source_chapter_ids":["FR-0099"],"tags":["归乡","亲缘疏离","远行选择"]},"retrieval_text":"家门外的喜事\n凡俗与旧情\n归乡 亲缘疏离 远行选择\n多年未归，你在家门外撞上一场亲人的喜事。家人已习惯没有你的生活，而你即将踏上去期不定的旅程，尚无人注意到你。\n家人希望团圆并理解你的去向，你想告别却难以许诺归期；贸然出现也可能打乱今日安排。\n年长亲属：惦念远行者，却不愿喜事中的晚辈承担自己的失落。\n成家的晚辈：盼亲人祝福，也希望新生活不受额外要求束缚。\n玩家有长期未见的凡俗亲属，关系未断绝。\n玩家能自主决定是否露面，现场没有必须救援的危险。\n亲属已全部亡故，或已有明确不愿见面的拒绝。\n三分支为游戏改编；原著修仙与凡俗寿命差转为已知的远行及时间成本；离开只结束现场互动，远行另走已声明路线。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著宝玉绑约改成普通报酬争议；家眷自愿单独记录，护送与跨地旅行需实际任务及路线支持。","category":"势力博弈","choices":[{"action_hint":"custom:协商家眷分流","continuation":"若主事者同意分流，可先安排不愿参战的人离开。","label":"召集自愿迁出者单独核对行程","requires_extension":true,"tradeoff":"公开分歧可能削弱家族凝聚，运输能力也有限。"},{"action_hint":"custom:界定防护委托","continuation":"若接受限时防护，可争取迁居或停战的准备时间。","label":"明确救助范围并要求主事者选项","requires_extension":true,"tradeoff":"对方可能认为帮助不足，拒绝交出原定报酬。"},{"action_hint":"interact:decline","continuation":"若日后对方愿缩小任务范围，可以重新议价。","label":"拒绝替家族铲除敌对势力的委托","requires_extension":false,"tradeoff":"失去这笔报酬，家族也会另找助力。"}],"conflict":"主事者要同时保命与保住势力，普通家眷更想脱险；你不愿把有限护送变成无边界战争。","dedupe_key":"evacuation_offer_vs_power_retention","exclusions":["所有家眷已一致决定留守，且拒绝再谈迁居。"],"followups":[{"closure":"迁居完成、双方撤销委托或玩家退出后结束。","development":"按已知运力与路线安排出发，留守者继续自行处理家业。","trigger":"迁出截止日到来且有家眷自愿报名"}],"id":"WD-FR-009","npc_motives":["家族主事者：担心迁出就失去号令旧部的资格。","家眷代表：愿放弃部分产业，却怕意见被说成怯懦。"],"preconditions":["家族面临明确而非臆测的外部压力。","至少一条安全性可评估的迁出路线已知。"],"situation":"一个受敌方压迫的家族请你彻底除去对手，声称只有如此才算救人。你能提供的较稳妥方案是迁居，但主事者舍不得城中的权势。","tags":["迁居谈判","守业野心","护送边界"],"title":"保住家业还是带人离城","variation_slots":["家业可换为矿脉、商路或领地","迁出者可换为工匠与学徒"]},"content_version":"2026-10-31.1","id":"WD-FR-009","metadata":{"category":"势力博弈","dedupe_key":"evacuation_offer_vs_power_retention","source_card_id":"WD-FR-009","source_chapter_ids":["FR-0118"],"tags":["迁居谈判","守业野心","护送边界"]},"retrieval_text":"保住家业还是带人离城\n势力博弈\n迁居谈判 守业野心 护送边界\n一个受敌方压迫的家族请你彻底除去对手，声称只有如此才算救人。你能提供的较稳妥方案是迁居，但主事者舍不得城中的权势。\n主事者要同时保命与保住势力，普通家眷更想脱险；你不愿把有限护送变成无边界战争。\n家族主事者：担心迁出就失去号令旧部的资格。\n家眷代表：愿放弃部分产业，却怕意见被说成怯懦。\n家族面临明确而非臆测的外部压力。\n至少一条安全性可评估的迁出路线已知。\n所有家眷已一致决定留守，且拒绝再谈迁居。\n三分支为游戏改编；原著宝玉绑约改成普通报酬争议；家眷自愿单独记录，护送与跨地旅行需实际任务及路线支持。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著女眷婚配筹码转成可争议的越权许诺；不得由玩家受诺便自动生成婚姻、好感或人身所有关系。","category":"凡俗与旧情","choices":[{"action_hint":"interact:ask","continuation":"若当事人愿意说明，可明确哪些承诺根本不能写入交易。","label":"请关系当事人独立表达意见","requires_extension":false,"tradeoff":"会让主事者失去对场面的控制，未必获得立即答复。"},{"action_hint":"custom:剔除第三人承诺","continuation":"若双方接受，可形成不牵连第三人终身的有限合作。","label":"删去关系报酬并改谈物资与任务范围","requires_extension":true,"tradeoff":"新报酬可能不足，对方也可能因此降低委托规模。"},{"action_hint":"interact:decline","continuation":"若当事人日后自愿求助，可作为独立关系重新处理。","label":"拒绝新增条件并退出整笔委托","requires_extension":false,"tradeoff":"原本可能获得的收益一并放弃。"}],"conflict":"委托人想用不由自己承担的代价扩大收益，你与当事人都需要重新划清承诺边界。","dedupe_key":"third_party_life_promised_as_payment","exclusions":["关系当事人已在无压力环境下明确自愿，且与委托无关。"],"followups":[{"closure":"修订合同成立或谈判终止后结束。","development":"分别核验任务与私人关系，不把一次援助解释为婚约成立。","trigger":"委托人提交修订条款或当事人主动联系"}],"id":"WD-FR-010","npc_motives":["委托人：将家族利益置于个人意愿之前，担心原条件不足以吸引帮手。","被许诺者：希望表达真实选择，却顾虑失去居所与亲属支持。"],"preconditions":["存在尚未成立的委托，新增关系未经当事人同意。","玩家有拒绝新条件的自由。"],"situation":"谈判即将定案时，委托人突然许诺把亲属的终身关系作为额外报酬，换你承担更多危险。被许诺者在场，却明显事前不知情。","tags":["婚约筹码","第三人意愿","委托加码"],"title":"替别人许下的终身","variation_slots":["婚约可换为入赘、收徒或人身从属","家族主事者可换为监护人或族老"]},"content_version":"2026-10-31.1","id":"WD-FR-010","metadata":{"category":"凡俗与旧情","dedupe_key":"third_party_life_promised_as_payment","source_card_id":"WD-FR-010","source_chapter_ids":["FR-0123"],"tags":["婚约筹码","第三人意愿","委托加码"]},"retrieval_text":"替别人许下的终身\n凡俗与旧情\n婚约筹码 第三人意愿 委托加码\n谈判即将定案时，委托人突然许诺把亲属的终身关系作为额外报酬，换你承担更多危险。被许诺者在场，却明显事前不知情。\n委托人想用不由自己承担的代价扩大收益，你与当事人都需要重新划清承诺边界。\n委托人：将家族利益置于个人意愿之前，担心原条件不足以吸引帮手。\n被许诺者：希望表达真实选择，却顾虑失去居所与亲属支持。\n存在尚未成立的委托，新增关系未经当事人同意。\n玩家有拒绝新条件的自由。\n关系当事人已在无压力环境下明确自愿，且与委托无关。\n三分支为游戏改编；原著女眷婚配筹码转成可争议的越权许诺；不得由玩家受诺便自动生成婚姻、好感或人身所有关系。"},{"card":{"adaptation_notes":"三分支为游戏改编；钥匙符替换为可撤销的共同住处权限；入盟、指挥范围与退盟要显式支持，询问不自动加入团体。","category":"同盟与背叛","choices":[{"action_hint":"interact:ask","continuation":"若范围讲清，可据此决定是否短期加入。","label":"询问哪些争端属于共同防卫","requires_extension":false,"tradeoff":"需要公开自己的顾虑，可能暴露与其他成员的观念差异。"},{"action_hint":"custom:建立有限互助","continuation":"若对方接受，可形成不含战斗指挥权的合作。","label":"提出只共住与互报警讯的协作","requires_extension":true,"tradeoff":"得到的支援会较少，成员也未必愿分享全部便利。"},{"action_hint":"interact:decline","continuation":"若集会仍开放，可以保留礼貌往来而不承担义务。","label":"拒绝入伙，另找落脚处","requires_extension":false,"tradeoff":"失去现成庇护与共同情报，住宿需自行解决。"}],"conflict":"领头者要足够人手形成威慑，你要保护与消息，却不愿替成员私人争端无限承担责任。","dedupe_key":"temporary_coalition_command_scope","exclusions":["领头者已明确要求永久效忠或交出全部财物。"],"followups":[{"closure":"集会结束、成员退盟或协作期满后结束。","development":"依据预先确定的共同防卫范围决定是否适用。","trigger":"成员首次请求集体出面处理纠纷"}],"id":"WD-FR-011","npc_motives":["领头者：希望扩充实力，也担心成员遇事各自逃散。","谨慎成员：愿分担警戒，不想为别人的挑衅出头。"],"preconditions":["玩家暂无足够强的组织保护，正参加有竞争压力的聚会。","同盟尚未卷入实际冲突，成员身份可相互介绍。"],"situation":"集会上几名散修邀请你结伴自保，愿共享落脚处与常识。他们承诺平时自由行动，却要求发生外部纠纷时听从领头者指挥。","tags":["散修结伴","集体自保","行动自主"],"title":"临时同盟的指挥边界","variation_slots":["集会可换为渡口候船或秘境营地","共享资源可换为住处、守夜或路线信息"]},"content_version":"2026-10-31.1","id":"WD-FR-011","metadata":{"category":"同盟与背叛","dedupe_key":"temporary_coalition_command_scope","source_card_id":"WD-FR-011","source_chapter_ids":["FR-0130"],"tags":["散修结伴","集体自保","行动自主"]},"retrieval_text":"临时同盟的指挥边界\n同盟与背叛\n散修结伴 集体自保 行动自主\n集会上几名散修邀请你结伴自保，愿共享落脚处与常识。他们承诺平时自由行动，却要求发生外部纠纷时听从领头者指挥。\n领头者要足够人手形成威慑，你要保护与消息，却不愿替成员私人争端无限承担责任。\n领头者：希望扩充实力，也担心成员遇事各自逃散。\n谨慎成员：愿分担警戒，不想为别人的挑衅出头。\n玩家暂无足够强的组织保护，正参加有竞争压力的聚会。\n同盟尚未卷入实际冲突，成员身份可相互介绍。\n领头者已明确要求永久效忠或交出全部财物。\n三分支为游戏改编；钥匙符替换为可撤销的共同住处权限；入盟、指挥范围与退盟要显式支持，询问不自动加入团体。"},{"card":{"adaptation_notes":"三分支为游戏改编；保留物品可返还与群体纵容的结构；退伙需财物交接状态，原著道歉不移植成自动和解。","category":"同盟与背叛","choices":[{"action_hint":"custom:订立团体纪律","continuation":"若众人认可停止规则，可保留合作并明确再次越界的处理。","label":"要求当众归还并由受影响者定边界","requires_extension":true,"tradeoff":"可能令逞技者难堪，领队也要公开表态。"},{"action_hint":"interact:ask","continuation":"若有人另有顾虑，可另组路线而不替所有人接受道歉。","label":"询问过往受影响者是否愿继续同行","requires_extension":false,"tradeoff":"会揭开被压下的分歧，可能导致成员分流。"},{"action_hint":"custom:结清财物退伙","continuation":"若交接顺利，可结束纠纷而不承诺原谅。","label":"取回自有物件后退出团体","requires_extension":true,"tradeoff":"失去原有同行支援，需要安排自己的住处与路线。"}],"conflict":"领队想保住有天赋的帮手与团体和气，受影响者需要可信边界，当事人不愿被当成恶贼。","dedupe_key":"talented_member_boundary_violation","exclusions":["已形成持续暴力抢夺，或失物无法追回却被强说无事。"],"followups":[{"closure":"规则获持续遵守、团体解散或玩家退伙后结束。","development":"根据实际行为检验承诺，不因天赋自动免除责任。","trigger":"逞技者再次接触成员随身物品或团体下一次出行"}],"id":"WD-FR-012","npc_motives":["逞技者：在意被认可，习惯把他人不满当作玩笑。","领队：担心内斗削弱自保能力，也怕他招惹外部强敌。"],"preconditions":["物品尚可找回，冲突仍处于可交谈阶段。","玩家与涉事者属于临时或松散团体。"],"situation":"临时伙伴在欢迎你时顺手摸走物件，被你察觉。领队称他只是爱玩且总会归还，其他成员却透露自己也受过同样对待。","tags":["内部纪律","天才特权","受害者边界"],"title":"把偷窃说成玩笑的人","variation_slots":["偷窃可换为擅改器具或私看信件","逞技者可换为年轻工匠或贵族子弟"]},"content_version":"2026-10-31.1","id":"WD-FR-012","metadata":{"category":"同盟与背叛","dedupe_key":"talented_member_boundary_violation","source_card_id":"WD-FR-012","source_chapter_ids":["FR-0133"],"tags":["内部纪律","天才特权","受害者边界"]},"retrieval_text":"把偷窃说成玩笑的人\n同盟与背叛\n内部纪律 天才特权 受害者边界\n临时伙伴在欢迎你时顺手摸走物件，被你察觉。领队称他只是爱玩且总会归还，其他成员却透露自己也受过同样对待。\n领队想保住有天赋的帮手与团体和气，受影响者需要可信边界，当事人不愿被当成恶贼。\n逞技者：在意被认可，习惯把他人不满当作玩笑。\n领队：担心内斗削弱自保能力，也怕他招惹外部强敌。\n物品尚可找回，冲突仍处于可交谈阶段。\n玩家与涉事者属于临时或松散团体。\n已形成持续暴力抢夺，或失物无法追回却被强说无事。\n三分支为游戏改编；保留物品可返还与群体纵容的结构；退伙需财物交接状态，原著道歉不移植成自动和解。"},{"card":{"adaptation_notes":"三分支为游戏改编；提升资源与祖传工具替换为有真实供需的资源和器具；质押是新增机制，必须支持所有权、保管与到期结算。","category":"交易与信用","choices":[{"action_hint":"custom:查验后交换","continuation":"若产权与品质无误，可完成一次明确买断。","label":"查验器具并按公开条件直接交换","requires_extension":true,"tradeoff":"资源一旦交付便失去其他用途，器具仍可能不适配。"},{"action_hint":"custom:建立质押赎回","continuation":"若双方接受，可让卖方保留赎回机会而非口头许诺。","label":"提出限期质押与赎回条件","requires_extension":true,"tradeoff":"会增加保管与追账成本，错过赎期也可能伤及关系。"},{"action_hint":"interact:decline","continuation":"若卖方日后有其他货物，可重新接触。","label":"拒绝收购祖物，结束这笔议价","requires_extension":false,"tradeoff":"双方都需寻找其他交易对象，机会期限不会暂停。"}],"conflict":"卖方要及时抓住机会又不愿永久失去祖物，你要可靠产权，也不能把对方的急迫当成品质保证。","dedupe_key":"heirloom_liquidation_for_deadline","exclusions":["卖方无权处分物件，或交易资源在当前世界中不存在。"],"followups":[{"closure":"买断交割、赎回完成或双方依法结清后结束。","development":"卖方依据实际结果与财力决定是否履行赎回。","trigger":"选拔结束或约定赎回日到来"}],"id":"WD-FR-013","npc_motives":["摊主：想帮亲属跨过眼前门槛，担心贱卖后再也赎不回。","待选亲属：需要资源，却未必清楚家人愿付出的全部代价。"],"preconditions":["玩家确有卖方所需且可转让的资源。","祖物用途与来源能被查验，选拔期限已知。"],"situation":"摊主取出本不打算出售的祖传器具，希望换你手中的稀缺资源，供亲属赶在选拔前准备。器具确有用处，她却明显不舍。","tags":["祖传物件","突破期限","亲属筹资"],"title":"拿祖物换眼前机会","variation_slots":["祖物可换为船契、旧剑或工匠工具","急需资源可换为学费、护具或通行费用"]},"content_version":"2026-10-31.1","id":"WD-FR-013","metadata":{"category":"交易与信用","dedupe_key":"heirloom_liquidation_for_deadline","source_card_id":"WD-FR-013","source_chapter_ids":["FR-0137"],"tags":["祖传物件","突破期限","亲属筹资"]},"retrieval_text":"拿祖物换眼前机会\n交易与信用\n祖传物件 突破期限 亲属筹资\n摊主取出本不打算出售的祖传器具，希望换你手中的稀缺资源，供亲属赶在选拔前准备。器具确有用处，她却明显不舍。\n卖方要及时抓住机会又不愿永久失去祖物，你要可靠产权，也不能把对方的急迫当成品质保证。\n摊主：想帮亲属跨过眼前门槛，担心贱卖后再也赎不回。\n待选亲属：需要资源，却未必清楚家人愿付出的全部代价。\n玩家确有卖方所需且可转让的资源。\n祖物用途与来源能被查验，选拔期限已知。\n卖方无权处分物件，或交易资源在当前世界中不存在。\n三分支为游戏改编；提升资源与祖传工具替换为有真实供需的资源和器具；质押是新增机制，必须支持所有权、保管与到期结算。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著突破资源转为世界中已有稀缺资格；优先规则与转让范围必须预先存在，不以原著资质结论判定玩家无望。","category":"宗门与派系","choices":[{"action_hint":"interact:ask","continuation":"若规则支持，可保留资格并让组织承担调配责任。","label":"要求说明凭证权利与分配依据","requires_extension":false,"tradeoff":"公开程序会暴露自己持证，也可能拖慢兑现。"},{"action_hint":"custom:协商资格转让","continuation":"若条款充分，可自愿转让而保留独立入门资格。","label":"让买方提出可核验的替代权益","requires_extension":true,"tradeoff":"须评估替代物能否支持自己的目标，不能只听估值。"},{"action_hint":"interact:decline","continuation":"若兑现期未过，可在搜集信息后再作决定。","label":"暂不转让，延期考虑报价","requires_extension":false,"tradeoff":"不会自动获得额外补偿，也可能错过有利报价。"}],"conflict":"组织要维护旧承诺与本期安排，失去名额者正错过关键时机；你有合法请求，却被视为突然插队的人。","dedupe_key":"legacy_entitlement_scarce_allocation","exclusions":["凭证不含该项权利，或资源足够而无实际冲突。"],"followups":[{"closure":"资格兑现、合法转让或玩家主动放弃后结束。","development":"核对实物、权限与期限，禁止把沉默视为同意。","trigger":"组织宣布交割日期或买方递交明确报价"}],"id":"WD-FR-014","npc_motives":["分配执事：想避免毁约名声，宁愿内部私下达成交换。","候补者长辈：担心晚辈错过机会，愿付代价也容易越界。"],"preconditions":["玩家持有可验证的历史凭证。","资源真实有限，且当前尚未交割给玩家。"],"situation":"你持旧凭证来兑现组织许下的稀缺资格，才发现本期名额已经分完。有人愿出价收购你的权利，执事强调必须自愿。","tags":["承诺兑现","资源分配","特权顺位"],"title":"旧凭证撞上新名额","variation_slots":["凭证可换为旧功勋、祖辈契约或救援承诺","名额可换为传送、拜师或入库资格"]},"content_version":"2026-10-31.1","id":"WD-FR-014","metadata":{"category":"宗门与派系","dedupe_key":"legacy_entitlement_scarce_allocation","source_card_id":"WD-FR-014","source_chapter_ids":["FR-0144"],"tags":["承诺兑现","资源分配","特权顺位"]},"retrieval_text":"旧凭证撞上新名额\n宗门与派系\n承诺兑现 资源分配 特权顺位\n你持旧凭证来兑现组织许下的稀缺资格，才发现本期名额已经分完。有人愿出价收购你的权利，执事强调必须自愿。\n组织要维护旧承诺与本期安排，失去名额者正错过关键时机；你有合法请求，却被视为突然插队的人。\n分配执事：想避免毁约名声，宁愿内部私下达成交换。\n候补者长辈：担心晚辈错过机会，愿付代价也容易越界。\n玩家持有可验证的历史凭证。\n资源真实有限，且当前尚未交割给玩家。\n凭证不含该项权利，或资源足够而无实际冲突。\n三分支为游戏改编；原著突破资源转为世界中已有稀缺资格；优先规则与转让范围必须预先存在，不以原著资质结论判定玩家无望。"},{"card":{"adaptation_notes":"三分支为游戏改编；保留延期被包装成寄存的结构；账目、原始证据与付款状态须独立支持，不让礼貌话自动抹去债权。","category":"交易与信用","choices":[{"action_hint":"custom:登记延期交付","continuation":"若记录被认可，日后可按明确节点催交。","label":"接受分期但要求逐项确认余款","requires_extension":true,"tradeoff":"可能让对方觉得被防备，仍要承担等待成本。"},{"action_hint":"custom:协商抵偿结算","continuation":"若完成验收，可减少暴露在权势关系中的未付余额。","label":"提出用现有实物结清部分报酬","requires_extension":true,"tradeoff":"可选物品可能并不适用，折价也需双方同意。"},{"action_hint":"interact:leave","continuation":"若找到可信中介，可自主决定是否重启协商。","label":"退出本次谈话，暂缓催索且不作寄存声明","requires_extension":false,"tradeoff":"眼前缺少报酬可用，之后追索仍需证据。"}],"conflict":"欠付者既要节省开支又要保住信用，你需要报酬和关系空间；含糊措辞会改变日后追索难度。","dedupe_key":"power_imbalanced_payment_reframing","exclusions":["报酬已全部到账，或所谓债务没有任何先前约定。"],"followups":[{"closure":"结清、双方正式和解或玩家明确放弃追索后结束。","development":"以原始约定核对余额，防止人情义务替代实物偿付。","trigger":"约定交付节点到来或欠付者提出新要求"}],"id":"WD-FR-015","npc_motives":["欠付前辈：担心承认欠账留下把柄，偏爱体面但模糊的说法。","见证者：愿替前辈圆场，也可能利用这笔亏欠交换政治支持。"],"preconditions":["双方有未结清且可核对的交易。","玩家处于较弱地位，但仍能保留记录或寻求中介。"],"situation":"一位地位高于你的交易对象已拿到你的东西，却称剩余报酬暂时不便交付，希望你当面说成自愿寄存，旁边还有他信任的见证者。","tags":["强弱交易","延期交付","体面话术"],"title":"暂存之名的拖欠","variation_slots":["报酬可换为器材、权限或工钱","中介可换为账房、族老或公会执事"]},"content_version":"2026-10-31.1","id":"WD-FR-015","metadata":{"category":"交易与信用","dedupe_key":"power_imbalanced_payment_reframing","source_card_id":"WD-FR-015","source_chapter_ids":["FR-0150"],"tags":["强弱交易","延期交付","体面话术"]},"retrieval_text":"暂存之名的拖欠\n交易与信用\n强弱交易 延期交付 体面话术\n一位地位高于你的交易对象已拿到你的东西，却称剩余报酬暂时不便交付，希望你当面说成自愿寄存，旁边还有他信任的见证者。\n欠付者既要节省开支又要保住信用，你需要报酬和关系空间；含糊措辞会改变日后追索难度。\n欠付前辈：担心承认欠账留下把柄，偏爱体面但模糊的说法。\n见证者：愿替前辈圆场，也可能利用这笔亏欠交换政治支持。\n双方有未结清且可核对的交易。\n玩家处于较弱地位，但仍能保留记录或寻求中介。\n报酬已全部到账，或所谓债务没有任何先前约定。\n三分支为游戏改编；保留延期被包装成寄存的结构；账目、原始证据与付款状态须独立支持，不让礼貌话自动抹去债权。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著器物的威能比例与境界不搬用；以可核验余量和适配条件替代，鉴定及耗损须有状态支持。","category":"机缘与代价","choices":[{"action_hint":"interact:ask","continuation":"若资料可靠，可判断它更适合保命还是长期使用。","label":"询问耗损、适配与保存记录","requires_extension":false,"tradeoff":"可能暴露自己的知识不足，卖方回答仍需验证。"},{"action_hint":"custom:约定耗损验器","continuation":"若双方承认鉴定结果，可按状态重议价格。","label":"约定承担有限耗损后共同验器","requires_extension":true,"tradeoff":"检验会增加成本，也可能只得到剩余威能的区间。"},{"action_hint":"interact:decline","continuation":"若出现更适合自身的器物，可另行比较。","label":"拒绝购买并保留资源","requires_extension":false,"tradeoff":"会错过一次短期增强手段，但无需承担未知维护成本。"}],"conflict":"商家想按潜在威力定价，你要按可用余量与实际适配判断价值；试用本身也可能耗损商品。","dedupe_key":"finite_legacy_power_purchase","exclusions":["该器物被明确设定为无限使用，或玩家完全无法驱动。"],"followups":[{"closure":"交易交割、报价失效或玩家拒绝后结束。","development":"根据真实状态修订报价，不能用稀有性代替可用性。","trigger":"验器完成或卖方补齐保存记录"}],"id":"WD-FR-016","npc_motives":["掌柜：愿解释常识争取大客户，却不想无偿承担试用耗损。","鉴定者：可判断状态范围，但不愿保证每次使用的结果。"],"preconditions":["玩家面对有代价的交易，手中资源足以议价。","世界已有会耗尽或折损的借力器物。"],"situation":"商家展示一件能让低阶使用者借来强大威能的遗器，称其珍贵稀少。你询问后得知它会消耗封存力量，剩余状态却尚未核清。","tags":["有限威能","鉴货信息","长期取舍"],"title":"强大却会耗尽的遗器","variation_slots":["遗器可换为充能护符或有限授权的机关","耗损可换为结构磨损或储能减少"]},"content_version":"2026-10-31.1","id":"WD-FR-016","metadata":{"category":"机缘与代价","dedupe_key":"finite_legacy_power_purchase","source_card_id":"WD-FR-016","source_chapter_ids":["FR-0164"],"tags":["有限威能","鉴货信息","长期取舍"]},"retrieval_text":"强大却会耗尽的遗器\n机缘与代价\n有限威能 鉴货信息 长期取舍\n商家展示一件能让低阶使用者借来强大威能的遗器，称其珍贵稀少。你询问后得知它会消耗封存力量，剩余状态却尚未核清。\n商家想按潜在威力定价，你要按可用余量与实际适配判断价值；试用本身也可能耗损商品。\n掌柜：愿解释常识争取大客户，却不想无偿承担试用耗损。\n鉴定者：可判断状态范围，但不愿保证每次使用的结果。\n玩家面对有代价的交易，手中资源足以议价。\n世界已有会耗尽或折损的借力器物。\n该器物被明确设定为无限使用，或玩家完全无法驱动。\n三分支为游戏改编；原著器物的威能比例与境界不搬用；以可核验余量和适配条件替代，鉴定及耗损须有状态支持。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著采药竞赛改为已有试炼目标；只保留上层收益与基层风险错位，拒绝加码不自动判作叛门。","category":"宗门与派系","choices":[{"action_hint":"interact:ask","continuation":"若长辈公开承诺分配，队伍才有依据评估是否争取。","label":"询问额外收益与风险由谁承担","requires_extension":false,"tradeoff":"可能被视为扫兴，但能揭示原任务与赌局的区别。"},{"action_hint":"custom:订立试炼边界","continuation":"若领队认可，可按原定安全条件放弃超额争夺。","label":"联合队友提出撤离底线与成绩上限","requires_extension":true,"tradeoff":"需要协调不同诉求，未必获得所有人支持。"},{"action_hint":"custom:申请调整试炼职责","continuation":"若存在替代岗位，可承担后勤或退出此次试炼。","label":"拒绝加码，只申请原定低风险任务","requires_extension":true,"tradeoff":"可能失去额外奖励与被看重的机会。"}],"conflict":"领队长辈想赢得私人所需，弟子要合理报酬与生还机会；赌注越大，抢成绩的压力越强。","dedupe_key":"senior_wager_externalizes_trial_risk","exclusions":["玩家并非参赛者，或收益和安全边界已充分约定。"],"followups":[{"closure":"试炼结算、岗位变更或玩家退出后结束。","development":"按已明确的边界决定追求成绩或撤回，不自动服从赌局。","trigger":"试炼出现超出原目标的争夺机会"}],"id":"WD-FR-017","npc_motives":["本方长辈：渴求稀缺资源，容易把弟子排名当作个人胜负。","队内骨干：担心临时加码打乱原有撤离与分工安排。"],"preconditions":["多人试炼尚未开始，玩家可决定是否参与加码。","队伍已有基本任务与返程条件。"],"situation":"试炼开始前，几位长辈以各队成绩押上珍贵资源，又临时扩大赌局。弟子承担采集与探索的危险，却不清楚额外收益如何分配。","tags":["声望竞逐","风险转嫁","试炼成绩"],"title":"长辈的赌局落在弟子身上","variation_slots":["成绩可换为遗迹线索、救援人数或修复进度","赌注可换为资源、声誉或长期劳务"]},"content_version":"2026-10-31.1","id":"WD-FR-017","metadata":{"category":"宗门与派系","dedupe_key":"senior_wager_externalizes_trial_risk","source_card_id":"WD-FR-017","source_chapter_ids":["FR-0176"],"tags":["声望竞逐","风险转嫁","试炼成绩"]},"retrieval_text":"长辈的赌局落在弟子身上\n宗门与派系\n声望竞逐 风险转嫁 试炼成绩\n试炼开始前，几位长辈以各队成绩押上珍贵资源，又临时扩大赌局。弟子承担采集与探索的危险，却不清楚额外收益如何分配。\n领队长辈想赢得私人所需，弟子要合理报酬与生还机会；赌注越大，抢成绩的压力越强。\n本方长辈：渴求稀缺资源，容易把弟子排名当作个人胜负。\n队内骨干：担心临时加码打乱原有撤离与分工安排。\n多人试炼尚未开始，玩家可决定是否参与加码。\n队伍已有基本任务与返程条件。\n玩家并非参赛者，或收益和安全边界已充分约定。\n三分支为游戏改编；原著采药竞赛改为已有试炼目标；只保留上层收益与基层风险错位，拒绝加码不自动判作叛门。"},{"card":{"adaptation_notes":"三分支为游戏改编；旧物只形成对方信念，不直接增加真实战力；资料完整度、来源与互换内容须单独记录。","category":"身份与秘密","choices":[{"action_hint":"custom:分层交换路线资料","continuation":"若双方资料相符，可再决定是否交换更敏感部分。","label":"只交换可互相核对的公共路段","requires_extension":true,"tradeoff":"无法立即得到核心捷径，但能较低成本建立可信度。"},{"action_hint":"interact:ask","continuation":"若其说明旧主习惯，可帮助判断是否还有追索风险。","label":"询问对方认出旧物的依据","requires_extension":false,"tradeoff":"可能让对方察觉自己与原主关系没有想象中紧密。"},{"action_hint":"evade:withdraw","continuation":"若退路畅通，可另从更可信渠道了解险地。","label":"保持戒备并撤离谈话范围","requires_extension":false,"tradeoff":"放弃当次资料互补，也不保证对方不继续观察。"}],"conflict":"对方想借情报探清你的底牌，你要补足路线知识；解释太多会失去威慑，删节过度则可能换来无用资料。","dedupe_key":"trophy_reputation_partial_information","exclusions":["对方已确知玩家全部实力，或资料早已共同公开。"],"followups":[{"closure":"资料核验完毕、交易终止或双方分道后结束。","development":"用现场事实验证资料删节程度，决定是否继续有限合作。","trigger":"玩家到达一段已交换路线或再次遇见对方"}],"id":"WD-FR-018","npc_motives":["试探者：怀疑旧物不代表真正实力，却不愿亲自冒险验证。","资料掌握者：想了解自己不熟悉的区域，并保护独有捷径。"],"preconditions":["玩家持有来源可辨的物件，且与其原主有真实经历。","双方尚未开战，各自拥有不同的可交换资料。"],"situation":"陌生修士认出你身上一件来自危险人物的旧物，因而高估你的实力，暂缓敌意并邀你交换险地资料；他始终保持可退的距离。","tags":["实力误判","敌意降温","情报删节"],"title":"战利品带来的错估","variation_slots":["旧物可换为旗号、坐骑或破损令牌","资料可换为巡逻时间与危险生物分布"]},"content_version":"2026-10-31.1","id":"WD-FR-018","metadata":{"category":"身份与秘密","dedupe_key":"trophy_reputation_partial_information","source_card_id":"WD-FR-018","source_chapter_ids":["FR-0193"],"tags":["实力误判","敌意降温","情报删节"]},"retrieval_text":"战利品带来的错估\n身份与秘密\n实力误判 敌意降温 情报删节\n陌生修士认出你身上一件来自危险人物的旧物，因而高估你的实力，暂缓敌意并邀你交换险地资料；他始终保持可退的距离。\n对方想借情报探清你的底牌，你要补足路线知识；解释太多会失去威慑，删节过度则可能换来无用资料。\n试探者：怀疑旧物不代表真正实力，却不愿亲自冒险验证。\n资料掌握者：想了解自己不熟悉的区域，并保护独有捷径。\n玩家持有来源可辨的物件，且与其原主有真实经历。\n双方尚未开战，各自拥有不同的可交换资料。\n对方已确知玩家全部实力，或资料早已共同公开。\n三分支为游戏改编；旧物只形成对方信念，不直接增加真实战力；资料完整度、来源与互换内容须单独记录。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著阵法威能比例改为逐项可验证功能；资助、验收及升级归属均为新增状态，不写必定研发成功。","category":"交易与信用","choices":[{"action_hint":"custom:按现状购买原型","continuation":"若试验满足需求，可立即使用并将升级另行商谈。","label":"按现有功能验收购买原型","requires_extension":true,"tradeoff":"可能承担维护难题，也无法要求未来改进免费交付。"},{"action_hint":"custom:建立研发分期资助","continuation":"若阶段成果可核验，可逐步交付而非一次赌未来。","label":"用分段资助换取公开里程碑","requires_extension":true,"tradeoff":"资源会被长期占用，工匠也可能无法按期改进。"},{"action_hint":"interact:decline","continuation":"若成品以后进入市场，可再按当时条件评估。","label":"拒绝参与研发交易","requires_extension":false,"tradeoff":"放弃潜在技术先机，但保留急需资源的其他用途。"}],"conflict":"工匠想按未来潜力估价，你只愿为可用功能付费；急用期限又使漫长研发担保难以兑现。","dedupe_key":"prototype_present_value_future_promise","exclusions":["工匠只提供设想没有实物，或当前功能完全不适配。"],"followups":[{"closure":"现状交割、研发结项或双方中止后结束。","development":"按实际功能结算，未完成部分可终止资助而非强迫追加。","trigger":"原型验收或约定阶段成果到期"}],"id":"WD-FR-019","npc_motives":["工匠：急需资源帮助合作者，真心相信技术还能改进。","主持者：要保证当场可交付，不愿让未来承诺扰乱市场定价。"],"preconditions":["玩家有明确防护需求，并能提供工匠所需资源。","原型确有可演示的部分功能。"],"situation":"工匠拿一套只完成部分功能的防护器具筹集急用资源，公开交易失败。其他买家等成熟成品，你却发现现有功能或许已能解决眼前问题。","tags":["技术原型","救急筹资","现值与承诺"],"title":"未完成的技术能否救急","variation_slots":["原型可换为运输机关或识别装置","急用资源可换为医疗、维修或赎回费用"]},"content_version":"2026-10-31.1","id":"WD-FR-019","metadata":{"category":"交易与信用","dedupe_key":"prototype_present_value_future_promise","source_card_id":"WD-FR-019","source_chapter_ids":["FR-0226"],"tags":["技术原型","救急筹资","现值与承诺"]},"retrieval_text":"未完成的技术能否救急\n交易与信用\n技术原型 救急筹资 现值与承诺\n工匠拿一套只完成部分功能的防护器具筹集急用资源，公开交易失败。其他买家等成熟成品，你却发现现有功能或许已能解决眼前问题。\n工匠想按未来潜力估价，你只愿为可用功能付费；急用期限又使漫长研发担保难以兑现。\n工匠：急需资源帮助合作者，真心相信技术还能改进。\n主持者：要保证当场可交付，不愿让未来承诺扰乱市场定价。\n玩家有明确防护需求，并能提供工匠所需资源。\n原型确有可演示的部分功能。\n工匠只提供设想没有实物，或当前功能完全不适配。\n三分支为游戏改编；原著阵法威能比例改为逐项可验证功能；资助、验收及升级归属均为新增状态，不写必定研发成功。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著亲密修炼安排改成会共享隐私的长期合作；不搬用外貌偏好与流言作为人物价值判断，任何绑定需双方同意。","category":"师徒与控制","choices":[{"action_hint":"interact:ask","continuation":"若双方愿意，可判断是否存在有限协作方式。","label":"请求与另一当事人先谈合作边界","requires_extension":false,"tradeoff":"谈话可能揭示不相容目标，也不能据表情替对方作决定。"},{"action_hint":"custom:改订有限研习安排","continuation":"若三方认可，可保留合作机会并隔离私人修炼部分。","label":"提出短期公开研习替代长期绑定","requires_extension":true,"tradeoff":"师长可能觉得不足以建立关系，候选者也可拒绝。"},{"action_hint":"interact:decline","continuation":"若对方接受自主决定，关系可转为普通同门往来。","label":"明确拒绝长期共修","requires_extension":false,"tradeoff":"会令师长失望，需要自行承担解释压力。"}],"conflict":"师长要兑现对外承诺并巩固关系，你要保留修炼隐私；另一个当事人的意愿也不能由两位师长替代。","dedupe_key":"mentor_prestige_vs_student_privacy","exclusions":["双方早已自由同意共修，或合作无需共享任何私人生活。"],"followups":[{"closure":"安排撤销、有限合作另立或双方自愿订约后结束。","development":"重新核对同意范围，不把沉默或师命当作成立依据。","trigger":"师长要求正式答复或双方完成边界谈话"}],"id":"WD-FR-020","npc_motives":["授业者：把联合视为弟子受益，不愿在同辈面前失信。","共修候选者：可能另有计划，却担心直接反对得罪自己的师长。"],"preconditions":["师长已对外作出未经玩家同意的长期安排。","玩家确有私人修炼限制，且尚未成立正式关系。"],"situation":"师长宣布已替你答应与另一门人的长期共修，认为双方师门都能得益。你有不宜共享的修炼安排，对方似乎也并非情愿。","tags":["师门联结","修炼隐私","先斩后奏"],"title":"师长已替你应下的共修","variation_slots":["共修可换为长期搭档或共用工坊","隐私可换为独门技艺与身份保密"]},"content_version":"2026-10-31.1","id":"WD-FR-020","metadata":{"category":"师徒与控制","dedupe_key":"mentor_prestige_vs_student_privacy","source_card_id":"WD-FR-020","source_chapter_ids":["FR-0244"],"tags":["师门联结","修炼隐私","先斩后奏"]},"retrieval_text":"师长已替你应下的共修\n师徒与控制\n师门联结 修炼隐私 先斩后奏\n师长宣布已替你答应与另一门人的长期共修，认为双方师门都能得益。你有不宜共享的修炼安排，对方似乎也并非情愿。\n师长要兑现对外承诺并巩固关系，你要保留修炼隐私；另一个当事人的意愿也不能由两位师长替代。\n授业者：把联合视为弟子受益，不愿在同辈面前失信。\n共修候选者：可能另有计划，却担心直接反对得罪自己的师长。\n师长已对外作出未经玩家同意的长期安排。\n玩家确有私人修炼限制，且尚未成立正式关系。\n双方早已自由同意共修，或合作无需共享任何私人生活。\n三分支为游戏改编；原著亲密修炼安排改成会共享隐私的长期合作；不搬用外貌偏好与流言作为人物价值判断，任何绑定需双方同意。"},{"card":{"adaptation_notes":"三分支为游戏改编；专属令牌改为通道必需的保护条件；结构记录、修复与未知地点探索需扩展，不能用普通旅行直接跳到未声明地点。","category":"探索与禁制","choices":[{"action_hint":"custom:记录通道结构","continuation":"若识别出修复条件，可再决定是否公开位置。","label":"记录可见结构后请行家评估","requires_extension":true,"tradeoff":"资料可能不足，且分享纹样会透露部分发现。"},{"action_hint":"custom:调查传送条件","continuation":"若发现保护条件，可排除部分盲试风险而非保证抵达。","label":"先核验配套信物的用途与承载限制","requires_extension":true,"tradeoff":"寻找资料会形成额外准备成本，未必能查全。"},{"action_hint":"evade:withdraw","continuation":"若地点没有被毁，可日后自行决定是否返回。","label":"沿既有出口撤离，暂不动用通道","requires_extension":false,"tradeoff":"暂时失去捷径，战区中的常规撤退仍可能艰难。"}],"conflict":"你需要脱离战区，修复者需要足够资料；公布位置可换来帮助，也会失去这条后路的独占性。","dedupe_key":"broken_long_distance_escape_route","exclusions":["目的地与安全性已全部验证，或没有任何可恢复结构。"],"followups":[{"closure":"通道方案被验证采用、主动封存或玩家改道后结束。","development":"比较修复条件与撤离窗口，允许选择其他路线。","trigger":"行家提出修复清单或外部战线发生已知变化"}],"id":"WD-FR-021","npc_motives":["修复行家：对失传结构感兴趣，但不能凭残图保证安全。","争夺者：若得知位置，可能将通道作为势力迁移资源。"],"preconditions":["通道位置已发现且有部分结构可辨。","玩家存在远行需求，现场仍有可用的普通撤退路线。"],"situation":"你在险地发现失效的远距通道与一件疑似配套信物。外界战事正逼近，修复可能打开新退路，但目的地、承载限制与返回方式都未明。","tags":["未知目的地","残阵修复","撤离后路"],"title":"损坏的远方出口","variation_slots":["通道可换为旧航路、地下门或跨界渡口","信物可换为校准装置或保护器具"]},"content_version":"2026-10-31.1","id":"WD-FR-021","metadata":{"category":"探索与禁制","dedupe_key":"broken_long_distance_escape_route","source_card_id":"WD-FR-021","source_chapter_ids":["FR-0271"],"tags":["未知目的地","残阵修复","撤离后路"]},"retrieval_text":"损坏的远方出口\n探索与禁制\n未知目的地 残阵修复 撤离后路\n你在险地发现失效的远距通道与一件疑似配套信物。外界战事正逼近，修复可能打开新退路，但目的地、承载限制与返回方式都未明。\n你需要脱离战区，修复者需要足够资料；公布位置可换来帮助，也会失去这条后路的独占性。\n修复行家：对失传结构感兴趣，但不能凭残图保证安全。\n争夺者：若得知位置，可能将通道作为势力迁移资源。\n通道位置已发现且有部分结构可辨。\n玩家存在远行需求，现场仍有可用的普通撤退路线。\n目的地与安全性已全部验证，或没有任何可恢复结构。\n三分支为游戏改编；专属令牌改为通道必需的保护条件；结构记录、修复与未知地点探索需扩展，不能用普通旅行直接跳到未声明地点。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著试图暗中杀敌的打算只作来源背景；游戏将承诺拆成调查与后续决定，不把旧情直接兑换为必须杀人的任务。","category":"凡俗与旧情","choices":[{"action_hint":"interact:ask","continuation":"若证据指向具体责任人，可再评估合法交涉路径。","label":"先询问失踪经过与已知证据","requires_extension":false,"tradeoff":"可能让故人觉得迟疑，但能区分失踪、战死与谋害。"},{"action_hint":"custom:建立有限调查承诺","continuation":"若支持关系与事实查清，可选择交涉、救人或继续拒绝。","label":"提出有条件的调查承诺","requires_extension":true,"tradeoff":"会占用将来精力，必须说明不等于保证报仇。"},{"action_hint":"interact:decline","continuation":"若故人愿意，可保留普通联络而不继续追讨。","label":"拒绝介入复仇并说明能力边界","requires_extension":false,"tradeoff":"可能伤及旧情，也无法消除对方的不甘。"}],"conflict":"故人想结束多年无力感，你既重旧情又不愿无证卷入势力争端；失踪亲人的遭遇尚未全被确认。","dedupe_key":"personal_grievance_proxy_power_boundary","exclusions":["目标与受害事件已证实无关，或求助者不愿进一步核查。"],"followups":[{"closure":"调查完成、当事人撤回或玩家明确无法继续后结束。","development":"重新判断责任与可行范围，承诺可因事实变化而结束。","trigger":"出现失踪者消息或可核验的幕后支持线索"}],"id":"WD-FR-022","npc_motives":["旧识：把你视为少数可求助的人，急切中容易把希望当承诺。","地方首领：依靠背后支持维持地位，会把个人遇袭解释为阵营挑衅。"],"preconditions":["玩家与求助者有真实旧交。","目标背后存在待核验的支持关系，且责任证据不完整。"],"situation":"旧日相识请你惩治毁掉其家业的凡俗首领。你能对付此人，却发现其背后可能有别派支持，私人援手因此可能变成派系冲突。","tags":["故人复仇","代理势力","有限承诺"],"title":"旧情求助触及势力边界","variation_slots":["旧识可换为童年同伴或旧商路伙伴","目标可换为地方官、庄主或公会头领"]},"content_version":"2026-10-31.1","id":"WD-FR-022","metadata":{"category":"凡俗与旧情","dedupe_key":"personal_grievance_proxy_power_boundary","source_card_id":"WD-FR-022","source_chapter_ids":["FR-0283"],"tags":["故人复仇","代理势力","有限承诺"]},"retrieval_text":"旧情求助触及势力边界\n凡俗与旧情\n故人复仇 代理势力 有限承诺\n旧日相识请你惩治毁掉其家业的凡俗首领。你能对付此人，却发现其背后可能有别派支持，私人援手因此可能变成派系冲突。\n故人想结束多年无力感，你既重旧情又不愿无证卷入势力争端；失踪亲人的遭遇尚未全被确认。\n旧识：把你视为少数可求助的人，急切中容易把希望当承诺。\n地方首领：依靠背后支持维持地位，会把个人遇袭解释为阵营挑衅。\n玩家与求助者有真实旧交。\n目标背后存在待核验的支持关系，且责任证据不完整。\n目标与受害事件已证实无关，或求助者不愿进一步核查。\n三分支为游戏改编；原著试图暗中杀敌的打算只作来源背景；游戏将承诺拆成调查与后续决定，不把旧情直接兑换为必须杀人的任务。"},{"card":{"adaptation_notes":"三分支为游戏改编；不复制原著终身追杀规定；后卫责任、组织信任与脱险分别记录，撤退必须使用危险撤离语义。","category":"追逐与藏身","choices":[{"action_hint":"interact:ask","continuation":"若领队提供可信接应，可与同组约定不持续恋战。","label":"核对会合点并请求明确撤退信号","requires_extension":false,"tradeoff":"可能被认为拖延，却能揭示任务是否有可执行终点。"},{"action_hint":"custom:执行有限后卫行动","continuation":"若敌人被延缓且退路未断，可转往约定会合点。","label":"组织短程牵制后依约脱离","requires_extension":true,"tradeoff":"需要同伴配合与真实地形，行动失败仍可能暴露。"},{"action_hint":"evade:withdraw","continuation":"若脱离追击，可自行选择新落脚处，不必返回大队。","label":"放弃后卫职责并沿可行路线撤退","requires_extension":false,"tradeoff":"可能失去组织庇护与信任，携带同伴须各自同意。"}],"conflict":"领队要保全大队与重建力量，后卫要可执行的生还路径；玩家的求道计划未必与重建事务一致。","dedupe_key":"rear_guard_evacuating_faction_exit","exclusions":["没有追兵，或地图仅用于强迫进入无出口死地。"],"followups":[{"closure":"抵达安全地带、完成会合或独立脱险后结束。","development":"按实际战况评估继续掩护或脱离，不能无限延长任务。","trigger":"撤退信号出现、追兵改道或接应期限届满"}],"id":"WD-FR-023","npc_motives":["撤离领队：宁愿牺牲部分灵活人手，也要保住组织骨干。","同组后卫：愿争取队伍存活，但想知道接应是否真实存在。"],"preconditions":["追兵位置与撤离方向已有可用情报。","玩家已被分入后卫，现场仍存在可评估退路。"],"situation":"战败撤离途中，领队将你编入临时后卫，要求引开追兵再按图会合。大队已先行，你既要判断掩护是否可行，也担心此后被长期绑定。","tags":["战败迁徙","后卫诱敌","个人前程"],"title":"撤离队伍中的后卫名单","variation_slots":["撤离组织可换为商队、城防或难民队","地形可换为山隘、水道或分岔路"]},"content_version":"2026-10-31.1","id":"WD-FR-023","metadata":{"category":"追逐与藏身","dedupe_key":"rear_guard_evacuating_faction_exit","source_card_id":"WD-FR-023","source_chapter_ids":["FR-0347"],"tags":["战败迁徙","后卫诱敌","个人前程"]},"retrieval_text":"撤离队伍中的后卫名单\n追逐与藏身\n战败迁徙 后卫诱敌 个人前程\n战败撤离途中，领队将你编入临时后卫，要求引开追兵再按图会合。大队已先行，你既要判断掩护是否可行，也担心此后被长期绑定。\n领队要保全大队与重建力量，后卫要可执行的生还路径；玩家的求道计划未必与重建事务一致。\n撤离领队：宁愿牺牲部分灵活人手，也要保住组织骨干。\n同组后卫：愿争取队伍存活，但想知道接应是否真实存在。\n追兵位置与撤离方向已有可用情报。\n玩家已被分入后卫，现场仍存在可评估退路。\n没有追兵，或地图仅用于强迫进入无出口死地。\n三分支为游戏改编；不复制原著终身追杀规定；后卫责任、组织信任与脱险分别记录，撤退必须使用危险撤离语义。"},{"card":{"adaptation_notes":"三分支为游戏改编；不移植原著体质病因与寿数；承诺必须记录可判断条件和终止方式，不因获得力量自动强制复仇。","category":"同盟与背叛","choices":[{"action_hint":"custom:登记条件性承诺","continuation":"若未来条件满足，可重新核验事实并决定履约方式。","label":"明确能力门槛后作有限承诺","requires_extension":true,"tradeoff":"会形成长期责任，门槛不能含糊到永远无法判断。"},{"action_hint":"custom:托管证据线索","continuation":"若遇到合适见证者，可经其同意转交资料。","label":"只承诺保留证据与寻找适合的求助者","requires_extension":true,"tradeoff":"可能无法满足对方最深愿望，但承担范围更可控。"},{"action_hint":"interact:decline","continuation":"若陪伴者仍愿沟通，可只完成当下告别。","label":"拒绝作出未来承诺，坦诚说明缘由","requires_extension":false,"tradeoff":"对方可能失望，关系也可能止于这次相见。"}],"conflict":"托付者需要希望与被记住，你不愿用空话安慰，却也不想把余生锁进无法衡量的责任。","dedupe_key":"bounded_future_promise_capacity_threshold","exclusions":["托付者要求无条件立即赴死，或玩家已明确没有继续往来的意愿。"],"followups":[{"closure":"约定义务完成、托付撤回或条件已永久不可能时结束。","development":"核实目标、受害者与局势是否变化，再确认原承诺的范围。","trigger":"玩家主动重访旧档，或约定能力条件实际满足"}],"id":"WD-FR-024","npc_motives":["托付者：其他求援渠道已尽，希望至少有人保留此事的记忆。","陪伴者：希望留下真实资料，也担心复仇掩盖最后的生活安排。"],"preconditions":["双方已有可支撑托付的信任。","目标超出玩家当前能力，且没有迫在眼前必须行动的危险。"],"situation":"一位处境衰弱的旧识把未了之事托付给你，明知你目前无法对抗其仇敌，仍请求一个未来可能兑现的承诺，不要求强制誓约。","tags":["临终托付","实力门槛","承诺边界"],"title":"只在有能力时兑现的诺言","variation_slots":["未了事可换为查明冤案或收回遗物","能力门槛可换为证据、身份或资源"]},"content_version":"2026-10-31.1","id":"WD-FR-024","metadata":{"category":"同盟与背叛","dedupe_key":"bounded_future_promise_capacity_threshold","source_card_id":"WD-FR-024","source_chapter_ids":["FR-0352"],"tags":["临终托付","实力门槛","承诺边界"]},"retrieval_text":"只在有能力时兑现的诺言\n同盟与背叛\n临终托付 实力门槛 承诺边界\n一位处境衰弱的旧识把未了之事托付给你，明知你目前无法对抗其仇敌，仍请求一个未来可能兑现的承诺，不要求强制誓约。\n托付者需要希望与被记住，你不愿用空话安慰，却也不想把余生锁进无法衡量的责任。\n托付者：其他求援渠道已尽，希望至少有人保留此事的记忆。\n陪伴者：希望留下真实资料，也担心复仇掩盖最后的生活安排。\n双方已有可支撑托付的信任。\n目标超出玩家当前能力，且没有迫在眼前必须行动的危险。\n托付者要求无条件立即赴死，或玩家已明确没有继续往来的意愿。\n三分支为游戏改编；不移植原著体质病因与寿数；承诺必须记录可判断条件和终止方式，不因获得力量自动强制复仇。"},{"card":{"adaptation_notes":"三分支为游戏改编；远距迁移是前置事实；后续交通先建立地点与路线，不能用普通道路动作生成未声明目的地。","category":"突破与远行","choices":[{"action_hint":"custom:示意请求接船","continuation":"若船方回应，可先核对目的港与搭乘条件。","label":"在安全距离示意并请求交流","requires_extension":true,"tradeoff":"会暴露自己的存在，船方未必愿意停船。"},{"action_hint":"interact:observe","continuation":"若发现正常商运迹象，可更有依据地决定是否接触。","label":"辨认船只行为与牵引物状态","requires_extension":false,"tradeoff":"可见信息有限，观察不能直接判断整片海域安全。"},{"action_hint":"evade:withdraw","continuation":"若安全返回，可调整探索方向而不必盲目追船。","label":"撤回可定位的临时落脚点","requires_extension":false,"tradeoff":"错过这艘船，仍需解决后续航路与补给问题。"}],"conflict":"你急需航路与补给，船上人要保住航程和货物；贸然接近可能被当成截船者。","dedupe_key":"unmapped_arrival_contact_local_transport","exclusions":["玩家已有可靠当地地图，或船只明确处于敌对追击中。"],"followups":[{"closure":"抵达首个可靠落脚处或玩家终止追船后结束。","development":"只将被确认的港口加入后续路线，未知海域仍需探索。","trigger":"船方回应信号或玩家获得当地航路说明"}],"id":"WD-FR-025","npc_motives":["船主：愿结识有能力的旅人，但害怕来客带来纠纷。","领航者：熟悉当地航路，想避免因沟通误会改变既定航程。"],"preconditions":["玩家已抵达未知地区，并有可定位的临时落脚点。","具备接近船只和返回的基本能力。"],"situation":"远距迁移把你带到孤岛，原有地图失去作用。试探附近海面时，一艘使用陌生牵引方式的商船出现，你仍能辨认返回孤岛的方向。","tags":["异地落脚","航路求助","陌生运输"],"title":"远行后的陌生海面","variation_slots":["海面可换为荒漠、浮岛或陌生边境","船只可换为商队与驮兽队"]},"content_version":"2026-10-31.1","id":"WD-FR-025","metadata":{"category":"突破与远行","dedupe_key":"unmapped_arrival_contact_local_transport","source_card_id":"WD-FR-025","source_chapter_ids":["FR-0364"],"tags":["异地落脚","航路求助","陌生运输"]},"retrieval_text":"远行后的陌生海面\n突破与远行\n异地落脚 航路求助 陌生运输\n远距迁移把你带到孤岛，原有地图失去作用。试探附近海面时，一艘使用陌生牵引方式的商船出现，你仍能辨认返回孤岛的方向。\n你急需航路与补给，船上人要保住航程和货物；贸然接近可能被当成截船者。\n船主：愿结识有能力的旅人，但害怕来客带来纠纷。\n领航者：熟悉当地航路，想避免因沟通误会改变既定航程。\n玩家已抵达未知地区，并有可定位的临时落脚点。\n具备接近船只和返回的基本能力。\n玩家已有可靠当地地图，或船只明确处于敌对追击中。\n三分支为游戏改编；远距迁移是前置事实；后续交通先建立地点与路线，不能用普通道路动作生成未声明目的地。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著岛屿政策变成明确地区规则；担保效力、居留期限与服务范围需显式支持，不能凭口头许诺生成身份。","category":"交易与信用","choices":[{"action_hint":"interact:ask","continuation":"若存在费用更高但自由的临住途径，可重新衡量交易。","label":"先询问临住、定居与其他保人的差别","requires_extension":false,"tradeoff":"对方可能不愿详谈替代渠道，信息仍需独立核验。"},{"action_hint":"custom:核验后订立担保服务","continuation":"若风险可承受，可订立一次性服务与明确担保手续。","label":"以核验对手与担保资格为接约条件","requires_extension":true,"tradeoff":"商人必须额外准备材料，争夺期限可能不等人。"},{"action_hint":"custom:结清搭乘拒绝加码","continuation":"若原搭乘款结清，可继续寻找独立的落脚渠道。","label":"拒绝挑战，另议原定搭乘费用","requires_extension":true,"tradeoff":"失去这位现成保人，安家成本或等待可能增加。"}],"conflict":"商人要挽回已投入的成本，你需要安家却不愿为信息不全的挑战背风险；担保并不等于永久服从。","dedupe_key":"residency_sponsor_bundled_service","exclusions":["当地没有相关门槛，或商人无法提供所称担保。"],"followups":[{"closure":"担保落实、临住确定或交易终止后结束。","development":"按已知规则分别处理服务与居留，不将胜负自动等同永久身份。","trigger":"挑战报名截止或担保机关要求核验"}],"id":"WD-FR-026","npc_motives":["商人：若失去经营资格就可能破产，愿拿未来收益换眼前帮手。","本地介绍人：既受雇于商人，也怕隐瞒制度导致信任破裂。"],"preconditions":["玩家确为外来者，定居制度已存在。","商人拥有合法担保资格，挑战尚可退出。"],"situation":"载你到新地的商人希望你替他参加资格争夺，遭拒后才提出定居担保。你由此发现，正式落脚与使用优质资源还存在先前未告知的门槛。","tags":["外来定居","担保依赖","行商竞争"],"title":"保人背后的安家门槛","variation_slots":["定居权益可换为市民资格、行会许可或灵地租赁","挑战可换为运力考核或公开技艺竞争"]},"content_version":"2026-10-31.1","id":"WD-FR-026","metadata":{"category":"交易与信用","dedupe_key":"residency_sponsor_bundled_service","source_card_id":"WD-FR-026","source_chapter_ids":["FR-0367"],"tags":["外来定居","担保依赖","行商竞争"]},"retrieval_text":"保人背后的安家门槛\n交易与信用\n外来定居 担保依赖 行商竞争\n载你到新地的商人希望你替他参加资格争夺，遭拒后才提出定居担保。你由此发现，正式落脚与使用优质资源还存在先前未告知的门槛。\n商人要挽回已投入的成本，你需要安家却不愿为信息不全的挑战背风险；担保并不等于永久服从。\n商人：若失去经营资格就可能破产，愿拿未来收益换眼前帮手。\n本地介绍人：既受雇于商人，也怕隐瞒制度导致信任破裂。\n玩家确为外来者，定居制度已存在。\n商人拥有合法担保资格，挑战尚可退出。\n当地没有相关门槛，或商人无法提供所称担保。\n三分支为游戏改编；原著岛屿政策变成明确地区规则；担保效力、居留期限与服务范围需显式支持，不能凭口头许诺生成身份。"},{"card":{"adaptation_notes":"三分支为游戏改编；不让一次质疑自动洗清参战责任；敌我关系、已造成损害和内应身份分别推进，撤离不保证追责消失。","category":"同盟与背叛","choices":[{"action_hint":"custom:提出战场停火核证","continuation":"若双方同意短暂停火，可分开核验追踪与目击来源。","label":"要求各方说明指控的独立证据","requires_extension":true,"tradeoff":"开口可能吸引攻击，且停手并不能抹去既有责任。"},{"action_hint":"custom:组织停攻保全证词","continuation":"若保持阵形，可避免继续扩大误伤并争取调查空间。","label":"与愿停手者后撤并保存矛盾证词","requires_extension":true,"tradeoff":"会削弱己方攻势，也可能被煽动者指责动摇。"},{"action_hint":"evade:withdraw","continuation":"若成功撤出，可选择向中立方提供所见或彻底离开。","label":"脱离战团，退出当前委托","requires_extension":false,"tradeoff":"可能失去报酬，自己已经参与的行为仍须面对解释。"}],"conflict":"复仇者急于为损失讨说法，被袭者要保护弟子；煽动者试图让已经发生的伤亡掩盖最初证据漏洞。","dedupe_key":"revenge_raid_false_target_escalation","exclusions":["全部身份与责任已查实，或双方完全无法沟通。"],"followups":[{"closure":"误认查清、委托解除或玩家安全退出后结束。","development":"据可见行为追查误导环节，受害方赔偿与责任另行协商。","trigger":"双方对照证据或出现继续破坏停火的人"}],"id":"WD-FR-027","npc_motives":["讨伐主事者：既怀疑受骗，也担心停手被解释为软弱。","被袭首领：即使愿听解释，也无法忽略已造成的真实伤亡。"],"preconditions":["战斗已经发生，但双方仍存在短暂交谈窗口。","玩家掌握至少一处具体情报矛盾，有可行撤退方向。"],"situation":"受雇参与讨伐后，你发现被袭者不认指控，且行动方式与委托情报不符。己方主事者要求暂缓，却有熟悉内情的人不断抢先动手。","tags":["错误归罪","战场核证","内应煽动"],"title":"被复仇理由推向误战","variation_slots":["讨伐可换为缉盗、夺货或惩戒叛徒","矛盾可换为口供、货物标记或行动时间"]},"content_version":"2026-10-31.1","id":"WD-FR-027","metadata":{"category":"同盟与背叛","dedupe_key":"revenge_raid_false_target_escalation","source_card_id":"WD-FR-027","source_chapter_ids":["FR-0404"],"tags":["错误归罪","战场核证","内应煽动"]},"retrieval_text":"被复仇理由推向误战\n同盟与背叛\n错误归罪 战场核证 内应煽动\n受雇参与讨伐后，你发现被袭者不认指控，且行动方式与委托情报不符。己方主事者要求暂缓，却有熟悉内情的人不断抢先动手。\n复仇者急于为损失讨说法，被袭者要保护弟子；煽动者试图让已经发生的伤亡掩盖最初证据漏洞。\n讨伐主事者：既怀疑受骗，也担心停手被解释为软弱。\n被袭首领：即使愿听解释，也无法忽略已造成的真实伤亡。\n战斗已经发生，但双方仍存在短暂交谈窗口。\n玩家掌握至少一处具体情报矛盾，有可行撤退方向。\n全部身份与责任已查实，或双方完全无法沟通。\n三分支为游戏改编；不让一次质疑自动洗清参战责任；敌我关系、已造成损害和内应身份分别推进，撤离不保证追责消失。"},{"card":{"adaptation_notes":"三分支为游戏改编；公开名号与真实义务分开建模；不采用原著以门人为附加报酬的条件，任何人员加入须独立自愿。","category":"宗门与派系","choices":[{"action_hint":"custom:订立名义职务","continuation":"若对方接受，可建立有边界且可撤回的公开联系。","label":"限定可公开措辞与挂名期限","requires_extension":true,"tradeoff":"越清楚的免责声明越可能削弱组织想要的威慑。"},{"action_hint":"custom:订立单次公开援助","continuation":"若服务完成，可结清报酬，不延伸为常驻职责。","label":"只出售一次公开援助服务","requires_extension":true,"tradeoff":"需要实际投入，组织也失去长期借名的便利。"},{"action_hint":"interact:decline","continuation":"若仍愿普通交易，可另以独立价格商谈。","label":"拒绝挂名并放弃该项报酬","requires_extension":false,"tradeoff":"稀缺物可能另寻买家，组织也需寻找其他保护。"}],"conflict":"组织要可信威慑，你要资源与自主；内部限定越宽松，对外宣传越容易超过你真实愿意承担的责任。","dedupe_key":"nominal_affiliation_public_deterrence","exclusions":["玩家已受同一组织无条件指挥，或对外完全没有可辨身份。"],"followups":[{"closure":"期限届满、声明撤回或单次服务结清后结束。","development":"比对授权范围，超出部分可纠正、重议或终止。","trigger":"组织以玩家名义发布声明或请求第一次实际出手"}],"id":"WD-FR-028","npc_motives":["组织主事者：需要阻止邻近势力趁虚夺产，不一定付得起长期护卫。","外部竞争者：会试探这层联系究竟是名义还是实际联盟。"],"preconditions":["玩家有外界可识别的声望或实力。","组织确有保护空缺，并能支付约定报酬。"],"situation":"失去强者庇护的小组织想用珍贵资源请你挂名，借声望度过虚弱期。他们称无需日常听命，但外界可能把你的名号理解成全面担保。","tags":["名义职务","声望担保","组织危机"],"title":"借你的名头撑过空缺","variation_slots":["头衔可换为客卿、顾问或荣誉护法","交换资源可换为藏书、材料或商路权限"]},"content_version":"2026-10-31.1","id":"WD-FR-028","metadata":{"category":"宗门与派系","dedupe_key":"nominal_affiliation_public_deterrence","source_card_id":"WD-FR-028","source_chapter_ids":["FR-0410"],"tags":["名义职务","声望担保","组织危机"]},"retrieval_text":"借你的名头撑过空缺\n宗门与派系\n名义职务 声望担保 组织危机\n失去强者庇护的小组织想用珍贵资源请你挂名，借声望度过虚弱期。他们称无需日常听命，但外界可能把你的名号理解成全面担保。\n组织要可信威慑，你要资源与自主；内部限定越宽松，对外宣传越容易超过你真实愿意承担的责任。\n组织主事者：需要阻止邻近势力趁虚夺产，不一定付得起长期护卫。\n外部竞争者：会试探这层联系究竟是名义还是实际联盟。\n玩家有外界可识别的声望或实力。\n组织确有保护空缺，并能支付约定报酬。\n玩家已受同一组织无条件指挥，或对外完全没有可辨身份。\n三分支为游戏改编；公开名号与真实义务分开建模；不采用原著以门人为附加报酬的条件，任何人员加入须独立自愿。"},{"card":{"adaptation_notes":"三分支为游戏改编；专名阵法改为属性和层级条件；笔记提供方法而非自动精通，破阵、消耗与贡献结算都需显式支持。","category":"探索与禁制","choices":[{"action_hint":"custom:重订分层探索分工","continuation":"若领队接受，可借互补专长逐层确认而非一次强闯。","label":"说明局部成果并重新分配探查职责","requires_extension":true,"tradeoff":"会降低众人对你的期待，也可能影响优先分配承诺。"},{"action_hint":"interact:observe","continuation":"若找到可比照特征，可再决定是否值得投入工具。","label":"当场观察新暴露的结构","requires_extension":false,"tradeoff":"外层经验未必适用，观察也可能仍无法辨认机制。"},{"action_hint":"custom:结算阶段探索退出","continuation":"若合作方认可已完成贡献，可在安全界线外离队。","label":"退出后续破阵，结算已经完成的部分","requires_extension":true,"tradeoff":"可能放弃更深处收获，并需说明先前奖励条件。"}],"conflict":"队伍想趁成功继续深入，你知道方法只适用于这一层；另一行家既顾颜面，也提供了关键判断。","dedupe_key":"partial_barrier_success_expertise_overclaim","exclusions":["玩家完全掌握禁制，或当前节点已没有暂停空间。"],"followups":[{"closure":"既定层级完成、分工终止或玩家退出后结束。","development":"重新核对风险与贡献，允许承认方法失效。","trigger":"下一层结构出现或领队要求继续投入"}],"id":"WD-FR-029","npc_motives":["出资领队：急于回收探索投入，容易把局部成果当成总体把握。","同行行家：愿认可有效方法，但希望自己的识别贡献不被抹去。"],"preconditions":["玩家确有适用笔记或工具，但尚未理解全部禁制。","外层已解除，内层仍可在安全距离观察。"],"situation":"队伍请你与另一位行家协力破解遗迹防护。对方先识别结构，你据旧笔记成功打开外层，众人便把你当成能破解全阵的高手。","tags":["互补专长","阶段成果","声望误认"],"title":"只拆开外层的破阵成功","variation_slots":["防护可换为机关、封锁或复杂锁具","旧笔记可换为维修手册与前人经验"]},"content_version":"2026-10-31.1","id":"WD-FR-029","metadata":{"category":"探索与禁制","dedupe_key":"partial_barrier_success_expertise_overclaim","source_card_id":"WD-FR-029","source_chapter_ids":["FR-0417"],"tags":["互补专长","阶段成果","声望误认"]},"retrieval_text":"只拆开外层的破阵成功\n探索与禁制\n互补专长 阶段成果 声望误认\n队伍请你与另一位行家协力破解遗迹防护。对方先识别结构，你据旧笔记成功打开外层，众人便把你当成能破解全阵的高手。\n队伍想趁成功继续深入，你知道方法只适用于这一层；另一行家既顾颜面，也提供了关键判断。\n出资领队：急于回收探索投入，容易把局部成果当成总体把握。\n同行行家：愿认可有效方法，但希望自己的识别贡献不被抹去。\n玩家确有适用笔记或工具，但尚未理解全部禁制。\n外层已解除，内层仍可在安全距离观察。\n玩家完全掌握禁制，或当前节点已没有暂停空间。\n三分支为游戏改编；专名阵法改为属性和层级条件；笔记提供方法而非自动精通，破阵、消耗与贡献结算都需显式支持。"},{"card":{"adaptation_notes":"三分支为游戏改编；把原著高空殿堂转成分层访问地点；进入机制与退出机制独立，观察是当场可见行为而非自动跨日等待。","category":"探索与禁制","choices":[{"action_hint":"interact:observe","continuation":"若确认动作与凭证相符，可据此提出更具体的问题。","label":"观察正在入内者如何启用凭证","requires_extension":false,"tradeoff":"看见进入不等于看见安全返回，仍有信息缺口。"},{"action_hint":"custom:协作验证遗迹门槛","continuation":"若入口允许往返，可先完成短程验证再决定深入。","label":"与同样持图者约定只验证门槛","requires_extension":true,"tradeoff":"伙伴可能要求交换情报，退出规则仍需现场确认。"},{"action_hint":"evade:withdraw","continuation":"若遗迹仍在且条件有变化，可自主决定是否再来。","label":"撤至安全观察点，放弃当次入内","requires_extension":false,"tradeoff":"可能错过开放窗口或先到收获。"}],"conflict":"你要确认准入与退出条件，先行者要保住探索优势；跟随可减少试错，也会暴露自己持有凭证。","dedupe_key":"map_as_credential_entry_exit_uncertainty","exclusions":["凭证已证伪，或入口正在无差别攻击且无观察余地。"],"followups":[{"closure":"门槛验证结束、窗口关闭或玩家放弃后结束。","development":"把准入、探查受限与退出条件分别更新，不据他人进入推定安全。","trigger":"有人返回、入口变化或协作验证得到结果"}],"id":"WD-FR-030","npc_motives":["先行探索者：愿快速入内，不愿在门外免费解释所得经验。","后到同行者：缺少把握，可能提议共同核对入口而不必深入结盟。"],"preconditions":["玩家持有与遗迹可交互的可信凭证。","入口可被观察，玩家尚未越过不可回返节点。"],"situation":"地图把你引向一处封闭遗迹，附近来客也持有相同图样。有人正用它穿过入口，而深处的结构会阻断探查，你尚不知能否原路退出。","tags":["入口观察","同图来客","感知受限"],"title":"地图也是通行凭证","variation_slots":["地图可换为印章、邀请函或共鸣碎片","感知限制可换为迷向、隔音或视线遮挡"]},"content_version":"2026-10-31.1","id":"WD-FR-030","metadata":{"category":"探索与禁制","dedupe_key":"map_as_credential_entry_exit_uncertainty","source_card_id":"WD-FR-030","source_chapter_ids":["FR-0431"],"tags":["入口观察","同图来客","感知受限"]},"retrieval_text":"地图也是通行凭证\n探索与禁制\n入口观察 同图来客 感知受限\n地图把你引向一处封闭遗迹，附近来客也持有相同图样。有人正用它穿过入口，而深处的结构会阻断探查，你尚不知能否原路退出。\n你要确认准入与退出条件，先行者要保住探索优势；跟随可减少试错，也会暴露自己持有凭证。\n先行探索者：愿快速入内，不愿在门外免费解释所得经验。\n后到同行者：缺少把握，可能提议共同核对入口而不必深入结盟。\n玩家持有与遗迹可交互的可信凭证。\n入口可被观察，玩家尚未越过不可回返节点。\n凭证已证伪，或入口正在无差别攻击且无观察余地。\n三分支为游戏改编；把原著高空殿堂转成分层访问地点；进入机制与退出机制独立，观察是当场可见行为而非自动跨日等待。"},{"card":{"adaptation_notes":"三分支为游戏改编；感官识别须有既往接触与特征状态；保密、身份暴露及通行进度需明确支持，不能由询问自动刷新伪装。","category":"身份与秘密","choices":[{"action_hint":"interact:ask","continuation":"若依据真实，可再判断对方愿提供什么可核验帮助。","label":"询问辨认依据与私谈目的","requires_extension":false,"tradeoff":"承认提问可能增加对方判断，但能检验是否只是试探。"},{"action_hint":"custom:协商私谈保密条件","continuation":"若对方给出真实进度与退路，可继续限定范围的合作。","label":"先协商信息保密与可验证的通行条件","requires_extension":true,"tradeoff":"需要双方承担可见行动，不能仅凭互诉困境建立信任。"},{"action_hint":"evade:withdraw","continuation":"若安全退出，可调整伪装与接触渠道。","label":"立即撤离会面与监视区域","requires_extension":false,"tradeoff":"放弃当前通行线索，身份泄露风险仍然存在。"}],"conflict":"接待者想绕过监视争取自主，监视者要控制信息；你需要通行帮助，却无法确定识破者是盟友还是要挟者。","dedupe_key":"monitored_host_recognizes_disguised_guest","exclusions":["身份早已公开，或识破只靠无来源的全知能力。"],"followups":[{"closure":"通行安排结束、双方终止或玩家脱离该地后结束。","development":"用实际履约判断合作，而不因共同秘密自动形成同盟。","trigger":"监视者追问行踪或接待者提供可核验的通道消息"}],"id":"WD-FR-031","npc_motives":["接待者：掌握你的真实身份，希望获得独立商谈的筹码。","监视侍从：受另一权威委派，担心主事者私下改变约定。"],"preconditions":["玩家确在隐藏身份，且接待者有过去接触依据。","现场存在具体监视迹象，并保有可行退出路线。"],"situation":"你以隐蔽身份求助，接待者每谈到关键处就受侍从打断。她暗示另行私谈，之后以一种你未防备的辨认特征揭破身份。","tags":["受监视会面","感官识别","双重谈判"],"title":"侍从咳嗽后的私下邀约","variation_slots":["辨认特征可换为习惯动作、口音或旧器具","监视者可换为账房、亲信或外派顾问"]},"content_version":"2026-10-31.1","id":"WD-FR-031","metadata":{"category":"身份与秘密","dedupe_key":"monitored_host_recognizes_disguised_guest","source_card_id":"WD-FR-031","source_chapter_ids":["FR-0555"],"tags":["受监视会面","感官识别","双重谈判"]},"retrieval_text":"侍从咳嗽后的私下邀约\n身份与秘密\n受监视会面 感官识别 双重谈判\n你以隐蔽身份求助，接待者每谈到关键处就受侍从打断。她暗示另行私谈，之后以一种你未防备的辨认特征揭破身份。\n接待者想绕过监视争取自主，监视者要控制信息；你需要通行帮助，却无法确定识破者是盟友还是要挟者。\n接待者：掌握你的真实身份，希望获得独立商谈的筹码。\n监视侍从：受另一权威委派，担心主事者私下改变约定。\n玩家确在隐藏身份，且接待者有过去接触依据。\n现场存在具体监视迹象，并保有可行退出路线。\n身份早已公开，或识破只靠无来源的全知能力。\n三分支为游戏改编；感官识别须有既往接触与特征状态；保密、身份暴露及通行进度需明确支持，不能由询问自动刷新伪装。"},{"card":{"adaptation_notes":"三分支为游戏改编；专属异境改为已有能力限制与资源约束；不复制固定人口上限为强制死亡规则，口粮和劳作需实际结算。","category":"生存求道","choices":[{"action_hint":"interact:ask","continuation":"若存在适合的岗位，可判断自己能否长期承受。","label":"询问口粮规则与真正缺少的技能","requires_extension":false,"tradeoff":"可能听到不符合原身份的工作要求，但尚不承担义务。"},{"action_hint":"custom:约定村落试工","continuation":"若双方认可成果，可再议长期分配而非永久卖身。","label":"提出有限试工并学习本地防卫方式","requires_extension":true,"tradeoff":"会投入劳动，初期贡献未必抵得上全部口粮。"},{"action_hint":"evade:withdraw","continuation":"若路线可行，可另寻村落或继续调查出口。","label":"拒绝定居，撤往已知临时避难处","requires_extension":false,"tradeoff":"需要自行解决食物，失去村落协同防护。"}],"conflict":"村落必须维持有限口粮与防务，你要活下去并寻找出路；陌生人的能力与负担都还没有被当地人理解。","dedupe_key":"power_loss_community_survival_contribution","exclusions":["玩家仍可随意施展压倒性法术，或被强行设为无路可去。"],"followups":[{"closure":"接纳条款落实、试工结清或玩家离村后结束。","development":"按真实能力调整岗位，允许协商与退出，不以境界替代贡献。","trigger":"试工期满或下一次防务分工开始"}],"id":"WD-FR-032","npc_motives":["村落长老：担心新增人口挤压口粮，更相信可见劳动而非外界名号。","防卫队员：希望补充人手，也不愿让新人未经训练拖累阵列。"],"preconditions":["环境已明确限制玩家通常能力。","村落愿谈接纳条件，另有已知临时避难位置。"],"situation":"进入法力难以施展的封闭地域后，你投靠的村落刚击退兽袭。长老把食物与参与劳作绑定，你过去的境界并不能直接换来供养。","tags":["绝灵环境","共同防卫","食物分配"],"title":"修为失效后的村落位置","variation_slots":["能力限制可换为失灵区或重伤恢复期","贡献可换为维修、翻译、照护或守夜"]},"content_version":"2026-10-31.1","id":"WD-FR-032","metadata":{"category":"生存求道","dedupe_key":"power_loss_community_survival_contribution","source_card_id":"WD-FR-032","source_chapter_ids":["FR-0582"],"tags":["绝灵环境","共同防卫","食物分配"]},"retrieval_text":"修为失效后的村落位置\n生存求道\n绝灵环境 共同防卫 食物分配\n进入法力难以施展的封闭地域后，你投靠的村落刚击退兽袭。长老把食物与参与劳作绑定，你过去的境界并不能直接换来供养。\n村落必须维持有限口粮与防务，你要活下去并寻找出路；陌生人的能力与负担都还没有被当地人理解。\n村落长老：担心新增人口挤压口粮，更相信可见劳动而非外界名号。\n防卫队员：希望补充人手，也不愿让新人未经训练拖累阵列。\n环境已明确限制玩家通常能力。\n村落愿谈接纳条件，另有已知临时避难位置。\n玩家仍可随意施展压倒性法术，或被强行设为无路可去。\n三分支为游戏改编；专属异境改为已有能力限制与资源约束；不复制固定人口上限为强制死亡规则，口粮和劳作需实际结算。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著修为层数转为相对门槛；识别痕迹与证明意图分离，保密信息不会由普通观察自动向全组织公开。","category":"身份与秘密","choices":[{"action_hint":"interact:ask","continuation":"若规则清楚，可决定是否按同一标准补充自己的履历。","label":"询问审查是否允许申报特殊传承","requires_extension":false,"tradeoff":"可能引起执事对自己也有保留的猜测。"},{"action_hint":"custom:提交限定异常线索","continuation":"若执事独立验证，可调查来源而非凭玩家判断定罪。","label":"只提交匿名的可核验异常线索","requires_extension":true,"tradeoff":"匿名性未必可靠，组织也可能扩大核查范围。"},{"action_hint":"interact:decline","continuation":"若未来出现实际冲突，再按新事实处理。","label":"拒绝追查对方，专注自己的审查","requires_extension":false,"tradeoff":"放弃进一步确认对方背景，仍可能日后共同任职。"}],"conflict":"执事要排除危险来客，异常新人要保住隐私，你想避免共同受疑，却没有证据证明特殊修法就是恶意。","dedupe_key":"hidden_candidate_detects_peer_anomaly","exclusions":["该痕迹被世界规则明确证明为犯罪，或对方已主动说明并获认可。"],"followups":[{"closure":"审查结束、疑点解开或玩家退出关注后结束。","development":"对照先前痕迹更新判断，不把沉默固定解释为间谍。","trigger":"审查结果公布或同行者主动解释特殊传承"}],"id":"WD-FR-033","npc_motives":["同行新人：可能有合法但不愿公开的传承，也可能另负任务。","审核执事：希望流程可靠，却难逐一辨别所有罕见技艺。"],"preconditions":["玩家有既定识别能力，且正参与真实身份审查。","发现的是具体异常痕迹，尚不足以判断动机。"],"situation":"你与一批新人接受组织审查，发现其中一人修为合格，却隐藏另一种修炼痕迹。你能看出异常的能力本身，也不在对外公布的履历中。","tags":["入门审查","异常功法","互相藏拙"],"title":"同批新人藏着别样气息","variation_slots":["异常可换为战斗习惯、异域器物或不合履历的技艺","招录可换为临时护卫登记"]},"content_version":"2026-10-31.1","id":"WD-FR-033","metadata":{"category":"身份与秘密","dedupe_key":"hidden_candidate_detects_peer_anomaly","source_card_id":"WD-FR-033","source_chapter_ids":["FR-0600"],"tags":["入门审查","异常功法","互相藏拙"]},"retrieval_text":"同批新人藏着别样气息\n身份与秘密\n入门审查 异常功法 互相藏拙\n你与一批新人接受组织审查，发现其中一人修为合格，却隐藏另一种修炼痕迹。你能看出异常的能力本身，也不在对外公布的履历中。\n执事要排除危险来客，异常新人要保住隐私，你想避免共同受疑，却没有证据证明特殊修法就是恶意。\n同行新人：可能有合法但不愿公开的传承，也可能另负任务。\n审核执事：希望流程可靠，却难逐一辨别所有罕见技艺。\n玩家有既定识别能力，且正参与真实身份审查。\n发现的是具体异常痕迹，尚不足以判断动机。\n该痕迹被世界规则明确证明为犯罪，或对方已主动说明并获认可。\n三分支为游戏改编；原著修为层数转为相对门槛；识别痕迹与证明意图分离，保密信息不会由普通观察自动向全组织公开。"},{"card":{"adaptation_notes":"三分支为游戏改编；专属宝物与境界换成真实秘密及可验证脱离条件；共生、保密与解约需显式支持，不把同意一次合作当作永久所有。","category":"师徒与控制","choices":[{"action_hint":"interact:ask","continuation":"若陈述可核验，可为后续合作确定实际保密范围。","label":"先询问其记忆范围与真实脱离目标","requires_extension":false,"tradeoff":"会让对方知道哪些秘密最敏感，也可能得到不完整回答。"},{"action_hint":"custom:订立可解除共生约定","continuation":"若双方确认可验证节点，可逐步协作并保留解除路径。","label":"商议有终止条件的共生与保密约定","requires_extension":true,"tradeoff":"需要承担转移与研究成本，未来自由不能靠空泛许诺。"},{"action_hint":"interact:decline","continuation":"若之后找到独立容器或中介，可另行讨论安全分离。","label":"拒绝共生，暂停缔约谈话","requires_extension":false,"tradeoff":"对方知晓的内容不会消失，仍需寻求双方接受的隔离办法。"}],"conflict":"你需要可信保密，器物意识需要身体与自主；无限控制能减少眼前疑虑，却会破坏其愿意合作的理由。","dedupe_key":"sentient_artifact_confidentiality_autonomy","exclusions":["器物只是无意识工具，或玩家从未持有涉及秘密的物件。"],"followups":[{"closure":"完成安全分离、约定解除或关系重新成立后结束。","development":"评估独立生存条件并重新确认意愿，不能无限顺延自由期限。","trigger":"获得新容器、达到约定节点或一方提出解除"}],"id":"WD-FR-034","npc_motives":["器物意识：过去依附器物才能离开困境，希望帮助强者换取未来自由。","共同研究者：能评估转移风险，却不愿为无法验证的自由条件作保证。"],"preconditions":["世界已存在有独立意愿的器物意识。","其知情来自长期携带，双方仍有协商余地。"],"situation":"你一直携带的器物显露独立意识，承认知晓多项私密行动。它愿建立共生关系换取生存与未来脱离的机会，你却担心秘密继续外泄。","tags":["器物意识","秘密暴露","自由承诺"],"title":"随身器物中的旁观者","variation_slots":["器物可换为灵舟核心、旧镜或记忆载体","自由条件可换为容器与外界环境"]},"content_version":"2026-10-31.1","id":"WD-FR-034","metadata":{"category":"师徒与控制","dedupe_key":"sentient_artifact_confidentiality_autonomy","source_card_id":"WD-FR-034","source_chapter_ids":["FR-0616"],"tags":["器物意识","秘密暴露","自由承诺"]},"retrieval_text":"随身器物中的旁观者\n师徒与控制\n器物意识 秘密暴露 自由承诺\n你一直携带的器物显露独立意识，承认知晓多项私密行动。它愿建立共生关系换取生存与未来脱离的机会，你却担心秘密继续外泄。\n你需要可信保密，器物意识需要身体与自主；无限控制能减少眼前疑虑，却会破坏其愿意合作的理由。\n器物意识：过去依附器物才能离开困境，希望帮助强者换取未来自由。\n共同研究者：能评估转移风险，却不愿为无法验证的自由条件作保证。\n世界已存在有独立意愿的器物意识。\n其知情来自长期携带，双方仍有协商余地。\n器物只是无意识工具，或玩家从未持有涉及秘密的物件。\n三分支为游戏改编；专属宝物与境界换成真实秘密及可验证脱离条件；共生、保密与解约需显式支持，不把同意一次合作当作永久所有。"},{"card":{"adaptation_notes":"三分支为游戏改编；不照搬原著岁数与人物关系；亲缘是可验证历史状态，展示力量不能替代身份证据，也不自动生成继承权。","category":"凡俗与旧情","choices":[{"action_hint":"custom:核验跨代亲缘","continuation":"若细节吻合，可建立身份信任而不自动接受族中职位。","label":"同意用旧物与记忆交叉核验","requires_extension":true,"tradeoff":"会触及离别记忆，也不保证每件后来物品都认得。"},{"action_hint":"interact:ask","continuation":"若来源可互证，可逐步说明自己的经历与来意。","label":"先询问家族近况与画像来历","requires_extension":false,"tradeoff":"可能延长怀疑，族人也有权不向陌生人透露。"},{"action_hint":"interact:leave","continuation":"若以后双方都愿意，可经可信中间人再联系。","label":"不再主张相认，结束此次拜访","requires_extension":false,"tradeoff":"错过正式重续亲缘的机会，也不会获得家族权限。"}],"conflict":"后人要保护家产与名分，又期盼强者庇护；你想确认故人后代安好，却未必愿接管整个家族。","dedupe_key":"long_lived_return_ancestor_authentication","exclusions":["玩家只是相貌相似的陌生人，或后人已经明确拒绝接触。"],"followups":[{"closure":"核验完成并处理本次来意，或玩家离开后结束。","development":"把认亲与具体援助分开商谈，后代不因血缘自动获得承诺。","trigger":"身份确认后族人提出庇护或资源请求"}],"id":"WD-FR-035","npc_motives":["族长：不能凭相貌和威势认祖，否则难向全族交代。","旧友后裔：更相信超凡经历，也希望重续先辈留下的交情。"],"preconditions":["玩家与该家族确有跨代亲缘或故交事实。","族内保存可交叉核对的私密旧物。"],"situation":"你多年后归乡，容貌与族中先祖画像相同，却远比后人想象年轻。族人怀疑有人借祖名图谋，愿以只有家主知道的旧物归属核验。","tags":["长寿归乡","后代核验","亲缘边界"],"title":"祖祠里的年轻来客","variation_slots":["祖祠可换为纪念馆、旧宅或家族墓园","旧物可换为手札、家训或失传曲调"]},"content_version":"2026-10-31.1","id":"WD-FR-035","metadata":{"category":"凡俗与旧情","dedupe_key":"long_lived_return_ancestor_authentication","source_card_id":"WD-FR-035","source_chapter_ids":["FR-0662"],"tags":["长寿归乡","后代核验","亲缘边界"]},"retrieval_text":"祖祠里的年轻来客\n凡俗与旧情\n长寿归乡 后代核验 亲缘边界\n你多年后归乡，容貌与族中先祖画像相同，却远比后人想象年轻。族人怀疑有人借祖名图谋，愿以只有家主知道的旧物归属核验。\n后人要保护家产与名分，又期盼强者庇护；你想确认故人后代安好，却未必愿接管整个家族。\n族长：不能凭相貌和威势认祖，否则难向全族交代。\n旧友后裔：更相信超凡经历，也希望重续先辈留下的交情。\n玩家与该家族确有跨代亲缘或故交事实。\n族内保存可交叉核对的私密旧物。\n玩家只是相貌相似的陌生人，或后人已经明确拒绝接触。\n三分支为游戏改编；不照搬原著岁数与人物关系；亲缘是可验证历史状态，展示力量不能替代身份证据，也不自动生成继承权。"},{"card":{"adaptation_notes":"三分支为游戏改编；删除原著以侍妾交换的机制，改成有来源的不可割让器具；裁定、演示与信息交付需扩展，拒绝不触发必死惩罚。","category":"势力博弈","choices":[{"action_hint":"custom:申请交易争端裁定","continuation":"若不可转让条款成立，可中止强制议价而无需展示能力。","label":"要求中立裁判核对规则适用范围","requires_extension":true,"tradeoff":"会公开争端，也可能发现规则确实偏向强者。"},{"action_hint":"custom:订立有限能力验证","continuation":"若对方同意，可先获信息再决定是否参与后续计划。","label":"提出有限能力演示换取真实目的","requires_extension":true,"tradeoff":"仍会暴露部分底牌，演示边界需要双方事先接受。"},{"action_hint":"evade:withdraw","continuation":"若退路未被封锁，可向别处主办者寻求交易。","label":"拒绝比试并撤离争端区域","requires_extension":false,"tradeoff":"可能失去当次集市便利，对方也可能继续寻求接触。"}],"conflict":"挑战者要验证你的隐藏能力，你要保护不可让渡的资源；主办方偏好让强者自行解决，又须维持规则表面公正。","dedupe_key":"coercive_exchange_as_capability_screen","exclusions":["主办规则从未建立，或剧情把同伴直接当可交易物品。"],"followups":[{"closure":"争端撤销、有限演示完成或玩家脱离后结束。","development":"按真实目的重估合作，不把较量自动延伸成长期效忠。","trigger":"裁判给出解释或挑战者披露筛选目的"}],"id":"WD-FR-036","npc_motives":["挑战者：需要符合某种条件的合作者，但不愿先泄露目的。","同行见证者：想防止你受伤，却担心贸然干涉破坏本地规矩。"],"preconditions":["当地确有已公布的争端程序，但尚未开始较量。","争议器具具有真实不可割让理由，玩家有离场渠道。"],"situation":"强者借集市的争端规则，要用更贵物件换你无法割让的关键器具，拒绝便提出特定能力较量。他真正想看的似乎不是那件器具。","tags":["制度漏洞","能力试探","不对称挑战"],"title":"用交易规则逼你露底","variation_slots":["能力可换为识图、耐性或特殊环境适应","争议物可换为护身器具与不可转让凭证"]},"content_version":"2026-10-31.1","id":"WD-FR-036","metadata":{"category":"势力博弈","dedupe_key":"coercive_exchange_as_capability_screen","source_card_id":"WD-FR-036","source_chapter_ids":["FR-0675"],"tags":["制度漏洞","能力试探","不对称挑战"]},"retrieval_text":"用交易规则逼你露底\n势力博弈\n制度漏洞 能力试探 不对称挑战\n强者借集市的争端规则，要用更贵物件换你无法割让的关键器具，拒绝便提出特定能力较量。他真正想看的似乎不是那件器具。\n挑战者要验证你的隐藏能力，你要保护不可让渡的资源；主办方偏好让强者自行解决，又须维持规则表面公正。\n挑战者：需要符合某种条件的合作者，但不愿先泄露目的。\n同行见证者：想防止你受伤，却担心贸然干涉破坏本地规矩。\n当地确有已公布的争端程序，但尚未开始较量。\n争议器具具有真实不可割让理由，玩家有离场渠道。\n主办规则从未建立，或剧情把同伴直接当可交易物品。\n三分支为游戏改编；删除原著以侍妾交换的机制，改成有来源的不可割让器具；裁定、演示与信息交付需扩展，拒绝不触发必死惩罚。"},{"card":{"adaptation_notes":"三分支为游戏改编；祖辈忠诚不自动继承；取消强制世代身份，帮助、聘用与冷静期分别记录，不以拒签惩罚后人。","category":"师徒与控制","choices":[{"action_hint":"custom:重订代际合作约定","continuation":"若后人充分理解，可成立只约束本人和期限的合作。","label":"提出有薪有期的新合作取代世代从属","requires_extension":true,"tradeoff":"需要明确任务、报酬与退出条件，难靠一句誓言省事。"},{"action_hint":"custom:结清祖辈旧约","continuation":"若对方接受，可独立求道并保留普通故交关系。","label":"给出一次性帮助并结清旧缘","requires_extension":true,"tradeoff":"需要拿出自愿提供的资源，也不能期待以后无偿效劳。"},{"action_hint":"interact:decline","continuation":"若对方日后主动回来，可从头核对其真实选择。","label":"拒绝立即续约，允许对方自行考虑","requires_extension":false,"tradeoff":"未来未必再能得到同样机会，但不产生新的从属义务。"}],"conflict":"后人想借旧缘获得修行机会，又缺乏议价经验；你需要可靠帮手，却不能把祖辈的话直接当成后人的同意。","dedupe_key":"inherited_subordination_renegotiation","exclusions":["旧约已明确被双方废除，或后人没有自主决定能力。"],"followups":[{"closure":"选择完成、本人撤回或双方不再接触后结束。","development":"确认其理解义务与替代路径，再处理新约或旧缘结清。","trigger":"持信人主动再次提出明确选择"}],"id":"WD-FR-037","npc_motives":["后辈持信人：害怕错失唯一门路，容易在感激下仓促答应。","旧约受诺者：看重熟人传承的可信度，也需承认旧保护从未兑现。"],"preconditions":["旧约与信物均可核验，玩家为旧约相关方。","后人已能独立决定，尚未签订新的从属关系。"],"situation":"一位年轻修士凭祖传信物来认旧约，认为必须替祖辈继续效力。你确与其先人有过约定，但从未向这一代提供相应庇护。","tags":["跨代契约","修行扶助","冷静决定"],"title":"祖辈誓言是否由后人续签","variation_slots":["旧约可换为家族恩债、旧商号承诺或师门遗托","信物可换为断契或共同密码"]},"content_version":"2026-10-31.1","id":"WD-FR-037","metadata":{"category":"师徒与控制","dedupe_key":"inherited_subordination_renegotiation","source_card_id":"WD-FR-037","source_chapter_ids":["FR-0683"],"tags":["跨代契约","修行扶助","冷静决定"]},"retrieval_text":"祖辈誓言是否由后人续签\n师徒与控制\n跨代契约 修行扶助 冷静决定\n一位年轻修士凭祖传信物来认旧约，认为必须替祖辈继续效力。你确与其先人有过约定，但从未向这一代提供相应庇护。\n后人想借旧缘获得修行机会，又缺乏议价经验；你需要可靠帮手，却不能把祖辈的话直接当成后人的同意。\n后辈持信人：害怕错失唯一门路，容易在感激下仓促答应。\n旧约受诺者：看重熟人传承的可信度，也需承认旧保护从未兑现。\n旧约与信物均可核验，玩家为旧约相关方。\n后人已能独立决定，尚未签订新的从属关系。\n旧约已明确被双方废除，或后人没有自主决定能力。\n三分支为游戏改编；祖辈忠诚不自动继承；取消强制世代身份，帮助、聘用与冷静期分别记录，不以拒签惩罚后人。"},{"card":{"adaptation_notes":"三分支为游戏改编；原著专属心术改为明确距离与权限受限的约束；不让救助者替当事人决定感情，逃离与彻底解制是不同结果。","category":"追逐与藏身","choices":[{"action_hint":"custom:协作准备范围外脱身","continuation":"若路线与时机可行，可到安全处再研究解除办法。","label":"按同伴原计划准备离开范围","requires_extension":true,"tradeoff":"需放弃在地便利，离开后禁制也未必立即消失。"},{"action_hint":"custom:调查控制器处置条件","continuation":"若发现可协商条件，可减少与强者正面冲突的需要。","label":"调查控制器位置与可行交涉办法","requires_extension":true,"tradeoff":"可能暴露援助意图，取回或解除也不能先作保证。"},{"action_hint":"evade:withdraw","continuation":"若仍能保持联系，可在控制范围外接应自愿离开的同伴。","label":"拒绝夺器方案，先撤出危险接触区","requires_extension":false,"tradeoff":"当次无法彻底解除禁制，需尊重同伴自己的后续决定。"}],"conflict":"控制者要把公开仪式变成既成事实，同伴要恢复自主；直接夺器可能更快，却会与实力更强者正面冲突。","dedupe_key":"bounded_control_range_escape_alternative","exclusions":["同伴自愿参加仪式，或控制被设为无距离限制且没有退路。"],"followups":[{"closure":"安全脱离控制范围、禁制解除或援助被撤回后结束。","development":"由同伴再次确认计划，依实际距离和路线决定行动。","trigger":"控制者接近、仪式期限临近或同伴完成恢复准备"}],"id":"WD-FR-038","npc_motives":["受制同伴：愿离开熟悉环境，不想让援助者为证明心意冒险。","控制者：用组织扩张收益为强迫辩护，担心仪式失败丢失盟友。"],"preconditions":["同伴主动说明意愿，控制范围与恢复条件有可信依据。","存在能离开控制范围的路线，仪式尚未开始。"],"situation":"一位被迫参加政治仪式的同伴告诉你，控制者只能在有限距离操纵其动作。她已有恢复能力后逃离的计划，请你一起衡量夺取控制器与远走的代价。","tags":["强制仪式","有限距离","自主脱身"],"title":"逃出控制范围的另一条路","variation_slots":["仪式可换为宣誓、交接或政治婚约","控制器可换为距离受限的契印或装置"]},"content_version":"2026-10-31.1","id":"WD-FR-038","metadata":{"category":"追逐与藏身","dedupe_key":"bounded_control_range_escape_alternative","source_card_id":"WD-FR-038","source_chapter_ids":["FR-0715"],"tags":["强制仪式","有限距离","自主脱身"]},"retrieval_text":"逃出控制范围的另一条路\n追逐与藏身\n强制仪式 有限距离 自主脱身\n一位被迫参加政治仪式的同伴告诉你，控制者只能在有限距离操纵其动作。她已有恢复能力后逃离的计划，请你一起衡量夺取控制器与远走的代价。\n控制者要把公开仪式变成既成事实，同伴要恢复自主；直接夺器可能更快，却会与实力更强者正面冲突。\n受制同伴：愿离开熟悉环境，不想让援助者为证明心意冒险。\n控制者：用组织扩张收益为强迫辩护，担心仪式失败丢失盟友。\n同伴主动说明意愿，控制范围与恢复条件有可信依据。\n存在能离开控制范围的路线，仪式尚未开始。\n同伴自愿参加仪式，或控制被设为无距离限制且没有退路。\n三分支为游戏改编；原著专属心术改为明确距离与权限受限的约束；不让救助者替当事人决定感情，逃离与彻底解制是不同结果。"},{"card":{"adaptation_notes":"三分支为游戏改编；不搬用原著固定战期与势力规模；议事权、支援清单与撤民路线须已存在或显式扩展，投票不自动移动军队。","category":"势力博弈","choices":[{"action_hint":"custom:组织战争成本核对","continuation":"若信息可比，可判断争论来自事实差异还是利益错位。","label":"要求各派列出拖延与决战的实际损失","requires_extension":true,"tradeoff":"公开成本会暴露防线弱点，估计也可能有偏差。"},{"action_hint":"custom:协商联盟战争分担","continuation":"若各派正式承诺，可让战略选择有可执行的分担条件。","label":"提出前线撤民与后方支援捆绑方案","requires_extension":true,"tradeoff":"后方需先承担资源义务，前方也要接受共同协调。"},{"action_hint":"custom:撤回议会支持","continuation":"若条款以后补齐，可自主决定是否再次支持。","label":"拒绝为未说明代价的方案背书","requires_extension":true,"tradeoff":"可能失去当次议事影响，联盟仍可由其他成员作决定。"}],"conflict":"后方想用时间削弱敌人，前方要保住根基；统一战略若没有成本分担，会使同盟成员各自撤走。","dedupe_key":"coalition_war_cost_geographic_asymmetry","exclusions":["各方成本已经充分分摊，或议会仅是无法影响的旁观场景。"],"followups":[{"closure":"方案正式通过、联盟另作决策或玩家退出议事后结束。","development":"核对承诺与真实支援，必要时重议而非把口号当履约。","trigger":"各派提交支援清单或前线出现新的战况"}],"id":"WD-FR-039","npc_motives":["腹地代表：相信敌方补给不足，不愿仓促投入精锐。","边境代表：担心被当成缓冲地带，要求可兑现的支援。"],"preconditions":["联盟由利益位置不同的成员组成。","外敌与交战期限确有依据，玩家有表达意见的资格。"],"situation":"联盟商讨敌方限期战书，腹地势力主张拖延，前线代表则担心驻地与凡俗人口先承受损失。你有议事席位，但各派尚未承诺如何分摊代价。","tags":["前后方分歧","战争成本","联盟分摊"],"title":"谁的土地承受持久战","variation_slots":["前线可换为灾区、封锁区或争议商路","支援可换为粮运、接纳人口或驻守力量"]},"content_version":"2026-10-31.1","id":"WD-FR-039","metadata":{"category":"势力博弈","dedupe_key":"coalition_war_cost_geographic_asymmetry","source_card_id":"WD-FR-039","source_chapter_ids":["FR-0758"],"tags":["前后方分歧","战争成本","联盟分摊"]},"retrieval_text":"谁的土地承受持久战\n势力博弈\n前后方分歧 战争成本 联盟分摊\n联盟商讨敌方限期战书，腹地势力主张拖延，前线代表则担心驻地与凡俗人口先承受损失。你有议事席位，但各派尚未承诺如何分摊代价。\n后方想用时间削弱敌人，前方要保住根基；统一战略若没有成本分担，会使同盟成员各自撤走。\n腹地代表：相信敌方补给不足，不愿仓促投入精锐。\n边境代表：担心被当成缓冲地带，要求可兑现的支援。\n联盟由利益位置不同的成员组成。\n外敌与交战期限确有依据，玩家有表达意见的资格。\n各方成本已经充分分摊，或议会仅是无法影响的旁观场景。\n三分支为游戏改编；不搬用原著固定战期与势力规模；议事权、支援清单与撤民路线须已存在或显式扩展，投票不自动移动军队。"},{"card":{"adaptation_notes":"三分支为游戏改编；固定年限改为当前世界真实窗口；对外说法、联系人和同行责任需记录，暂停研究不意味着研究自动完成。","category":"突破与远行","choices":[{"action_hint":"custom:建立远行联络安排","continuation":"若联系人接受职责，可处理急事并按约定条件传讯。","label":"仅向必要联系人交代行程与联络规则","requires_extension":true,"tradeoff":"会增加知情者，秘密不再只由自己控制。"},{"action_hint":"custom:修订同行与返程计划","continuation":"若双方接受路线与职责，可同行而不承诺替对方突破。","label":"重核同行者准备并约定中途退出点","requires_extension":true,"tradeoff":"会增加筹备成本，未必能兼顾原定窗口。"},{"action_hint":"custom:取消本次远行计划","continuation":"若在地事务后来稳定，可再制定新的路线安排。","label":"取消当次启程，重新选择远行时机","requires_extension":true,"tradeoff":"可能错过现有窗口，准备投入也未必能全数复用。"}],"conflict":"你要保密行程且按时返回，留守者要应付外界询问，同行者希望获得历练却会改变原有准备。","dedupe_key":"discreet_expedition_cover_and_return_window","exclusions":["处于必须即时逃亡的状态，或保密需强迫无辜者承担风险。"],"followups":[{"closure":"返回、正式改期或远行计划取消并交接完毕后结束。","development":"按联络规则处理，不让留守者无限延长掩护与承诺。","trigger":"有访客求见、紧急消息到达或返程节点临近"}],"id":"WD-FR-040","npc_motives":["留守主事者：愿代为接待，不想因含糊说法承担无期限责任。","请求同行者：遇到个人瓶颈，希望路上获指点，也需了解真实风险。"],"preconditions":["目的地与往返路线已声明，存在真实返程窗口。","玩家能自主启程，驻地有自愿协助的人。"],"situation":"你计划在有限窗口内远行，驻地同伴愿代你解释缺席，另有人临行提出同行。公开理由若与真实安排不符，日后访客与紧急求援都可能揭穿。","tags":["远行窗口","行踪保密","同行请求"],"title":"以闭关消息掩护远行","variation_slots":["公开理由可换为研究、休整或不接待访客","远行目标可换为求学、访友或跨域调查"]},"content_version":"2026-10-31.1","id":"WD-FR-040","metadata":{"category":"突破与远行","dedupe_key":"discreet_expedition_cover_and_return_window","source_card_id":"WD-FR-040","source_chapter_ids":["FR-0795"],"tags":["远行窗口","行踪保密","同行请求"]},"retrieval_text":"以闭关消息掩护远行\n突破与远行\n远行窗口 行踪保密 同行请求\n你计划在有限窗口内远行，驻地同伴愿代你解释缺席，另有人临行提出同行。公开理由若与真实安排不符，日后访客与紧急求援都可能揭穿。\n你要保密行程且按时返回，留守者要应付外界询问，同行者希望获得历练却会改变原有准备。\n留守主事者：愿代为接待，不想因含糊说法承担无期限责任。\n请求同行者：遇到个人瓶颈，希望路上获指点，也需了解真实风险。\n目的地与往返路线已声明，存在真实返程窗口。\n玩家能自主启程，驻地有自愿协助的人。\n处于必须即时逃亡的状态，或保密需强迫无辜者承担风险。\n三分支为游戏改编；固定年限改为当前世界真实窗口；对外说法、联系人和同行责任需记录，暂停研究不意味着研究自动完成。"},{"card":{"adaptation_notes":"把专属传送阵改成有失败类型和出口证据的地域设施；不得把免责告示当成随机杀死玩家的许可，入阵与集合状态均需引擎支持。","category":"探索与禁制","choices":[{"action_hint":"interact:ask","continuation":"若地图年代与勘察记录吻合，可形成有边界的风险判断。","label":"要求展示出口依据再决定入阵","requires_extension":false,"tradeoff":"主办者可能只提供旧记录，甚至拒绝进一步解释。"},{"action_hint":"custom:negotiate_rendezvous","continuation":"只有同伴接受并且标记能跨区生效，集合约定才可成立。","label":"与同批者约定失散后的集合办法","requires_extension":true,"tradeoff":"共享联络方式会暴露身份，也不能消除落点风险。"},{"action_hint":"interact:decline","continuation":"若日后出现可核实的新入口，可以重新评估，无须追赶原队。","label":"放弃本轮入谷并保留凭证","requires_extension":false,"tradeoff":"已付费用是否可退取决于原约，可能错过本次开放。"}],"conflict":"主办者要抢在窗口关闭前回收投入，入场者需要可靠退路，双方掌握的信息并不对等。","dedupe_key":"single_way_gate_disclosure","exclusions":["玩家已掌握安全往返路线，主办者不再控制必要入口。"],"followups":[{"closure":"玩家离场或本轮入口关闭后结束。","development":"旧出口失效的证据可促使其补充说明或调整条款。","trigger":"主办者公布下一批开阵时间"}],"id":"WD-FR-041","npc_motives":["主持者：维持开阵秩序，避免为试验技术承担无限赔偿。","向导：愿售旧地图，却不能保证旧出口仍然存在。"],"preconditions":["玩家已取得本次入场资格。","当地存在明确开启窗口与未经完全验证的传送技术。"],"situation":"险地入口由一家势力控制，持有凭证的你排到阵前，才听说落点不能指定，阵台将在末批入内后拆除。","tags":["入场资格","不完整技术","退路核验"],"title":"单程入口的免责告示","variation_slots":["入口经营者的组织性质","凭证费用与开放窗口"]},"content_version":"2026-10-31.1","id":"WD-FR-041","metadata":{"category":"探索与禁制","dedupe_key":"single_way_gate_disclosure","source_card_id":"WD-FR-041","source_chapter_ids":["FR-0806"],"tags":["入场资格","不完整技术","退路核验"]},"retrieval_text":"单程入口的免责告示\n探索与禁制\n入场资格 不完整技术 退路核验\n险地入口由一家势力控制，持有凭证的你排到阵前，才听说落点不能指定，阵台将在末批入内后拆除。\n主办者要抢在窗口关闭前回收投入，入场者需要可靠退路，双方掌握的信息并不对等。\n主持者：维持开阵秩序，避免为试验技术承担无限赔偿。\n向导：愿售旧地图，却不能保证旧出口仍然存在。\n玩家已取得本次入场资格。\n当地存在明确开启窗口与未经完全验证的传送技术。\n玩家已掌握安全往返路线，主办者不再控制必要入口。\n把专属传送阵改成有失败类型和出口证据的地域设施；不得把免责告示当成随机杀死玩家的许可，入阵与集合状态均需引擎支持。"},{"card":{"adaptation_notes":"将专属护环和禁光替为经过验证的专用通行器与环境规则；防护不等于无敌，队形、负荷及停步状态须显式实现。","category":"同盟与背叛","choices":[{"action_hint":"custom:coordinate_shared_shield","continuation":"若所有人能跟随口令，可再尝试短距离进入并保留回撤余量。","label":"先排定队形并演练停步口令","requires_extension":true,"tradeoff":"演练消耗通行窗口，行动最慢者决定全队速度。"},{"action_hint":"custom:monitor_barrier_cycle","continuation":"若发现负荷增长或覆盖缩小，可以据此缩短通行段落。","label":"观察禁光周期与器物反应","requires_extension":true,"tradeoff":"持续观察需要时间，其他队伍可能先行占据出口。"},{"action_hint":"evade:withdraw","continuation":"安全路线仍成立时可原路回退，之后是否重组队伍由双方决定。","label":"撤回已经确认安全的入口平台","requires_extension":false,"tradeoff":"本轮通行暂停，队友可能另找持具者。"}],"conflict":"持具者需要别人服从步调，同伴担心把性命交给一人；各自加固防护反可能破坏通道。","dedupe_key":"shared_protection_pace_dependency","exclusions":["没有足够证据说明护具有效，或安全范围容不下全队。"],"followups":[{"closure":"全队通过或放弃此通道后结束。","development":"同伴可提出拆成小队，但护具往返次数成为新的成本。","trigger":"一次演练暴露队伍无法同步"}],"id":"WD-FR-042","npc_motives":["持具者：希望节省器物负荷，不愿被队友推着冒进。","负伤同伴：想通过窄道，却可能跟不上队伍移动。"],"preconditions":["已有测试证明特殊护具能偏转禁制。","队伍人数和体形没有超过护具实际覆盖范围。"],"situation":"前方禁光会穿透常见护具，队中只有一件特殊器物能撑开小片安全范围，同行者等你决定通行安排。","tags":["共享防护","行动协调","禁区通行"],"title":"共用护具的窄道","variation_slots":["护具覆盖形状与承重限制","禁制对其他法术的反应"]},"content_version":"2026-10-31.1","id":"WD-FR-042","metadata":{"category":"同盟与背叛","dedupe_key":"shared_protection_pace_dependency","source_card_id":"WD-FR-042","source_chapter_ids":["FR-0815"],"tags":["共享防护","行动协调","禁区通行"]},"retrieval_text":"共用护具的窄道\n同盟与背叛\n共享防护 行动协调 禁区通行\n前方禁光会穿透常见护具，队中只有一件特殊器物能撑开小片安全范围，同行者等你决定通行安排。\n持具者需要别人服从步调，同伴担心把性命交给一人；各自加固防护反可能破坏通道。\n持具者：希望节省器物负荷，不愿被队友推着冒进。\n负伤同伴：想通过窄道，却可能跟不上队伍移动。\n已有测试证明特殊护具能偏转禁制。\n队伍人数和体形没有超过护具实际覆盖范围。\n没有足够证据说明护具有效，或安全范围容不下全队。\n将专属护环和禁光替为经过验证的专用通行器与环境规则；防护不等于无敌，队形、负荷及停步状态须显式实现。"},{"card":{"adaptation_notes":"保留强弱不对等与期限边界，移除原宗门和境界名；协议记录、资源结算及违约认定均需状态支持，不能靠一句询问完成。","category":"交易与信用","choices":[{"action_hint":"custom:agree_limited_alliance","continuation":"若双方接受且能独立撤出，各自只承担约定的破禁部分。","label":"提出开门即散的分段合作约定","requires_extension":true,"tradeoff":"需要明确阵材损耗和撤手条件，谈判会耽误时间。"},{"action_hint":"interact:ask","continuation":"若对方只催促而不展示能力，合作价值应重新估计。","label":"询问对方能提供哪些可验证支援","requires_extension":false,"tradeoff":"透露部分技术难点，可能让对方判断你的弱处。"},{"action_hint":"evade:withdraw","continuation":"双方没有阻拦行为时可各行其事，不自动升级为仇敌。","label":"拒绝合队并撤向已勘察的外缘","requires_extension":false,"tradeoff":"另寻入口要增加路程，可能错过先行者留下的机会。"}],"conflict":"来者缺少阵法专长而你缺少时间与力量；合作能节省消耗，也可能让对方掌握你的底牌。","dedupe_key":"limited_alliance_scope_boundary","exclusions":["对方正在攻击或已证明不会遵守任何阶段边界。"],"followups":[{"closure":"按约分开或另立独立约定时结束。","development":"旧约可用于要求重新谈报酬，而非默认延长服务。","trigger":"封禁解除且有人要求追加同行义务"}],"id":"WD-FR-043","npc_motives":["领队：希望尽快进入遗迹，忌惮公开翻脸损害后续合作。","阵师：愿提供判断，但不愿被要求继续陪同争宝。"],"preconditions":["双方各自拥有破禁所需的不同能力。","其他入口存在但勘察成本明显，当前仍可退出。"],"situation":"你正在研究一条耗时的封禁通路，一支人数占优的队伍主动提出共同破阵，要求立即商定分工。","tags":["有限合作","实力不均","时间竞争"],"title":"只到门槛为止的同盟","variation_slots":["互补能力与投入种类","强势一方的声誉约束"]},"content_version":"2026-10-31.1","id":"WD-FR-043","metadata":{"category":"交易与信用","dedupe_key":"limited_alliance_scope_boundary","source_card_id":"WD-FR-043","source_chapter_ids":["FR-0815"],"tags":["有限合作","实力不均","时间竞争"]},"retrieval_text":"只到门槛为止的同盟\n交易与信用\n有限合作 实力不均 时间竞争\n你正在研究一条耗时的封禁通路，一支人数占优的队伍主动提出共同破阵，要求立即商定分工。\n来者缺少阵法专长而你缺少时间与力量；合作能节省消耗，也可能让对方掌握你的底牌。\n领队：希望尽快进入遗迹，忌惮公开翻脸损害后续合作。\n阵师：愿提供判断，但不愿被要求继续陪同争宝。\n双方各自拥有破禁所需的不同能力。\n其他入口存在但勘察成本明显，当前仍可退出。\n对方正在攻击或已证明不会遵守任何阶段边界。\n保留强弱不对等与期限边界，移除原宗门和境界名；协议记录、资源结算及违约认定均需状态支持，不能靠一句询问完成。"},{"card":{"adaptation_notes":"将古宝与灵石改为当地可估价资产；秘密入口只是新提案，不代表玩家必须继续，退出前须核对安全路线与尚欠份额。","category":"机缘与代价","choices":[{"action_hint":"custom:settle_loot_share","continuation":"若付款与物权记录完成，各方可自由决定下一步路线。","label":"按可验证估价收取补偿后结清","requires_extension":true,"tradeoff":"现钱可能低于日后售价，需要接受即时结算的折让。"},{"action_hint":"interact:ask","continuation":"只有风险与分配重新议定后，才可把旧合作延伸到新目标。","label":"询问下一处目标和独立退路","requires_extension":false,"tradeoff":"要求披露可能令同伴顾虑秘密外流。"},{"action_hint":"evade:withdraw","continuation":"若各方已有安全返路，可分别离开；未付清款项和物品按原约另行处理。","label":"退出后续探险，要求另行结算已有份额","requires_extension":false,"tradeoff":"可能错过更高收益，但不承担尚未同意的风险。"}],"conflict":"同伴想把现有合作延长到下一处目标，你更看重已获收益；退出还牵涉共用返程工具的安排。","dedupe_key":"loot_cashout_exit_optional_extension","exclusions":["仍在即时战斗中，无法安全进行结算。"],"followups":[{"closure":"份额结清且双方分开后结束。","development":"若旧物估价有误，仅在原约允许复核时重谈。","trigger":"同伴带回新目标的实际发现"}],"id":"WD-FR-044","npc_motives":["寻宝者：急需实物提升实力，愿掏空随身现钱换取份额。","领路人：希望保留下一处线索，不愿为队友离开放弃计划。"],"preconditions":["当前收获属于双方事先约定共同分配的物品。","玩家保留离队权，且返程资源的归属可以明确。"],"situation":"队伍已经取得一批难以均分的战利品，同行者想用现钱买下你的份额，并提议再探一个他们掌握的秘密入口。","tags":["收益结算","目标分歧","主动止损"],"title":"分完战利品之后","variation_slots":["不可切分的收获种类","共同返程工具的所有权"]},"content_version":"2026-10-31.1","id":"WD-FR-044","metadata":{"category":"机缘与代价","dedupe_key":"loot_cashout_exit_optional_extension","source_card_id":"WD-FR-044","source_chapter_ids":["FR-0823"],"tags":["收益结算","目标分歧","主动止损"]},"retrieval_text":"分完战利品之后\n机缘与代价\n收益结算 目标分歧 主动止损\n队伍已经取得一批难以均分的战利品，同行者想用现钱买下你的份额，并提议再探一个他们掌握的秘密入口。\n同伴想把现有合作延长到下一处目标，你更看重已获收益；退出还牵涉共用返程工具的安排。\n寻宝者：急需实物提升实力，愿掏空随身现钱换取份额。\n领路人：希望保留下一处线索，不愿为队友离开放弃计划。\n当前收获属于双方事先约定共同分配的物品。\n玩家保留离队权，且返程资源的归属可以明确。\n仍在即时战斗中，无法安全进行结算。\n将古宝与灵石改为当地可估价资产；秘密入口只是新提案，不代表玩家必须继续，退出前须核对安全路线与尚欠份额。"},{"card":{"adaptation_notes":"以敌方公开征兆替代原著魔族设定；任何布阵、同步攻击和掩护承诺均为新增战术状态，不能由普通观察直接触发伤害。","category":"生存求道","choices":[{"action_hint":"custom:coordinate_delayed_counter","continuation":"若有人应允且牵制持续到位，可尝试完成布置，不保证困住强敌。","label":"说明准备时间并请求有限牵制","requires_extension":true,"tradeoff":"会暴露自己的手段轮廓，队友也可能拒绝承担掩护。"},{"action_hint":"interact:observe","continuation":"若找到固定转向或停顿征兆，可提供给队友作为下一次攻击依据。","label":"观察当前移动与蓄势征兆","requires_extension":false,"tradeoff":"只能看出已显露的征兆，敌人也可能故意伪装蓄势。"},{"action_hint":"evade:withdraw","continuation":"能否同行取决于彼此回应，拒绝追击不自动丧失既有装备。","label":"趁敌人尚未封路撤向既定出口","requires_extension":false,"tradeoff":"需放弃现场目标，撤退速度受最慢同行者影响。"}],"conflict":"同伴要立即压制强敌，你需要有人承担近身风险；人人保留底牌会让敌方获得变招时间。","dedupe_key":"transformation_window_cover_commitment","exclusions":["没有可实施的牵制方式，或敌人已完成压倒性的封锁。"],"followups":[{"closure":"脱离战斗或明确解除共同威胁时结束。","development":"原有分工需要立即缩短，避免把临时掩护当成无限承诺。","trigger":"敌人改变移动方式或掩护者示意退出"}],"id":"WD-FR-045","npc_motives":["近战同伴：愿短时掩护，但不肯无限承受追击。","经验丰富的旁观者：判断风险偏高，希望保存队伍退路。"],"preconditions":["强敌变招已有可观察征兆。","玩家确有需要准备的能力，且至少存在一条已知退路。"],"situation":"强敌暂退并出现蓄势征兆，同场几人都能牵制却缺少统一节奏；你的重手段需要一段不受干扰的准备。","tags":["强敌变招","分工牵制","底牌消耗"],"title":"敌人变招前的协同空隙","variation_slots":["蓄势征兆与反制准备","同伴愿承担的掩护范围"]},"content_version":"2026-10-31.1","id":"WD-FR-045","metadata":{"category":"生存求道","dedupe_key":"transformation_window_cover_commitment","source_card_id":"WD-FR-045","source_chapter_ids":["FR-0844"],"tags":["强敌变招","分工牵制","底牌消耗"]},"retrieval_text":"敌人变招前的协同空隙\n生存求道\n强敌变招 分工牵制 底牌消耗\n强敌暂退并出现蓄势征兆，同场几人都能牵制却缺少统一节奏；你的重手段需要一段不受干扰的准备。\n同伴要立即压制强敌，你需要有人承担近身风险；人人保留底牌会让敌方获得变招时间。\n近战同伴：愿短时掩护，但不肯无限承受追击。\n经验丰富的旁观者：判断风险偏高，希望保存队伍退路。\n强敌变招已有可观察征兆。\n玩家确有需要准备的能力，且至少存在一条已知退路。\n没有可实施的牵制方式，或敌人已完成压倒性的封锁。\n以敌方公开征兆替代原著魔族设定；任何布阵、同步攻击和掩护承诺均为新增战术状态，不能由普通观察直接触发伤害。"},{"card":{"adaptation_notes":"空间寿命和脱困门槛要由可检验信息给出；不照搬数十年修炼时长，也不把提高境界写成保证成功的自动结局。","category":"突破与远行","choices":[{"action_hint":"custom:plan_confined_training","continuation":"若阶段检查显示空间仍稳定且能力进步，可再评估破壁尝试。","label":"制定储备与实力提升的阶段计划","requires_extension":true,"tradeoff":"要占用长期时间，外界安排可能需要另寻补救。"},{"action_hint":"custom:survey_space_weakpoint","continuation":"若弱点位置能够复测，可减少下一次尝试的盲目消耗。","label":"按内部而非边缘重新寻找薄弱处","requires_extension":true,"tradeoff":"搜寻消耗心神，仍不代表找到后就能打开。"},{"action_hint":"evade:withdraw","continuation":"休整只结束当前强攻，可自行选择之后是否继续调查。","label":"暂停破壁，退回已验证的安全驻点","requires_extension":false,"tradeoff":"短期不能履行外界事务，但保存尝试所需的力量。"}],"conflict":"急于重返外界的人担心错过承诺，稳健者担心连续强攻耗尽资源；等待也需要可信的稳定期限。","dedupe_key":"confinement_growth_deadline_budget","exclusions":["空间正在即时崩解，或无法支持任何短期停留。"],"followups":[{"closure":"成功离开或转为独立长期生存阶段后结束。","development":"按已有证据重排储备和尝试窗口，允许放弃高消耗方案。","trigger":"稳定征兆变化或外界期限临近"}],"id":"WD-FR-046","npc_motives":["技术顾问：愿指出观察方法，不肯保证未经测试的空间寿命。","同伴：希望先建立生活秩序，怕每次失败都透支逃生能力。"],"preconditions":["封闭环境已有生存资源和可测的稳定征兆。","玩家在外界存在明确但并非立即到期的牵挂。"],"situation":"你与同伴被隔在一处尚能生存的小天地内，现有攻击未能破壁，顾问认为必须提高实力才有可靠脱身机会。","tags":["封闭空间","能力门槛","外界牵挂"],"title":"困境中的长期时间表","variation_slots":["可观测的空间稳定指标","外界承诺及缓冲期限"]},"content_version":"2026-10-31.1","id":"WD-FR-046","metadata":{"category":"突破与远行","dedupe_key":"confinement_growth_deadline_budget","source_card_id":"WD-FR-046","source_chapter_ids":["FR-0857"],"tags":["封闭空间","能力门槛","外界牵挂"]},"retrieval_text":"困境中的长期时间表\n突破与远行\n封闭空间 能力门槛 外界牵挂\n你与同伴被隔在一处尚能生存的小天地内，现有攻击未能破壁，顾问认为必须提高实力才有可靠脱身机会。\n急于重返外界的人担心错过承诺，稳健者担心连续强攻耗尽资源；等待也需要可信的稳定期限。\n技术顾问：愿指出观察方法，不肯保证未经测试的空间寿命。\n同伴：希望先建立生活秩序，怕每次失败都透支逃生能力。\n封闭环境已有生存资源和可测的稳定征兆。\n玩家在外界存在明确但并非立即到期的牵挂。\n空间正在即时崩解，或无法支持任何短期停留。\n空间寿命和脱困门槛要由可检验信息给出；不照搬数十年修炼时长，也不把提高境界写成保证成功的自动结局。"},{"card":{"adaptation_notes":"将入门资格制度转成世界实际采用的准入门槛；部落困境有资源原因，不能让救助必然换来天才弟子或忠诚势力。","category":"势力博弈","choices":[{"action_hint":"custom:contract_partial_escort","continuation":"若双方明确终点与补给责任，可让队伍用较小代价渡过当前难关。","label":"商议只护送最危险的一段","requires_extension":true,"tradeoff":"有限报酬对应有限服务，之后仍有未解决的路途风险。"},{"action_hint":"interact:ask","continuation":"若存在不影响报名的可售物，队伍可自行权衡是否换粮。","label":"询问贡物清单与可绕行的补给点","requires_extension":false,"tradeoff":"公开清单会暴露车队财物，族长可能不愿提供。"},{"action_hint":"interact:decline","continuation":"若已有公开安全路讯可分享，是否提供可另行决定。","label":"谢绝护送并结束商议","requires_extension":false,"tradeoff":"车队需寻找其他办法，玩家不取得报酬或未来供奉。"}],"conflict":"族长想保住孩子的入学机会，护卫需要能覆盖风险的报酬；出售贡物补粮可能损害报名资格。","dedupe_key":"poor_caravan_education_escort_gap","exclusions":["车队已获足够保护与粮食，或玩家无法接触车队。"],"followups":[{"closure":"履约结清、协商解除或车队自行改道时结束。","development":"按约结算有限服务，不能自动转为部落永久护卫。","trigger":"车队抵达约定终点或报名条件发生变化"}],"id":"WD-FR-047","npc_motives":["族长：愿承担个人劳役换护送，却怕部落未来数年被债务拖垮。","年轻候选人：想继续赶路，也不愿同伴为了自己的资格挨饿。"],"preconditions":["队伍确有已有的报名期限和不足的补给。","玩家具备护送、交易或提供路线信息中的至少一种能力。"],"situation":"一支小部落车队带着学徒候选人与贡物赶往区域学府，雇不起常驻护卫，途中弃掉了大部分口粮。","tags":["资源匮乏","教育机会","脆弱商队"],"title":"小部落的护送缺口","variation_slots":["入学、祭仪或迁居的资格要求","车队能提供的非货币报酬"]},"content_version":"2026-10-31.1","id":"WD-FR-047","metadata":{"category":"势力博弈","dedupe_key":"poor_caravan_education_escort_gap","source_card_id":"WD-FR-047","source_chapter_ids":["FR-0880"],"tags":["资源匮乏","教育机会","脆弱商队"]},"retrieval_text":"小部落的护送缺口\n势力博弈\n资源匮乏 教育机会 脆弱商队\n一支小部落车队带着学徒候选人与贡物赶往区域学府，雇不起常驻护卫，途中弃掉了大部分口粮。\n族长想保住孩子的入学机会，护卫需要能覆盖风险的报酬；出售贡物补粮可能损害报名资格。\n族长：愿承担个人劳役换护送，却怕部落未来数年被债务拖垮。\n年轻候选人：想继续赶路，也不愿同伴为了自己的资格挨饿。\n队伍确有已有的报名期限和不足的补给。\n玩家具备护送、交易或提供路线信息中的至少一种能力。\n车队已获足够保护与粮食，或玩家无法接触车队。\n将入门资格制度转成世界实际采用的准入门槛；部落困境有资源原因，不能让救助必然换来天才弟子或忠诚势力。"},{"card":{"adaptation_notes":"原著药材只作为估值差异来源，游戏可换成零件或文书；引荐、尾款和失约状态必须单独实现，不能默认附带稀有货。","category":"交易与信用","choices":[{"action_hint":"custom:escrow_referral_credit","continuation":"若凭证可验证并顺利入场，尾款才能按约抵扣，而采购仍自行决定。","label":"把差价拆成入场成功后才结清的尾款","requires_extension":true,"tradeoff":"对方可能嫌手续麻烦，交易因此延后。"},{"action_hint":"interact:ask","continuation":"若只保入场而不保成交，可据此比较现金与渠道的真实价值。","label":"询问引荐范围与失约补偿","requires_extension":false,"tradeoff":"过细盘问可能降低卖方让利意愿。"},{"action_hint":"interact:decline","continuation":"双方若无法接受同一估价，可各自收回未交付物品。","label":"拒绝渠道抵价，坚持原定实物或现金结算","requires_extension":false,"tradeoff":"可能谈不成此次交换，也不会取得圈内资格。"}],"conflict":"卖方想节省现钱，买方需要渠道却难判断门路真假；一次引荐的价值不等于保证买到所需物。","dedupe_key":"price_gap_referral_valuation","exclusions":["所谓门路没有任何可核实的时间、地点或担保关系。"],"followups":[{"closure":"入场义务履行或差价另行结清后结束。","development":"按事先约定补差或撤销尾款，避免事后凭想象追债。","trigger":"引荐日期到达或卖方未能兑现入场"}],"id":"WD-FR-048","npc_motives":["卖方：愿借自己的信用作保，但不愿承担后续采购成败。","中间人：重视圈内信任，担心新来者泄露交易安排。"],"preconditions":["双方已经认可实物存在可讨论的价值差。","玩家有明确采购需求，而引荐者确有相关人脉。"],"situation":"交换双方已验过实物，你提供的东西价值略高；对方拿不出更好货物，提出用进入稀缺交易圈的引荐抵差价。","tags":["以物易物","信息估值","引荐信用"],"title":"差价换成一条门路","variation_slots":["需要采购的稀缺零件","担保形式与尾款保管者"]},"content_version":"2026-10-31.1","id":"WD-FR-048","metadata":{"category":"交易与信用","dedupe_key":"price_gap_referral_valuation","source_card_id":"WD-FR-048","source_chapter_ids":["FR-0941"],"tags":["以物易物","信息估值","引荐信用"]},"retrieval_text":"差价换成一条门路\n交易与信用\n以物易物 信息估值 引荐信用\n交换双方已验过实物，你提供的东西价值略高；对方拿不出更好货物，提出用进入稀缺交易圈的引荐抵差价。\n卖方想节省现钱，买方需要渠道却难判断门路真假；一次引荐的价值不等于保证买到所需物。\n卖方：愿借自己的信用作保，但不愿承担后续采购成败。\n中间人：重视圈内信任，担心新来者泄露交易安排。\n双方已经认可实物存在可讨论的价值差。\n玩家有明确采购需求，而引荐者确有相关人脉。\n所谓门路没有任何可核实的时间、地点或担保关系。\n原著药材只作为估值差异来源，游戏可换成零件或文书；引荐、尾款和失约状态必须单独实现，不能默认附带稀有货。"},{"card":{"adaptation_notes":"抽取错峰、担保与隐私三种约束，不照搬禁物清单；邀请只提供接触机会，身份登记和交易许可需另行建模。","category":"身份与秘密","choices":[{"action_hint":"custom:verify_private_market_access","continuation":"若时间和准入要求满足，可自行选择参与哪一段交换。","label":"先取得可验证的入场规则和时间表","requires_extension":true,"tradeoff":"需适度披露身份，管事可能拒绝提供完整宾客信息。"},{"action_hint":"interact:ask","continuation":"若规则超出可接受范围，可据实缩小采购需求或停止接洽。","label":"询问担保责任及禁止交易的物品","requires_extension":false,"tradeoff":"问题可能使引荐人觉得你谨慎过头。"},{"action_hint":"interact:decline","continuation":"公开场次是否买到材料仍取决于实际货单。","label":"谢绝私会，保留公开拍卖行程","requires_extension":false,"tradeoff":"会失去部分稀缺交易机会，也免去担保与保密义务。"}],"conflict":"组织者要保护参与者身份，你需要核对行程和交易边界；披露太多需求可能使自己的财力外泄。","dedupe_key":"dual_market_access_privacy_schedule","exclusions":["私会地点未经确认，或玩家已被该会明确禁止入内。"],"followups":[{"closure":"玩家明确选定场次或拒绝邀请后结束。","development":"可重新评估暴露成本，先前邀请不自动等于接受新条款。","trigger":"管事临时要求额外身份保证"}],"id":"WD-FR-049","npc_motives":["引荐人：想促成交易，担心受邀者公开追问惹人注意。","会场管事：欢迎有货的新客，但必须能追索扰乱秩序者。"],"preconditions":["已经存在公开集市及独立的邀请制场次。","玩家得到真实引荐，尚未承诺携带或购买任何物品。"],"situation":"你获邀参加只接纳熟人担保的私下交换会，它与公开拍卖同期开办；引荐者称核心场次错开，却不愿当众细说。","tags":["圈层准入","信息保密","行程冲突"],"title":"明暗两场的错峰邀请","variation_slots":["私会对新客的责任要求","两场活动的时间与货物差别"]},"content_version":"2026-10-31.1","id":"WD-FR-049","metadata":{"category":"身份与秘密","dedupe_key":"dual_market_access_privacy_schedule","source_card_id":"WD-FR-049","source_chapter_ids":["FR-0941"],"tags":["圈层准入","信息保密","行程冲突"]},"retrieval_text":"明暗两场的错峰邀请\n身份与秘密\n圈层准入 信息保密 行程冲突\n你获邀参加只接纳熟人担保的私下交换会，它与公开拍卖同期开办；引荐者称核心场次错开，却不愿当众细说。\n组织者要保护参与者身份，你需要核对行程和交易边界；披露太多需求可能使自己的财力外泄。\n引荐人：想促成交易，担心受邀者公开追问惹人注意。\n会场管事：欢迎有货的新客，但必须能追索扰乱秩序者。\n已经存在公开集市及独立的邀请制场次。\n玩家得到真实引荐，尚未承诺携带或购买任何物品。\n私会地点未经确认，或玩家已被该会明确禁止入内。\n抽取错峰、担保与隐私三种约束，不照搬禁物清单；邀请只提供接触机会，身份登记和交易许可需另行建模。"},{"card":{"adaptation_notes":"把特定灵虫的培育秘法改成玩家已有用途的稀缺技术；救援分支属于游戏原创，原文此章尚未完成援救，不写成已发生的结局。","category":"同盟与背叛","choices":[{"action_hint":"custom:negotiate_rescue_secret","continuation":"若真实性得到支持，可另定有限救援目标与剩余交付条件。","label":"要求先给出可验证的技术片段再议救援","requires_extension":true,"tradeoff":"讨价还价占用短暂窗口，片段也可能不完整。"},{"action_hint":"interact:observe","continuation":"若威胁确有扩张迹象，可据自身利益决定是否采取有限干预。","label":"先评估围攻者得手后对自己的威胁","requires_extension":false,"tradeoff":"只能凭已显露手段判断，也可能被各方误解为待价而沽。"},{"action_hint":"evade:withdraw","continuation":"旧怨不会自动消除，也不强制追加新的报复事件。","label":"拒绝卷入并沿现有退路撤离","requires_extension":false,"tradeoff":"放弃技术与和解机会，后续关系取决于各方实际经历。"}],"conflict":"求救者要立刻活命，同行者担忧泄密责任；你需要可信报酬，也不愿任围攻者借吞并他们坐大。","dedupe_key":"old_enemy_rescue_secret_authority","exclusions":["玩家毫无救援能力，或对方只是借口求救却不处于实际危险。"],"followups":[{"closure":"救援义务与技术交付结清，或玩家脱离现场时结束。","development":"若先前未约定可再谈，但不能追认玩家已经接受禁制。","trigger":"求救者脱险后要求限定技术用途"}],"id":"WD-FR-050","npc_motives":["被困者：认为保住自身与守护力量比保密更重要。","守秘者：害怕获救后仍遭本族追责，要求限制传播范围。"],"preconditions":["双方确有历史冲突，求救者掌握玩家需要的技术。","玩家有施加影响或退出现场的现实能力。"],"situation":"曾经追索你的对手正被第三方围困，先许诺消除旧怨，见你未表态，又提出交出本族严守的技术。","tags":["救援谈判","旧怨","秘密传承"],"title":"旧敌的救命报价","variation_slots":["秘密技术的价值与可验证片段","第三方壮大的具体机制"]},"content_version":"2026-10-31.1","id":"WD-FR-050","metadata":{"category":"同盟与背叛","dedupe_key":"old_enemy_rescue_secret_authority","source_card_id":"WD-FR-050","source_chapter_ids":["FR-1052"],"tags":["救援谈判","旧怨","秘密传承"]},"retrieval_text":"旧敌的救命报价\n同盟与背叛\n救援谈判 旧怨 秘密传承\n曾经追索你的对手正被第三方围困，先许诺消除旧怨，见你未表态，又提出交出本族严守的技术。\n求救者要立刻活命，同行者担忧泄密责任；你需要可信报酬，也不愿任围攻者借吞并他们坐大。\n被困者：认为保住自身与守护力量比保密更重要。\n守秘者：害怕获救后仍遭本族追责，要求限制传播范围。\n双方确有历史冲突，求救者掌握玩家需要的技术。\n玩家有施加影响或退出现场的现实能力。\n玩家毫无救援能力，或对方只是借口求救却不处于实际危险。\n把特定灵虫的培育秘法改成玩家已有用途的稀缺技术；救援分支属于游戏原创，原文此章尚未完成援救，不写成已发生的结局。"},{"card":{"adaptation_notes":"将族群记忆转成可追索的机关知识，保留反复搜索仍会漏项的原因；分步展示、持有权和中枢状态必须明确支持。","category":"同盟与背叛","choices":[{"action_hint":"custom:stage_dual_key_activation","continuation":"若机关反应与承诺一致，再决定是否推进下一步，器物不必永久转让。","label":"提出分步展示与同步启用的办法","requires_extension":true,"tradeoff":"需要多次核验，拖延可能增加遗迹消耗。"},{"action_hint":"interact:ask","continuation":"若其描述能对应现场痕迹，可提高合作可信度而不直接信任其人。","label":"询问对方如何认出中枢","requires_extension":false,"tradeoff":"会暴露你先前搜索的盲点，对方可能只说明部分依据。"},{"action_hint":"evade:withdraw","continuation":"此选择不自动重启旧战；任一方有新证据后可另行接洽。","label":"暂停合作，退回已确认安全的驻点","requires_extension":false,"tradeoff":"脱困继续延迟，双方仍需各自负担生存资源。"}],"conflict":"双方各握不可替代的信息或钥匙，独自脱困都无把握；先交出底牌的人可能失去谈判余地。","dedupe_key":"enemy_dual_key_staged_disclosure","exclusions":["任一方已有独立可行出口，互相依赖并不存在。"],"followups":[{"closure":"双方离开遗迹或明确放弃共同方案时结束。","development":"核对新增风险由谁承担，允许在未激活前终止。","trigger":"中枢要求额外操作或一方改变约定"}],"id":"WD-FR-051","npc_motives":["旧敌：想尽快脱困，怀疑你会拿到路线后反过来排挤自己。","器物保管者：愿合作，但要求保留实际控制权。"],"preconditions":["已有证据说明普通破坏与独自传送无效。","双方的钥匙与识别知识确实互补，尚未交割。"],"situation":"你在封闭遗迹搜寻多日，旧敌忽然表示已找到中枢，但需要你持有的器物，才肯带你去看具体位置。","tags":["互补线索","暂时停战","共同脱困"],"title":"仇敌手里的另一半钥匙","variation_slots":["需要的器物与传统知识","分步启动可验证的反馈"]},"content_version":"2026-10-31.1","id":"WD-FR-051","metadata":{"category":"同盟与背叛","dedupe_key":"enemy_dual_key_staged_disclosure","source_card_id":"WD-FR-051","source_chapter_ids":["FR-1126"],"tags":["互补线索","暂时停战","共同脱困"]},"retrieval_text":"仇敌手里的另一半钥匙\n同盟与背叛\n互补线索 暂时停战 共同脱困\n你在封闭遗迹搜寻多日，旧敌忽然表示已找到中枢，但需要你持有的器物，才肯带你去看具体位置。\n双方各握不可替代的信息或钥匙，独自脱困都无把握；先交出底牌的人可能失去谈判余地。\n旧敌：想尽快脱困，怀疑你会拿到路线后反过来排挤自己。\n器物保管者：愿合作，但要求保留实际控制权。\n已有证据说明普通破坏与独自传送无效。\n双方的钥匙与识别知识确实互补，尚未交割。\n任一方已有独立可行出口，互相依赖并不存在。\n将族群记忆转成可追索的机关知识，保留反复搜索仍会漏项的原因；分步展示、持有权和中枢状态必须明确支持。"},{"card":{"adaptation_notes":"原著只有转世疑问，此卡不得确认轮回；独特体质可改成技艺、旧物或行为习惯，援助和身份调查分别取得意愿。","category":"凡俗与旧情","choices":[{"action_hint":"custom:separate_aid_identity_inquiry","continuation":"若年轻人之后自愿交谈，可将记忆与独立事实逐项核对。","label":"先处理获准的求助，另约谈往事","requires_extension":true,"tradeoff":"确认身份会延迟，也可能永远没有答案。"},{"action_hint":"interact:ask","continuation":"若回答只显示普通传承，应保留巧合解释，避免追加虚构前世记忆。","label":"征询是否愿意谈自己的学习经历","requires_extension":false,"tradeoff":"提问可能让家属误会暗含收徒要求。"},{"action_hint":"interact:decline","continuation":"关系可以止于一次会面，之后是否往来由双方选择。","label":"停止追问，把对方当作独立来访者","requires_extension":false,"tradeoff":"放下追索会留下遗憾，但不妨碍已明确的救助承诺。"}],"conflict":"你想确认旧友是否归来，年轻人只求解决眼前困难；把相似当作身份结论可能压过其自身意愿。","dedupe_key":"resemblance_grief_identity_projection","exclusions":["世界规则已排除转世，或人物身份已被可靠证据明确确认。"],"followups":[{"closure":"双方不再追问或现有证据已得到清楚解释时结束。","development":"可以重新调查，但须区分记忆、传闻与可核实线索。","trigger":"对方主动带来与旧事相关的独立材料"}],"id":"WD-FR-052","npc_motives":["年轻人：希望被认真对待，不愿在不知情时承担旧人的关系。","家属：珍惜高人的援手，担心拒绝追问会失去帮助。"],"preconditions":["玩家已有一位具备相关特征的旧识记忆。","相似之处来自现场观察，尚无足够证据确认身份。"],"situation":"一名求助的年轻人显露出与你故友相似的才能和身体特征，旧事随之涌上心头，但对方并不认识你。","tags":["旧友投射","身份疑云","个人边界"],"title":"像故人的陌生孩子","variation_slots":["与旧友相似的技能或习惯","来访者希望解决的现实问题"]},"content_version":"2026-10-31.1","id":"WD-FR-052","metadata":{"category":"凡俗与旧情","dedupe_key":"resemblance_grief_identity_projection","source_card_id":"WD-FR-052","source_chapter_ids":["FR-1138"],"tags":["旧友投射","身份疑云","个人边界"]},"retrieval_text":"像故人的陌生孩子\n凡俗与旧情\n旧友投射 身份疑云 个人边界\n一名求助的年轻人显露出与你故友相似的才能和身体特征，旧事随之涌上心头，但对方并不认识你。\n你想确认旧友是否归来，年轻人只求解决眼前困难；把相似当作身份结论可能压过其自身意愿。\n年轻人：希望被认真对待，不愿在不知情时承担旧人的关系。\n家属：珍惜高人的援手，担心拒绝追问会失去帮助。\n玩家已有一位具备相关特征的旧识记忆。\n相似之处来自现场观察，尚无足够证据确认身份。\n世界规则已排除转世，或人物身份已被可靠证据明确确认。\n原著只有转世疑问，此卡不得确认轮回；独特体质可改成技艺、旧物或行为习惯，援助和身份调查分别取得意愿。"},{"card":{"adaptation_notes":"特殊体质需转成可观察、会随修炼变化的虚构机制；不得把收徒当唯一生路，长期照护、补位和自主暂停均需可记录状态。","category":"师徒与控制","choices":[{"action_hint":"custom:plan_limited_care_training","continuation":"若双方确认补位人选和停止条件，可先试行再决定是否继续。","label":"与当事人商议有限阶段的照护试行","requires_extension":true,"tradeoff":"要投入持续时间与资源，未必适合其长期生活。"},{"action_hint":"interact:ask","continuation":"若本人偏好安稳生活，可把后续支持转向已有安全方案。","label":"询问当事人对修行与凡俗生活的看法","requires_extension":false,"tradeoff":"可能与家属期待发生冲突，需要容许其改变主意。"},{"action_hint":"interact:decline","continuation":"既有临时帮助按原约结束，暂停进境可作为真实可行的选择。","label":"拒绝承担无法保证的长期照护","requires_extension":false,"tradeoff":"家属需寻找别的支持，不应因此被迫冒险修炼。"}],"conflict":"家属希望保留修行前途，晚辈的选择尚未被听见；强者能暂时帮助，却不能轻易承诺终身在场。","dedupe_key":"progress_requires_continuous_care","exclusions":["问题只需一次普通治疗便能解决，没有持续依赖。"],"followups":[{"closure":"阶段结束、转交可靠照护或当事人选择停止修炼时结束。","development":"在失衡前重新评估安排，不以债务强迫当事人拜师。","trigger":"照护者即将远行或资源持续性降低"}],"id":"WD-FR-053","npc_motives":["家属：愿投入积蓄，容易把一次救助误当成长期保证。","照护者：希望说明能力和出行限制，避免中断造成新的危机。"],"preconditions":["失衡机制有可靠诊断，至少存在暂停修炼的稳定方案。","当事人能够表达意愿，玩家可提供或联系部分照护。"],"situation":"一名有资质的晚辈被查出修行越快越易失衡，暂时休养可以安稳生活，继续进境则需要长期且昂贵的照护。","tags":["长期照护","修行选择","依赖成本"],"title":"继续修行需要谁的陪伴","variation_slots":["修行引发失衡的具体机制","照护频率与可替代支持"]},"content_version":"2026-10-31.1","id":"WD-FR-053","metadata":{"category":"师徒与控制","dedupe_key":"progress_requires_continuous_care","source_card_id":"WD-FR-053","source_chapter_ids":["FR-1138"],"tags":["长期照护","修行选择","依赖成本"]},"retrieval_text":"继续修行需要谁的陪伴\n师徒与控制\n长期照护 修行选择 依赖成本\n一名有资质的晚辈被查出修行越快越易失衡，暂时休养可以安稳生活，继续进境则需要长期且昂贵的照护。\n家属希望保留修行前途，晚辈的选择尚未被听见；强者能暂时帮助，却不能轻易承诺终身在场。\n家属：愿投入积蓄，容易把一次救助误当成长期保证。\n照护者：希望说明能力和出行限制，避免中断造成新的危机。\n失衡机制有可靠诊断，至少存在暂停修炼的稳定方案。\n当事人能够表达意愿，玩家可提供或联系部分照护。\n问题只需一次普通治疗便能解决，没有持续依赖。\n特殊体质需转成可观察、会随修炼变化的虚构机制；不得把收徒当唯一生路，长期照护、补位和自主暂停均需可记录状态。"},{"card":{"adaptation_notes":"不固定原著三次或境界名称，接入时需由承诺状态支持；有限援手不等于永久阵营归属，履约条件和消耗规则应明确。","category":"交易与信用","choices":[{"action_hint":"custom:bound_future_assistance","continuation":"若明确请求方式、可行条件及结清规则，可形成有限债务。","label":"把长期辅佐改为有范围的援手次数","requires_extension":true,"tradeoff":"仍将占用未来时间，不能保证每次求助都方便。"},{"action_hint":"interact:ask","continuation":"若证据仅支持借鉴价值，应据此缩小承诺而非否认全部知识。","label":"要求说明心得的实际验证经历","requires_extension":false,"tradeoff":"可能被视为质疑祖传成果，谈判气氛趋冷。"},{"action_hint":"interact:decline","continuation":"对方可以另找援手，拒绝本身不构成已经违约。","label":"拒绝交易并结束会谈","requires_extension":false,"tradeoff":"失去这批心得，但可继续原有修行计划。"}],"conflict":"长辈想买到可靠的未来保护，你想得到知识而保留自身道路；稳定执政没有明确完成期限。","dedupe_key":"indefinite_patronage_bounded_favors","exclusions":["对方没有权利处分知识，或承诺已经被不可更改地订立。"],"followups":[{"closure":"约定次数完成或双方书面解除债务时结束。","development":"先核对是否属于约定危险与能力范围，再决定履行方式。","trigger":"继承人以联络凭证提出请求"}],"id":"WD-FR-054","npc_motives":["掌权长辈：担心身后继承者遭清算，愿调整形式而不愿白送成果。","继承人：需要外援，也可能不愿时时受监护者干涉。"],"preconditions":["玩家与对方有接近对等的谈判地位。","可交换的知识确有来源，但效果尚不能保证。"],"situation":"一对掌权者愿交出珍贵突破心得，希望你为年轻继承人提供支持，但最初要求一直持续到其坐稳位置。","tags":["人情边界","知识交易","继承者保障"],"title":"把一生辅佐谈成有限援手","variation_slots":["突破心得的可靠程度","援手期限、次数与求援媒介"]},"content_version":"2026-10-31.1","id":"WD-FR-054","metadata":{"category":"交易与信用","dedupe_key":"indefinite_patronage_bounded_favors","source_card_id":"WD-FR-054","source_chapter_ids":["FR-1158"],"tags":["人情边界","知识交易","继承者保障"]},"retrieval_text":"把一生辅佐谈成有限援手\n交易与信用\n人情边界 知识交易 继承者保障\n一对掌权者愿交出珍贵突破心得，希望你为年轻继承人提供支持，但最初要求一直持续到其坐稳位置。\n长辈想买到可靠的未来保护，你想得到知识而保留自身道路；稳定执政没有明确完成期限。\n掌权长辈：担心身后继承者遭清算，愿调整形式而不愿白送成果。\n继承人：需要外援，也可能不愿时时受监护者干涉。\n玩家与对方有接近对等的谈判地位。\n可交换的知识确有来源，但效果尚不能保证。\n对方没有权利处分知识，或承诺已经被不可更改地订立。\n不固定原著三次或境界名称，接入时需由承诺状态支持；有限援手不等于永久阵营归属，履约条件和消耗规则应明确。"},{"card":{"adaptation_notes":"原著体质可换为维持封印、器物养护或稳定训练；赠予公共资源和请人照护不能暗中捆绑，交接必须让受助者知情。","category":"宗门与派系","choices":[{"action_hint":"custom:delegate_care_duty","continuation":"若三方同意触发条件与联络办法，可在玩家离开期间启用备用照护。","label":"与弟子和同门共同确认替班范围","requires_extension":true,"tradeoff":"需要公开部分个人情况，也要准备相应消耗物。"},{"action_hint":"interact:ask","continuation":"若其已有可靠自助方法，可减少不必要的限制与频繁求助。","label":"询问弟子希望保留哪些自主安排","requires_extension":false,"tradeoff":"可能发现其需求与师长想象不同。"},{"action_hint":"interact:decline","continuation":"待替班者能力或本人安排成熟后，可重新决定出行。","label":"拒绝现在启程，另行安排照护交接","requires_extension":false,"tradeoff":"会推迟自己的计划，但无需仓促把责任交给未准备的人。"}],"conflict":"弟子需要连续支持，同门已有本职事务；仅靠一句人情承诺，可能在真正需要时无人负责。","dedupe_key":"care_duty_backup_before_absence","exclusions":["没有持续照护需求，或弟子明确拒绝该替代人选。"],"followups":[{"closure":"玩家归来、弟子不再需要协助或完成正式转交时结束。","development":"启动事先约定的通知与再交接，不能默认无限延长。","trigger":"玩家行程延长或替班者临时离宗"}],"id":"WD-FR-055","npc_motives":["同门长者：愿帮旧交，却不愿接下无期限的全部师徒责任。","弟子：担心成为负担，希望知道求助渠道及自己能做什么。"],"preconditions":["玩家已有真实持续的照护或指导责任。","同门具有所需能力并愿意讨论替班安排。"],"situation":"你即将闭关或远行，一位依赖定期协助的弟子仍需照料；同门愿帮忙，但尚未商定何时接手和如何联络。","tags":["照护交接","职责边界","后备人选"],"title":"师父远行前的替班人","variation_slots":["需要持续协助的事项","同门可承担的时间与资源"]},"content_version":"2026-10-31.1","id":"WD-FR-055","metadata":{"category":"宗门与派系","dedupe_key":"care_duty_backup_before_absence","source_card_id":"WD-FR-055","source_chapter_ids":["FR-1174"],"tags":["照护交接","职责边界","后备人选"]},"retrieval_text":"师父远行前的替班人\n宗门与派系\n照护交接 职责边界 后备人选\n你即将闭关或远行，一位依赖定期协助的弟子仍需照料；同门愿帮忙，但尚未商定何时接手和如何联络。\n弟子需要连续支持，同门已有本职事务；仅靠一句人情承诺，可能在真正需要时无人负责。\n同门长者：愿帮旧交，却不愿接下无期限的全部师徒责任。\n弟子：担心成为负担，希望知道求助渠道及自己能做什么。\n玩家已有真实持续的照护或指导责任。\n同门具有所需能力并愿意讨论替班安排。\n没有持续照护需求，或弟子明确拒绝该替代人选。\n原著体质可换为维持封印、器物养护或稳定训练；赠予公共资源和请人照护不能暗中捆绑，交接必须让受助者知情。"},{"card":{"adaptation_notes":"用场地权限代替原著专属冰壁与咒术；保护不能抹去闭关者的意愿，改阵、门禁与紧急授权必须有明确状态。","category":"凡俗与旧情","choices":[{"action_hint":"custom:configure_retreat_access","continuation":"若宗门与闭关者认可，可分设普通维护与紧急介入权限。","label":"拟定最小访问名单和应急开门条件","requires_extension":true,"tradeoff":"需要把部分控制权交给可信者，不能做到完全独占。"},{"action_hint":"interact:ask","continuation":"若风险来自流程而非阵力，可先修订交接和巡查安排。","label":"询问掌事者过去有哪些防护漏洞","requires_extension":false,"tradeoff":"会暴露你对现有管理的不放心。"},{"action_hint":"interact:decline","continuation":"原权限继续有效，后续有充分共识时再调整。","label":"暂缓改阵，保留现有守护安排","requires_extension":false,"tradeoff":"可能需缩短自己的外出时间或另请可信同伴照看。"}],"conflict":"你想减少外人接近，掌事者要保留宗门设施责任；封得越严，异常发生时也越难及时介入。","dedupe_key":"sanctuary_security_access_balance","exclusions":["没有场地使用授权，或闭关者明确拒绝更改防护。"],"followups":[{"closure":"闭关结束或防护责任重新交割后结束。","development":"依预先约定联系当事人或备用责任者，避免以保护为名越权。","trigger":"守护者发现异常但未达到强行开门条件"}],"id":"WD-FR-056","npc_motives":["闭关者：需要安静和安全，也希望自身意愿受到尊重。","掌事者：愿提供便利，但需要知道谁能承担故障处理。"],"preconditions":["闭关者或既有授权允许讨论防护调整。","场地属于宗门且原本存在维护人员和访问规则。"],"situation":"亲近之人正在宗门禁地完成关键修炼，你可能暂时离开；掌事者愿让你加强防护，但急救与日常维护仍需通路。","tags":["伴侣保护","私人领地","访问权限"],"title":"闭关之地该由谁开门","variation_slots":["闭关、疗养或研究的使用需求","维护通路和紧急授权形式"]},"content_version":"2026-10-31.1","id":"WD-FR-056","metadata":{"category":"凡俗与旧情","dedupe_key":"sanctuary_security_access_balance","source_card_id":"WD-FR-056","source_chapter_ids":["FR-1174"],"tags":["伴侣保护","私人领地","访问权限"]},"retrieval_text":"闭关之地该由谁开门\n凡俗与旧情\n伴侣保护 私人领地 访问权限\n亲近之人正在宗门禁地完成关键修炼，你可能暂时离开；掌事者愿让你加强防护，但急救与日常维护仍需通路。\n你想减少外人接近，掌事者要保留宗门设施责任；封得越严，异常发生时也越难及时介入。\n闭关者：需要安静和安全，也希望自身意愿受到尊重。\n掌事者：愿提供便利，但需要知道谁能承担故障处理。\n闭关者或既有授权允许讨论防护调整。\n场地属于宗门且原本存在维护人员和访问规则。\n没有场地使用授权，或闭关者明确拒绝更改防护。\n用场地权限代替原著专属冰壁与咒术；保护不能抹去闭关者的意愿，改阵、门禁与紧急授权必须有明确状态。"},{"card":{"adaptation_notes":"秘密传送须源于已有发现，不能临时生成便利捷径；原著破阵可改为封锁通道，任何守护与保密措施需说明对返程的影响。","category":"追逐与藏身","choices":[{"action_hint":"custom:prepare_bounded_remote_aid","continuation":"若形势仍在约定范围且通道测试通过，可前往已确认地点。","label":"先回讯限定可提供的支援并整备通道","requires_extension":true,"tradeoff":"对方可能失望于范围有限，整备也会消耗时间和阵材。"},{"action_hint":"custom:request_remote_status","continuation":"若求援已不再需要到场，可改为双方同意的其他支持。","label":"询问最新战况和集合地点","requires_extension":true,"tradeoff":"通讯存在延迟，回复可能在局势变化后才到。"},{"action_hint":"custom:notify_delayed_aid","continuation":"不强制越级赶赴；对方能据实另找援手，避免把沉默当承诺。","label":"暂缓启程，明确告知尚未具备出发条件","requires_extension":true,"tradeoff":"若确有旧约，需保留未履行事项供双方之后讨论。"}],"conflict":"求援者需要速度，你需要保证返程与居所安全；每多准备一步都可能让现场形势变化。","dedupe_key":"urgent_aid_hidden_return_logistics","exclusions":["传送设施无法修复，或求援真实性已经被否定。"],"followups":[{"closure":"完成约定支援、求援撤回或双方解除义务后结束。","development":"重新核对到场是否仍有意义，并更新留守职责。","trigger":"通道修复完成或求援情势发生重大改变"}],"id":"WD-FR-057","npc_motives":["求援者：希望你尽快赶来，未必知道你的路线准备成本。","留守者：愿看护通道，但需要明确识别来客和求援范围。"],"preconditions":["确有此前建立的求援关系与可修复通道。","玩家已获求援内容，但尚未掌握现场最新情况。"],"situation":"旧友通过约定媒介紧急求援，你掌握一条隐秘捷径，却需要修复入口并安排后方守护，才能放心出发。","tags":["远程求援","秘密通道","后方保障"],"title":"旧约求援与隐秘返程","variation_slots":["隐秘路线的修复与测试成本","留下守护的可控方式"]},"content_version":"2026-10-31.1","id":"WD-FR-057","metadata":{"category":"追逐与藏身","dedupe_key":"urgent_aid_hidden_return_logistics","source_card_id":"WD-FR-057","source_chapter_ids":["FR-1203"],"tags":["远程求援","秘密通道","后方保障"]},"retrieval_text":"旧约求援与隐秘返程\n追逐与藏身\n远程求援 秘密通道 后方保障\n旧友通过约定媒介紧急求援，你掌握一条隐秘捷径，却需要修复入口并安排后方守护，才能放心出发。\n求援者需要速度，你需要保证返程与居所安全；每多准备一步都可能让现场形势变化。\n求援者：希望你尽快赶来，未必知道你的路线准备成本。\n留守者：愿看护通道，但需要明确识别来客和求援范围。\n确有此前建立的求援关系与可修复通道。\n玩家已获求援内容，但尚未掌握现场最新情况。\n传送设施无法修复，或求援真实性已经被否定。\n秘密传送须源于已有发现，不能临时生成便利捷径；原著破阵可改为封锁通道，任何守护与保密措施需说明对返程的影响。"},{"card":{"adaptation_notes":"抽取不可交掉自保筹码的结构，不沿用人物占有叙事；被援者保持自主身份，原文该章只到权衡，交易结果不可提前冒认。","category":"势力博弈","choices":[{"action_hint":"custom:negotiate_safe_release_exchange","continuation":"若双方认可验货与同时放行方式，可继续谈释放条款而不转移人身所有权。","label":"提出满足对方真实需要的替代交换","requires_extension":true,"tradeoff":"必须付出稀缺资产，也可能暴露自己另有资源。"},{"action_hint":"interact:ask","continuation":"若仍有契印或通行限制，需要纳入交换条件。","label":"询问解除控制所需的完整手续","requires_extension":false,"tradeoff":"可能触动对方颜面，却能发现口头放行之外的束缚。"},{"action_hint":"evade:withdraw","continuation":"安全退路存在时可以终止谈判，不强制因拒价爆发决战。","label":"拒绝交出保命筹码，撤离当前对峙","requires_extension":false,"tradeoff":"本轮释放未谈成，后续可由当事人认可的其他途径推进。"}],"conflict":"控制者要利益与体面，你要促成自愿离开又保住谈判安全；交出威慑后可能连履约保障都失去。","dedupe_key":"release_bargain_preserve_deterrence","exclusions":["当事人自愿留下，或玩家没有任何可承担的谈判能力。"],"followups":[{"closure":"当事人自主离开且交换结清，或谈判终止后结束。","development":"可以暂停交割，要求让见证者验证自由已实际恢复。","trigger":"对方接受替代筹码但拖延解除限制"}],"id":"WD-FR-058","npc_motives":["控制者：表面坚持高价，实际更在意某项长期困境。","被控制者：希望恢复自由，不愿被当作再次转交的财产。"],"preconditions":["当事人有明确离开意愿，玩家知道这一意愿。","存在可谈判空间和能约束翻脸的实际筹码。"],"situation":"一位强者控制着你想帮助的人，愿意谈释放，却开口索取你的主要自保手段；现场旁观势力也各有顾虑。","tags":["释放谈判","威慑筹码","真实需求"],"title":"赎回自由不能交掉自保","variation_slots":["控制关系与合法解除方式","强者隐而未宣的长期需求"]},"content_version":"2026-10-31.1","id":"WD-FR-058","metadata":{"category":"势力博弈","dedupe_key":"release_bargain_preserve_deterrence","source_card_id":"WD-FR-058","source_chapter_ids":["FR-1243"],"tags":["释放谈判","威慑筹码","真实需求"]},"retrieval_text":"赎回自由不能交掉自保\n势力博弈\n释放谈判 威慑筹码 真实需求\n一位强者控制着你想帮助的人，愿意谈释放，却开口索取你的主要自保手段；现场旁观势力也各有顾虑。\n控制者要利益与体面，你要促成自愿离开又保住谈判安全；交出威慑后可能连履约保障都失去。\n控制者：表面坚持高价，实际更在意某项长期困境。\n被控制者：希望恢复自由，不愿被当作再次转交的财产。\n当事人有明确离开意愿，玩家知道这一意愿。\n存在可谈判空间和能约束翻脸的实际筹码。\n当事人自愿留下，或玩家没有任何可承担的谈判能力。\n抽取不可交掉自保筹码的结构，不沿用人物占有叙事；被援者保持自主身份，原文该章只到权衡，交易结果不可提前冒认。"},{"card":{"adaptation_notes":"原著死禁改成世界可执行且有明确边界的契约选择，不设必须受控才可继续的唯一主线；能力、消耗和约束需分别实现。","category":"突破与远行","choices":[{"action_hint":"custom:negotiate_transit_safeguards","continuation":"若终止条件和互救范围清楚，可再安排防护轮换与资源分担。","label":"提出只覆盖旅程的可解除保障方案","requires_extension":true,"tradeoff":"较温和的保障可能不被对方接受，需要其他抵押补足。"},{"action_hint":"custom:audit_transit_capacity","continuation":"若发现能力不足，应修订计划，不用约束掩盖技术缺口。","label":"核对通行器的承载与法力消耗","requires_extension":true,"tradeoff":"测试占用开启时间，也会暴露己方储备。"},{"action_hint":"interact:decline","continuation":"未签订的互约不生效，已付的勘察费用按原约处理。","label":"退出本轮启程并保留自己的防护器物","requires_extension":false,"tradeoff":"可能等待很久才有下一窗口，也可能失去此次伙伴。"}],"conflict":"双方想避免临危被抛下，又害怕约束延伸到旅程之后；严厉禁制并不能替代实际的协作准备。","dedupe_key":"uncertain_transit_mutual_restraint","exclusions":["对方已强行控制玩家，无法称为平等互约。"],"followups":[{"closure":"跨越结束且保障解除，或共同方案取消后结束。","development":"需重新评估，并允许在入口未开启或可安全退回时停止。","trigger":"出发前一方临时要求扩大禁制范围"}],"id":"WD-FR-059","npc_motives":["同行者：担心独担通行器损耗，要求你提供可验证的防护贡献。","引路者：希望按窗口出发，仍需确认双方能保有行动能力。"],"preconditions":["已发现真实跨域通路且双方有不同的必要能力。","约束尚未订立，玩家仍可推迟这一轮出发。"],"situation":"跨越未知通路的窗口将近，你与一名并不完全信任的强者互有所需，对方提出互设制约来保证途中不背弃。","tags":["跨界启程","互信不足","资源留存"],"title":"远行伙伴要求相互制约","variation_slots":["跨界、深海或灾区通路","互救保障的期限与解除方式"]},"content_version":"2026-10-31.1","id":"WD-FR-059","metadata":{"category":"突破与远行","dedupe_key":"uncertain_transit_mutual_restraint","source_card_id":"WD-FR-059","source_chapter_ids":["FR-1265"],"tags":["跨界启程","互信不足","资源留存"]},"retrieval_text":"远行伙伴要求相互制约\n突破与远行\n跨界启程 互信不足 资源留存\n跨越未知通路的窗口将近，你与一名并不完全信任的强者互有所需，对方提出互设制约来保证途中不背弃。\n双方想避免临危被抛下，又害怕约束延伸到旅程之后；严厉禁制并不能替代实际的协作准备。\n同行者：担心独担通行器损耗，要求你提供可验证的防护贡献。\n引路者：希望按窗口出发，仍需确认双方能保有行动能力。\n已发现真实跨域通路且双方有不同的必要能力。\n约束尚未订立，玩家仍可推迟这一轮出发。\n对方已强行控制玩家，无法称为平等互约。\n原著死禁改成世界可执行且有明确边界的契约选择，不设必须受控才可继续的唯一主线；能力、消耗和约束需分别实现。"},{"card":{"adaptation_notes":"不把原著不留灯的做法当唯一正确选择；信号可靠性必须公开，失联只改变已约定事务，不强行判定死亡或要求永久等待。","category":"凡俗与旧情","choices":[{"action_hint":"custom:agree_absence_protocol","continuation":"若期限届满仍无消息，留守者可按约恢复生活并保留有限联络点。","label":"共同约定失联后的守候期限与分工","requires_extension":true,"tradeoff":"需要正面谈及不愿面对的失败可能。"},{"action_hint":"interact:ask","continuation":"若现有信物会误报，应先说明限制再由双方决定是否使用。","label":"询问亲友希望接收何种程度的消息","requires_extension":false,"tradeoff":"可能发现彼此对希望和确证的偏好不同。"},{"action_hint":"interact:decline","continuation":"待安排明确后仍可重新选择启程或留下。","label":"拒绝本轮启程，要求另议告别安排","requires_extension":false,"tradeoff":"可能错过当前窗口，但不需要用仓促沉默替代共同决定。"}],"conflict":"远行者希望亲友继续生活，亲友需要知道何时停止等待；保留希望与获得确切消息各有情感代价。","dedupe_key":"absence_signal_waiting_closure","exclusions":["世界已有完全可靠且双方同意使用的即时通讯。"],"followups":[{"closure":"最后一项留守责任完成或可靠消息到来时结束。","development":"按原约减少驻守、归还临借资源，并允许亲友自主安排生活。","trigger":"约定守候期限结束且没有新证据"}],"id":"WD-FR-060","npc_motives":["亲近之人：想收到消息，又不愿无期限占用所有人的生活。","驻守者：愿完成一段守候，需要明确撤守与封闭入口的时机。"],"preconditions":["确有长期失联风险及留守人员。","玩家尚能与亲友讨论消息、物资和入口处置安排。"],"situation":"你准备踏上一段可能长期失联的旅程，亲友愿守候入口；可留下的消息手段并不完善，失败信号也可能含混。","tags":["生死未明","告别安排","等待边界"],"title":"远行后留下什么消息","variation_slots":["通讯可靠程度与失效方式","留下的物资和守候人手"]},"content_version":"2026-10-31.1","id":"WD-FR-060","metadata":{"category":"凡俗与旧情","dedupe_key":"absence_signal_waiting_closure","source_card_id":"WD-FR-060","source_chapter_ids":["FR-1265"],"tags":["生死未明","告别安排","等待边界"]},"retrieval_text":"远行后留下什么消息\n凡俗与旧情\n生死未明 告别安排 等待边界\n你准备踏上一段可能长期失联的旅程，亲友愿守候入口；可留下的消息手段并不完善，失败信号也可能含混。\n远行者希望亲友继续生活，亲友需要知道何时停止等待；保留希望与获得确切消息各有情感代价。\n亲近之人：想收到消息，又不愿无期限占用所有人的生活。\n驻守者：愿完成一段守候，需要明确撤守与封闭入口的时机。\n确有长期失联风险及留守人员。\n玩家尚能与亲友讨论消息、物资和入口处置安排。\n世界已有完全可靠且双方同意使用的即时通讯。\n不把原著不留灯的做法当唯一正确选择；信号可靠性必须公开，失联只改变已约定事务，不强行判定死亡或要求永久等待。"},{"card":{"adaptation_notes":"原著多日失能可按当前世界时间尺度调整；陌生语言与探查用途必须可逐步解释，不能将首次接触直接写成被强制卖身。","category":"生存求道","choices":[{"action_hint":"custom:signal_limited_rescue_consent","continuation":"若对方愿意示范器物用途，可逐步形成最基本的救援沟通。","label":"用简单手势表达求救并限定检查范围","requires_extension":true,"tradeoff":"暴露自己的虚弱，可能失去继续隐匿的机会。"},{"action_hint":"interact:observe","continuation":"若发现明确攻击准备，可改为呼救或使用仍可用的自保手段。","label":"观察探查器与来者的防备反应","requires_extension":false,"tradeoff":"只能取得有限线索，不能凭外形断定器物安全。"},{"action_hint":"interact:decline","continuation":"拒绝本轮接触不会自动造成死亡，后续取决于环境和真实可用的求援方式。","label":"拒绝当前探查并请求暂缓接触","requires_extension":false,"tradeoff":"车队可能不愿继续靠近，帮助因而延后。"}],"conflict":"你需要救助又怕泄露来历，车队要确认是否存在伪装威胁；不沟通会让双方继续猜疑。","dedupe_key":"incapacitated_arrival_identity_check","exclusions":["玩家能轻易自行离开，或对方已直接发动袭击。"],"followups":[{"closure":"达成救援安排、来者离开或玩家恢复自主行动时结束。","development":"可重新询问所在地与救援条件，不必一次交代全部旧事。","trigger":"出现通译或双方确认了基本语言"}],"id":"WD-FR-061","npc_motives":["巡路者：不愿遗弃伤者，但不能贸然把危险带回全队。","商队领队：关注救援成本，也看重伤者可能拥有的生存技能。"],"preconditions":["玩家确有移动或施法能力受限的既有状态。","来者可沟通且尚未表现出明确攻击意图。"],"situation":"穿越事故使你暂时失去主要能力，附近车队发现了你，却因语言不通而保持距离，并拿出用途不明的探查器。","tags":["跨界失能","语言障碍","陌生救援"],"title":"异地获救前的身份核验","variation_slots":["事故导致的暂时能力限制","异地对伪装者的核验习惯"]},"content_version":"2026-10-31.1","id":"WD-FR-061","metadata":{"category":"生存求道","dedupe_key":"incapacitated_arrival_identity_check","source_card_id":"WD-FR-061","source_chapter_ids":["FR-1266"],"tags":["跨界失能","语言障碍","陌生救援"]},"retrieval_text":"异地获救前的身份核验\n生存求道\n跨界失能 语言障碍 陌生救援\n穿越事故使你暂时失去主要能力，附近车队发现了你，却因语言不通而保持距离，并拿出用途不明的探查器。\n你需要救助又怕泄露来历，车队要确认是否存在伪装威胁；不沟通会让双方继续猜疑。\n巡路者：不愿遗弃伤者，但不能贸然把危险带回全队。\n商队领队：关注救援成本，也看重伤者可能拥有的生存技能。\n玩家确有移动或施法能力受限的既有状态。\n来者可沟通且尚未表现出明确攻击意图。\n玩家能轻易自行离开，或对方已直接发动袭击。\n原著多日失能可按当前世界时间尺度调整；陌生语言与探查用途必须可逐步解释，不能将首次接触直接写成被强制卖身。"},{"card":{"adaptation_notes":"使用游戏内一致的期限和真实条款，不将源文数字矛盾推断为蓄意欺诈；任何签约与惩戒都须单独实现并明确告知。","category":"交易与信用","choices":[{"action_hint":"custom:negotiate_rescue_debt","continuation":"若双方认可可结清的债务和退出方式，可再决定是否接受运送。","label":"提出明确救援费用与有限服务范围","requires_extension":true,"tradeoff":"可能需抵押现有资产，商队也可能拒绝替代条件。"},{"action_hint":"interact:ask","continuation":"若口头说明与文字不同，应先要求统一再考虑签署。","label":"逐项询问期限、工作内容和违约机制","requires_extension":false,"tradeoff":"盘问可能令领队不耐烦，但不等于默认接受。"},{"action_hint":"interact:decline","continuation":"环境风险照既有事实发展，不因拒签追加必死惩罚。","label":"拒绝现有文书，保留另寻救援的可能","requires_extension":false,"tradeoff":"商队可停止协商，玩家需依已有条件寻找其他帮助。"}],"conflict":"商队要补偿风险与运力，你需要脱险但无法充分讨价还价；救援费用与长期人身依附混在了一起。","dedupe_key":"rescue_debt_term_comprehension","exclusions":["不存在理解契约的机会，或已经触发立即致命的环境灾变。"],"followups":[{"closure":"契约明确生效、谈判中止或其他救援到达后结束。","development":"重新核对条款，不把先前同意听取解释当作已签约。","trigger":"对方提供修订文书或实际救援成本发生变化"}],"id":"WD-FR-062","npc_motives":["领队：认为可用劳役抵偿成本，希望尽快做出出发决定。","文书执行者：只按现有条款办事，未必有权缩短期限。"],"preconditions":["玩家尚未签署文书，当前有机会询问或提出反案。","商队确实具备带人离开的能力与明确成本。"],"situation":"救援商队愿将伤者带到安全地区，却要求签长期服务文书；你刚能听懂当地话，尚不熟悉契约效力和条款。","tags":["救援债务","期限核对","不对等谈判"],"title":"救援要换多少年自由","variation_slots":["救援费用的可偿还形式","劳役范围与解除条件"]},"content_version":"2026-10-31.1","id":"WD-FR-062","metadata":{"category":"交易与信用","dedupe_key":"rescue_debt_term_comprehension","source_card_id":"WD-FR-062","source_chapter_ids":["FR-1267"],"tags":["救援债务","期限核对","不对等谈判"]},"retrieval_text":"救援要换多少年自由\n交易与信用\n救援债务 期限核对 不对等谈判\n救援商队愿将伤者带到安全地区，却要求签长期服务文书；你刚能听懂当地话，尚不熟悉契约效力和条款。\n商队要补偿风险与运力，你需要脱险但无法充分讨价还价；救援费用与长期人身依附混在了一起。\n领队：认为可用劳役抵偿成本，希望尽快做出出发决定。\n文书执行者：只按现有条款办事，未必有权缩短期限。\n玩家尚未签署文书，当前有机会询问或提出反案。\n商队确实具备带人离开的能力与明确成本。\n不存在理解契约的机会，或已经触发立即致命的环境灾变。\n使用游戏内一致的期限和真实条款，不将源文数字矛盾推断为蓄意欺诈；任何签约与惩戒都须单独实现并明确告知。"},{"card":{"adaptation_notes":"将原著灵具、指环和功法名称转成当地公开技术；发现功能不等于瞬间掌握制造，试用、能力登记和耗材支付需额外支持。","category":"身份与秘密","choices":[{"action_hint":"interact:ask","continuation":"若获得公开使用说明，可更新对当地护卫能力的判断。","label":"询问器具依靠什么耗材与限制","requires_extension":false,"tradeoff":"会暴露自己对当地常识陌生，可能引来更多来历问题。"},{"action_hint":"custom:request_safe_tool_demo","continuation":"只有演示实际证明可行，才可进一步考虑采购或学习。","label":"请求用非破坏方式演示日常功能","requires_extension":true,"tradeoff":"需要支付耗材或工坊费用，使用者也可拒绝。"},{"action_hint":"interact:decline","continuation":"对方若有正式要求，可另约有见证的测试，不默认认定玩家作假。","label":"拒绝进一步能力测试，结束本轮交流","requires_extension":false,"tradeoff":"可能得不到岗位评级或器具购买资格。"}],"conflict":"护卫需要确认你的能力等级，你想了解技术却不愿暴露全部底细；旧有身份判断在此地失去可靠性。","dedupe_key":"mundane_magitech_status_recalibration","exclusions":["玩家已经熟悉同类技术，或工具能力只是未经证实的传闻。"],"followups":[{"closure":"技术差异得到清楚说明或玩家不再追问时结束。","development":"可以用此前观察选择学习方向，避免仍按旧世界标准估量所有人。","trigger":"玩家进入工坊或申请当地岗位"}],"id":"WD-FR-063","npc_motives":["器具使用者：想完成例行工作，也怕被隐瞒实力者戏弄。","工坊学徒：愿讲基本用途，却不能擅自展示核心制造方法。"],"preconditions":["玩家来自技术规则不同的地域。","现场确有无需同等修为即可使用的工具与可交谈使用者。"],"situation":"在新地域，普通护卫拿着你原以为只有修士能用的器具；一次常规检查显示你的身体强度远超他们预期。","tags":["知识落差","技术扩散","实力误判"],"title":"凡人也能使用的异地器具","variation_slots":["凡人可使用的灵力设备","岗位评级和耗材来源"]},"content_version":"2026-10-31.1","id":"WD-FR-063","metadata":{"category":"身份与秘密","dedupe_key":"mundane_magitech_status_recalibration","source_card_id":"WD-FR-063","source_chapter_ids":["FR-1267"],"tags":["知识落差","技术扩散","实力误判"]},"retrieval_text":"凡人也能使用的异地器具\n身份与秘密\n知识落差 技术扩散 实力误判\n在新地域，普通护卫拿着你原以为只有修士能用的器具；一次常规检查显示你的身体强度远超他们预期。\n护卫需要确认你的能力等级，你想了解技术却不愿暴露全部底细；旧有身份判断在此地失去可靠性。\n器具使用者：想完成例行工作，也怕被隐瞒实力者戏弄。\n工坊学徒：愿讲基本用途，却不能擅自展示核心制造方法。\n玩家来自技术规则不同的地域。\n现场确有无需同等修为即可使用的工具与可交谈使用者。\n玩家已经熟悉同类技术，或工具能力只是未经证实的传闻。\n将原著灵具、指环和功法名称转成当地公开技术；发现功能不等于瞬间掌握制造，试用、能力登记和耗材支付需额外支持。"},{"card":{"adaptation_notes":"保留部分展示实力与换取合理职位的矛盾，不照搬功法层数；玩家是否反击、受聘或接受新职责都必须独立选择。","category":"宗门与派系","choices":[{"action_hint":"custom:set_employment_test_boundary","continuation":"若雇主承认试探，可用有限测试换取对应职权，而不展示全部能力。","label":"制止进一步接触并要求正式考核标准","requires_extension":true,"tradeoff":"可能被视为不好管理，影响录用或晋升。"},{"action_hint":"interact:ask","continuation":"只有职责和风险清楚，展示实力才有可比较的报酬依据。","label":"询问拟任岗位的责任与调遣范围","requires_extension":false,"tradeoff":"会把话题转向实际条件，雇主可能回避未公开的任务。"},{"action_hint":"evade:withdraw","continuation":"若雇主后来愿公开条件，可以重新预约，不默认必须回归。","label":"终止面谈并撤离有冲突的院门","requires_extension":false,"tradeoff":"可能失去这次职位，但无需继续承受未经同意的试探。"}],"conflict":"雇主想找到能担重任的人，你需要工作却不愿接受无边界试探；公开还手又可能损伤双方体面。","dedupe_key":"covert_employment_test_role_boundary","exclusions":["玩家已被明确告知并同意同样方式的考核。"],"followups":[{"closure":"签订明确岗位约定或双方结束雇佣接洽时结束。","development":"可据已谈职责重新议价，能力被看见不等于无限服从。","trigger":"雇主以此次表现要求承担额外危险差事"}],"id":"WD-FR-064","npc_motives":["雇主：愿提高有能力者待遇，也习惯以隐蔽考验掌握下属。","守门侍卫：奉命试探却怕失去威信，可能在失败后继续加力。"],"preconditions":["双方正在洽谈或调整可自愿终止的雇佣关系。","侍卫试探尚未造成必须持续战斗的局面。"],"situation":"雇主邀你面谈，门前侍卫却先动手试探；从内院反应看，这可能是一次未事先说明的任职考核。","tags":["雇佣考核","体面","能力隐藏"],"title":"入职之前先受一场试探","variation_slots":["测试方式与拟任职位","雇主需要隐藏的实际任务"]},"content_version":"2026-10-31.1","id":"WD-FR-064","metadata":{"category":"宗门与派系","dedupe_key":"covert_employment_test_role_boundary","source_card_id":"WD-FR-064","source_chapter_ids":["FR-1278"],"tags":["雇佣考核","体面","能力隐藏"]},"retrieval_text":"入职之前先受一场试探\n宗门与派系\n雇佣考核 体面 能力隐藏\n雇主邀你面谈，门前侍卫却先动手试探；从内院反应看，这可能是一次未事先说明的任职考核。\n雇主想找到能担重任的人，你需要工作却不愿接受无边界试探；公开还手又可能损伤双方体面。\n雇主：愿提高有能力者待遇，也习惯以隐蔽考验掌握下属。\n守门侍卫：奉命试探却怕失去威信，可能在失败后继续加力。\n双方正在洽谈或调整可自愿终止的雇佣关系。\n侍卫试探尚未造成必须持续战斗的局面。\n玩家已被明确告知并同意同样方式的考核。\n保留部分展示实力与换取合理职位的矛盾，不照搬功法层数；玩家是否反击、受聘或接受新职责都必须独立选择。"},{"card":{"adaptation_notes":"把特定丹药改成可核验的环境适应服务，不固定原著年数；说明是来访者提供的信息，制度和风险须经世界事实支持。","category":"势力博弈","choices":[{"action_hint":"custom:verify_residency_care_terms","continuation":"若标准可核验，可据实际负担决定适合的短期职务。","label":"要求公开领取条件与解除居留义务的标准","requires_extension":true,"tradeoff":"可能发现处理周期较长，必须重新安排远行计划。"},{"action_hint":"interact:ask","continuation":"多方说法若一致，可帮助区分必要依赖与自愿享受资源。","label":"询问已获自由者为何继续留下","requires_extension":false,"tradeoff":"个人经验可能有偏向，不能替代正式规则。"},{"action_hint":"interact:decline","continuation":"待资格与规则查明后再决定长期去留。","label":"暂缓额外任职，先维持已获准的临时安置","requires_extension":false,"tradeoff":"可能不能领取某些额外资源，但不应擅自失去已有基础照护。"}],"conflict":"城池需要可靠的守卫与人口，新来者需要稳定庇护；对关键资源的依赖可能限制选择工作和居所的自由。","dedupe_key":"newcomer_residency_service_lockin","exclusions":["玩家已无相关后遗症且不受其他居留义务约束。"],"followups":[{"closure":"取得独立生存条件并明确去留时结束。","development":"按公开标准复核义务，允许在条件满足时选择离开。","trigger":"适应指标达标或城方更改供给条件"}],"id":"WD-FR-065","npc_motives":["接待者：希望新人尽快适应，倾向强调城内资源优势。","老住民：已经可以离城，却认为留下有利于自身修行。"],"preconditions":["玩家确有需持续处理的跨界适应问题。","城内处理办法存在可核实来源和领取制度。","玩家已获临时安置与基础照护，尚未接受额外任职。"],"situation":"你抵达一座能处理跨界后遗症的城池，接待者称需要长期接受供给；这里资源丰富，但居留与职务规则尚不清楚。","tags":["制度依赖","新来者","资源换服务"],"title":"需要庇护才可自由离城","variation_slots":["跨界适应的虚构生理机制","城池供给与服务关系"]},"content_version":"2026-10-31.1","id":"WD-FR-065","metadata":{"category":"势力博弈","dedupe_key":"newcomer_residency_service_lockin","source_card_id":"WD-FR-065","source_chapter_ids":["FR-1317"],"tags":["制度依赖","新来者","资源换服务"]},"retrieval_text":"需要庇护才可自由离城\n势力博弈\n制度依赖 新来者 资源换服务\n你抵达一座能处理跨界后遗症的城池，接待者称需要长期接受供给；这里资源丰富，但居留与职务规则尚不清楚。\n城池需要可靠的守卫与人口，新来者需要稳定庇护；对关键资源的依赖可能限制选择工作和居所的自由。\n接待者：希望新人尽快适应，倾向强调城内资源优势。\n老住民：已经可以离城，却认为留下有利于自身修行。\n玩家确有需持续处理的跨界适应问题。\n城内处理办法存在可核实来源和领取制度。\n玩家已获临时安置与基础照护，尚未接受额外任职。\n玩家已无相关后遗症且不受其他居留义务约束。\n把特定丹药改成可核验的环境适应服务，不固定原著年数；说明是来访者提供的信息，制度和风险须经世界事实支持。"},{"card":{"adaptation_notes":"无需沿用特定异界强者作为追索者，应从玩家既有关系中选取；拒绝披露不默认等于可疑敌人，也不自动揭开真实出身。","category":"身份与秘密","choices":[{"action_hint":"custom:set_disclosure_boundary","continuation":"若对方尊重边界，互助仍可从公开信息开始。","label":"说明愿交流生活问题，故乡细节暂不公开","requires_extension":true,"tradeoff":"可能降低对方即时信任，需靠后续相处逐渐建立关系。"},{"action_hint":"interact:ask","continuation":"若分类只需宽泛信息，可回答必要部分而不编造具体故乡。","label":"先询问当地如何分类外来者","requires_extension":false,"tradeoff":"会显得不熟悉常识，也可能引出对方继续追问。"},{"action_hint":"interact:leave","continuation":"结束会面不自动损害声誉，其他公开渠道仍按既有条件可用。","label":"婉拒此次来访，约有需要再接洽","requires_extension":false,"tradeoff":"暂时失去一个信息来源，对方也可能不再主动拜访。"}],"conflict":"来者靠出身确认互助关系，你希望获取信息又担心旧事被追索；拒绝过硬会损失交往机会，坦白过多难以收回。","dedupe_key":"diaspora_network_origin_disclosure","exclusions":["来历早已公开且无可识别的新增泄露风险。"],"followups":[{"closure":"双方形成稳定披露边界或停止交往时结束。","development":"再次界定哪些信息可以转述，不把私下交谈视为公开授权。","trigger":"邻人愿介绍其他同类或代办事务"}],"id":"WD-FR-066","npc_motives":["热心邻人：想扩展互助圈，也对罕见的新来者感到好奇。","新住民：愿分享当前需求，但不愿让旧乡亲友受到牵连。"],"preconditions":["玩家身处陌生社会，尚无稳定信息渠道。","故乡信息确实关联一项已有的隐私或追索风险。"],"situation":"新住处刚安顿好，一位自称同类出身的邻人便来拜访，热心介绍当地规则，也随口问起你的具体故乡。","tags":["侨居网络","来历隐私","选择披露"],"title":"同乡来访先问哪一界","variation_slots":["旧乡关联的隐私风险","互助圈所需的最低身份信息"]},"content_version":"2026-10-31.1","id":"WD-FR-066","metadata":{"category":"身份与秘密","dedupe_key":"diaspora_network_origin_disclosure","source_card_id":"WD-FR-066","source_chapter_ids":["FR-1317"],"tags":["侨居网络","来历隐私","选择披露"]},"retrieval_text":"同乡来访先问哪一界\n身份与秘密\n侨居网络 来历隐私 选择披露\n新住处刚安顿好，一位自称同类出身的邻人便来拜访，热心介绍当地规则，也随口问起你的具体故乡。\n来者靠出身确认互助关系，你希望获取信息又担心旧事被追索；拒绝过硬会损失交往机会，坦白过多难以收回。\n热心邻人：想扩展互助圈，也对罕见的新来者感到好奇。\n新住民：愿分享当前需求，但不愿让旧乡亲友受到牵连。\n玩家身处陌生社会，尚无稳定信息渠道。\n故乡信息确实关联一项已有的隐私或追索风险。\n来历早已公开且无可识别的新增泄露风险。\n无需沿用特定异界强者作为追索者，应从玩家既有关系中选取；拒绝披露不默认等于可疑敌人，也不自动揭开真实出身。"},{"card":{"adaptation_notes":"把原著面积和百年限制转成游戏已有尺度，土地选择应基于玩家用途；低价值标签不暗示必藏宝物，申请和占用需明确状态。","category":"机缘与代价","choices":[{"action_hint":"custom:apply_land_by_use","continuation":"若实地资料支持需求，可承担这些成本换取更大活动范围。","label":"按用途列明最低条件后申请偏远地块","requires_extension":true,"tradeoff":"可能需要额外交通和供能，日常修炼效率也较低。"},{"action_hint":"interact:ask","continuation":"若规则尚允许延后登记，可先核实争议边界和维护责任。","label":"询问更换规则及首次申请减免","requires_extension":false,"tradeoff":"会显露新来者身份，但可能避免不必要的支出。"},{"action_hint":"interact:decline","continuation":"保留选择权不自动生成更优地块，之后依真实供应重新评估。","label":"暂不登记，继续使用现有临时住处","requires_extension":false,"tradeoff":"可能错过本轮空地，需要承担临住费用。"}],"conflict":"多数人追求修炼效率，你可能更需要空间或隐私；避开热门地点并不等于免除长期的使用成本。","dedupe_key":"land_use_priority_lockin","exclusions":["地块条件完全未知，无法比较用途与长期约束。"],"followups":[{"closure":"完成自愿登记或决定等待下一轮时结束。","development":"按公布的复核规则处理，不能仅因不满意就无成本换地。","trigger":"实地勘察发现地图未注明的使用限制"}],"id":"WD-FR-067","npc_motives":["管理者：希望按统一规则分配稀缺用地，不愿为个人偏好反复更改。","其他申请人：以灵气评判价值，未必理解特殊用途。"],"preconditions":["玩家有建居或设置设施的真实需求。","地图公开地块基本条件与选择后限制。","玩家仍有可合法停留的临时住处，其有效期尚未届满。"],"situation":"管理处开放一批长期居住用地，优质小地块竞争激烈，一处偏远大地块灵气较差；登记后很长时间不能改换。","tags":["土地选择","长期锁定","非主流需求"],"title":"低灵气的大地盘","variation_slots":["空间、安静、灵气或交通的权重","登记期限与公共设施责任"]},"content_version":"2026-10-31.1","id":"WD-FR-067","metadata":{"category":"机缘与代价","dedupe_key":"land_use_priority_lockin","source_card_id":"WD-FR-067","source_chapter_ids":["FR-1320"],"tags":["土地选择","长期锁定","非主流需求"]},"retrieval_text":"低灵气的大地盘\n机缘与代价\n土地选择 长期锁定 非主流需求\n管理处开放一批长期居住用地，优质小地块竞争激烈，一处偏远大地块灵气较差；登记后很长时间不能改换。\n多数人追求修炼效率，你可能更需要空间或隐私；避开热门地点并不等于免除长期的使用成本。\n管理者：希望按统一规则分配稀缺用地，不愿为个人偏好反复更改。\n其他申请人：以灵气评判价值，未必理解特殊用途。\n玩家有建居或设置设施的真实需求。\n地图公开地块基本条件与选择后限制。\n玩家仍有可合法停留的临时住处，其有效期尚未届满。\n地块条件完全未知，无法比较用途与长期约束。\n把原著面积和百年限制转成游戏已有尺度，土地选择应基于玩家用途；低价值标签不暗示必藏宝物，申请和占用需明确状态。"},{"card":{"adaptation_notes":"区别于初次选地，此卡只在已登记状态触发；原著境界威胁可改成实际可观察实力，退出损失必须事前公布且有限。","category":"宗门与派系","choices":[{"action_hint":"custom:seek_claim_adjudication","continuation":"若管理方确认程序，可据自己能力选择继续主张或撤回。","label":"要求公开裁定竞争程序与责任边界","requires_extension":true,"tradeoff":"会把纠纷摆到台面，可能需要承担正式比试或举证成本。"},{"action_hint":"interact:ask","continuation":"若存在合法补偿且足以覆盖损失，可另行讨论，不私改登记记录。","label":"询问对方是否能提供规则允许的补偿","requires_extension":false,"tradeoff":"谈判可能被误读为愿意退出，需先说明尚未同意。"},{"action_hint":"custom:withdraw_land_claim","continuation":"这是可承担的自然机会成本，不追加永久封杀或强制追杀。","label":"撤回本轮申请并离开争执现场","requires_extension":true,"tradeoff":"将失去已公开说明的本轮机会，需继续租住或等下一次。"}],"conflict":"对方想取得特定用地，你不能轻易承受放弃机会的损失；管事维护规则却不主动调解威胁。","dedupe_key":"registered_claim_late_coercive_rival","exclusions":["玩家没有既有申请，或对方提供了玩家已接受的替代安排。"],"followups":[{"closure":"使用权归属确定或玩家撤回后结束。","development":"依据同一规则重新评估，避免靠暗改地图解决矛盾。","trigger":"管理方公布裁定或对方提出新的交换条件"}],"id":"WD-FR-068","npc_motives":["竞争者：倚仗实力和关系，认为压低弱者成本最省事。","登记管事：不愿为个案破例，但需维持公开流程可信。"],"preconditions":["玩家已自主登记且尚未取得最终使用权。","当地存在已知竞争规则，而非任意强者随时夺地。"],"situation":"你已按规则登记一处冷门地块，后来者声称只有这里适合其技艺，要求你退出；管事表示当前规则不许改选。","tags":["既有申请","制度刚性","威胁与救济"],"title":"登记以后才来的强势竞争者","variation_slots":["正式竞争采用的方式","放弃资格的既有成本"]},"content_version":"2026-10-31.1","id":"WD-FR-068","metadata":{"category":"宗门与派系","dedupe_key":"registered_claim_late_coercive_rival","source_card_id":"WD-FR-068","source_chapter_ids":["FR-1320"],"tags":["既有申请","制度刚性","威胁与救济"]},"retrieval_text":"登记以后才来的强势竞争者\n宗门与派系\n既有申请 制度刚性 威胁与救济\n你已按规则登记一处冷门地块，后来者声称只有这里适合其技艺，要求你退出；管事表示当前规则不许改选。\n对方想取得特定用地，你不能轻易承受放弃机会的损失；管事维护规则却不主动调解威胁。\n竞争者：倚仗实力和关系，认为压低弱者成本最省事。\n登记管事：不愿为个案破例，但需维持公开流程可信。\n玩家已自主登记且尚未取得最终使用权。\n当地存在已知竞争规则，而非任意强者随时夺地。\n玩家没有既有申请，或对方提供了玩家已接受的替代安排。\n区别于初次选地，此卡只在已登记状态触发；原著境界威胁可改成实际可观察实力，退出损失必须事前公布且有限。"},{"card":{"adaptation_notes":"不照搬异族天然敌对，潜伏者需有当前冲突背景；延期申请和撤退权应存在于制度中，观察动作不能自动完成整片巡逻。","category":"宗门与派系","choices":[{"action_hint":"custom:plan_patrol_risk_protocol","continuation":"若能与邻队协调，可用互相确认减少盲区，但不能保证不会伏击。","label":"共同制定巡段、交接和失联撤回条件","requires_extension":true,"tradeoff":"降低推进速度，可能需要向调度说明覆盖不足。"},{"action_hint":"interact:ask","continuation":"若记录显示某段反复失联，可优先申请支援或修订路线。","label":"询问老队员过去失事的位置和征兆","requires_extension":false,"tradeoff":"可能暴露队内意见分歧，也未必取得完整记录。"},{"action_hint":"custom:request_patrol_deferral","continuation":"不必强闯以证明勇气，复核结果决定是否改派、补给或另议职责。","label":"暂缓进入高危地带并申请复核准备条件","requires_extension":true,"tradeoff":"可能影响轮值评价，需按已有制度交代原因。"}],"conflict":"上级要维持边界监视，队员需要可信的生存安排；队长若只表现镇定，无法消除信息不对称。","dedupe_key":"hazard_patrol_leadership_shared_evidence","exclusions":["队伍尚未成立，或命令没有任何有效来源。"],"followups":[{"closure":"轮值结束或职责正式移交后结束。","development":"按预定阈值撤回通报，不将继续深入当默认勇敢行为。","trigger":"探测器失灵、邻队失联或遇超出能力的征兆"}],"id":"WD-FR-069","npc_motives":["老队员：愿履职，但怕新队长把谨慎误当怯懦。","调度者：需要覆盖空缺巡段，未必掌握一线设备的全部局限。"],"preconditions":["玩家已接受或拥有小队领导职责。","巡区风险和设备局限已有可核查记录。"],"situation":"你刚接手一支巡逻队就收到高风险区域的轮值，老队员知道过去的损失，现配探测器却有盲区和漏报可能。","tags":["风险沟通","集体责任","有限探测"],"title":"新队长收到高危巡区","variation_slots":["侦测工具的盲区机制","撤回阈值与邻队联络"]},"content_version":"2026-10-31.1","id":"WD-FR-069","metadata":{"category":"宗门与派系","dedupe_key":"hazard_patrol_leadership_shared_evidence","source_card_id":"WD-FR-069","source_chapter_ids":["FR-1330"],"tags":["风险沟通","集体责任","有限探测"]},"retrieval_text":"新队长收到高危巡区\n宗门与派系\n风险沟通 集体责任 有限探测\n你刚接手一支巡逻队就收到高风险区域的轮值，老队员知道过去的损失，现配探测器却有盲区和漏报可能。\n上级要维持边界监视，队员需要可信的生存安排；队长若只表现镇定，无法消除信息不对称。\n老队员：愿履职，但怕新队长把谨慎误当怯懦。\n调度者：需要覆盖空缺巡段，未必掌握一线设备的全部局限。\n玩家已接受或拥有小队领导职责。\n巡区风险和设备局限已有可核查记录。\n队伍尚未成立，或命令没有任何有效来源。\n不照搬异族天然敌对，潜伏者需有当前冲突背景；延期申请和撤退权应存在于制度中，观察动作不能自动完成整片巡逻。"},{"card":{"adaptation_notes":"不把原著概率直接当固定死亡率；组织者说法需与任务记录对照，拒绝专项任务不等于逃亡，任职与资格变更须显式支持。","category":"势力博弈","choices":[{"action_hint":"custom:verify_service_exit_path","continuation":"若功勋认定与资格发放均有依据，再决定接受哪项具体任务。","label":"核对任务成果如何换取正式退役文书","requires_extension":true,"tradeoff":"需透露自身打算，领袖可能要求先保密。"},{"action_hint":"interact:ask","continuation":"若战争判断尚弱或留守分工改善，可重新权衡去留。","label":"询问情报来源与留下者的轮值安排","requires_extension":false,"tradeoff":"可能被视为动摇士气，但有助于避免只比较片面风险。"},{"action_hint":"interact:decline","continuation":"后续应依据真实局势另行决定，不强制惩罚未接高危委托者。","label":"拒绝这批远行任务，维持现有职责","requires_extension":false,"tradeoff":"放弃本次提前退役机会，既有守备责任仍按规则存在。"}],"conflict":"互助领袖想保存群体力量又不能公开逃避共同防务，成员则要衡量即时任务风险与尚未发生的战争。","dedupe_key":"minority_service_risk_exit_option","exclusions":["玩家本来可以无代价自由退出，或战争已经使远行方案不可执行。"],"followups":[{"closure":"正式退役、任务拒绝或相关制度方案失效时结束。","development":"允许在未出发前复核同意，已履行部分按原约核算。","trigger":"战争预警改变或任务认定规则被修改"}],"id":"WD-FR-070","npc_motives":["互助领袖：争取制度内的退路，也怕被指控只保护本群体。","普通成员：受过高危派遣，不愿再用模糊承诺换取冒险。"],"preconditions":["玩家确有受制度约束的服役状态。","退役办法来自有权限的组织者，且任务和战争风险可分别说明。"],"situation":"外来者互助会告知边城可能遭围攻，提出一批能换取退役资格的远行任务；留下守城和接任务各有不确定危险。","tags":["新来者互助","风险分配","合法退出"],"title":"用高功勋任务换退役资格","variation_slots":["外来群体与既有居民的任务差异","可核验的功勋退役标准"]},"content_version":"2026-10-31.1","id":"WD-FR-070","metadata":{"category":"势力博弈","dedupe_key":"minority_service_risk_exit_option","source_card_id":"WD-FR-070","source_chapter_ids":["FR-1356"],"tags":["新来者互助","风险分配","合法退出"]},"retrieval_text":"用高功勋任务换退役资格\n势力博弈\n新来者互助 风险分配 合法退出\n外来者互助会告知边城可能遭围攻，提出一批能换取退役资格的远行任务；留下守城和接任务各有不确定危险。\n互助领袖想保存群体力量又不能公开逃避共同防务，成员则要衡量即时任务风险与尚未发生的战争。\n互助领袖：争取制度内的退路，也怕被指控只保护本群体。\n普通成员：受过高危派遣，不愿再用模糊承诺换取冒险。\n玩家确有受制度约束的服役状态。\n退役办法来自有权限的组织者，且任务和战争风险可分别说明。\n玩家本来可以无代价自由退出，或战争已经使远行方案不可执行。\n不把原著概率直接当固定死亡率；组织者说法需与任务记录对照，拒绝专项任务不等于逃亡，任职与资格变更须显式支持。"},{"card":{"adaptation_notes":"把原著种族与等级换成当前阵营和真实侦测规则；游戏应保留带明确代价的退出途径，不复刻只能被迫接下的结构。","category":"同盟与背叛","choices":[{"action_hint":"custom:reconfirm_joint_mission_scope","continuation":"若新增条件可接受，可重新确认参与范围而不承诺无限救援。","label":"要求先说明必要分工与撤退联络再出发","requires_extension":true,"tradeoff":"领队可能只在封闭环境说明，准备时间因此增加。"},{"action_hint":"interact:ask","continuation":"若能力能覆盖不同风险，可据实际分工缓和境界争执。","label":"询问侦测门槛及各人的独特能力","requires_extension":false,"tradeoff":"可能触动队员隐私，需区分任务必需信息与全部底牌。"},{"action_hint":"evade:withdraw","continuation":"新增条件未获同意时不能强写玩家继续深入，退路仍需具备现实可行性。","label":"暂缓深入，撤回已确认的集合外缘","requires_extension":false,"tradeoff":"可能需要按原约另议解约成本，并失去本次任务收益。"}],"conflict":"领队用分段保密保护情报，队员需要充分知情才能分担风险；更高修为反而可能触发目标区的侦测。","dedupe_key":"joint_mission_late_scope_disclosure","exclusions":["全部任务信息和队员分工已充分披露，不存在新增条件。"],"followups":[{"closure":"任务范围重新确认、共同目标完成或玩家安全退出时结束。","development":"成员可暂停推进并重谈分工，已共同掌握的秘密按原约保护。","trigger":"途中再次披露超出原约的任务目的"}],"id":"WD-FR-071","npc_motives":["联合领队：希望赶上交接窗口，不愿当众透露卧底全貌。","强势队员：想避免被拖累，却把境界高低当作唯一可靠标准。"],"preconditions":["玩家曾接到任务概要，但关键条件在会合后才披露。","潜入区域确有明确的实力侦测门槛。"],"situation":"你抵达秘密集合点，发现同行者来自多个阵营，任务也比招募时复杂；领队催促先上路，部分人又质疑你的实力。","tags":["联合行动","信息不对称","实力偏见"],"title":"会合后才知道任务真貌","variation_slots":["不同阵营各自掌握的信息","潜入门槛与必要特殊能力"]},"content_version":"2026-10-31.1","id":"WD-FR-071","metadata":{"category":"同盟与背叛","dedupe_key":"joint_mission_late_scope_disclosure","source_card_id":"WD-FR-071","source_chapter_ids":["FR-1358"],"tags":["联合行动","信息不对称","实力偏见"]},"retrieval_text":"会合后才知道任务真貌\n同盟与背叛\n联合行动 信息不对称 实力偏见\n你抵达秘密集合点，发现同行者来自多个阵营，任务也比招募时复杂；领队催促先上路，部分人又质疑你的实力。\n领队用分段保密保护情报，队员需要充分知情才能分担风险；更高修为反而可能触发目标区的侦测。\n联合领队：希望赶上交接窗口，不愿当众透露卧底全貌。\n强势队员：想避免被拖累，却把境界高低当作唯一可靠标准。\n玩家曾接到任务概要，但关键条件在会合后才披露。\n潜入区域确有明确的实力侦测门槛。\n全部任务信息和队员分工已充分披露，不存在新增条件。\n把原著种族与等级换成当前阵营和真实侦测规则；游戏应保留带明确代价的退出途径，不复刻只能被迫接下的结构。"},{"card":{"adaptation_notes":"原著玉简被毁是实际事件，游戏不保证重复这一结果；封存、分权阅读与防篡改都属于新增状态，跟踪者须有追踪依据。","category":"身份与秘密","choices":[{"action_hint":"custom:joint_seal_intelligence","continuation":"若各方接受见证与封存，之后可按任务权限逐项查阅。","label":"先共同封存，转到安全点再分拣公开与私密部分","requires_extension":true,"tradeoff":"会推迟读取急讯，需要可信的防篡改办法。"},{"action_hint":"interact:ask","continuation":"若只是担心私讯，可提出最小披露原则，而不授予任何一方独占权。","label":"询问各方主张优先阅读的具体依据","requires_extension":false,"tradeoff":"透露争议范围，仍不能确认谁真正拥有全部材料。"},{"action_hint":"evade:withdraw","continuation":"脱离暴露区后可继续协商，不强制把离开解释为背叛任务。","label":"停止现场争阅，撤向已经确认的集合点","requires_extension":false,"tradeoff":"可能失去当场影响保管决定的机会，材料仍由现持有人掌握。"}],"conflict":"共同任务需要完整情报，各方又要保护自己人的秘密；现场争夺会延长暴露时间，并增加材料被毁的机会。","dedupe_key":"shared_intelligence_private_payload_custody","exclusions":["情报已公开，或有各方认可且可立即执行的保管规则。"],"followups":[{"closure":"材料按约交付、被可靠证据确认失效或玩家退出争议时结束。","development":"优先保存可验证的交接记录，再决定是否恢复读取。","trigger":"发现尾随、封印破损或材料疑被删改"}],"id":"WD-FR-072","npc_motives":["持有人：担心交出后被删改，要求保留取件证明。","他方代表：怕本方卧底身份流入竞争者手中，不接受无监督阅读。"],"preconditions":["情报确由多方共同参与的行动留下。","材料尚未读取或分拣，现场不具备充分保密条件。"],"situation":"联合队伍找到一份卧底留下的材料，不同阵营都说其中可能有本方私讯，持有人尚未决定谁先查看或如何带走。","tags":["共同情报","卧底隐私","保管争议"],"title":"一份情报有几位主人","variation_slots":["材料媒介与防篡改方式","各阵营应保护的私密信息"]},"content_version":"2026-10-31.1","id":"WD-FR-072","metadata":{"category":"身份与秘密","dedupe_key":"shared_intelligence_private_payload_custody","source_card_id":"WD-FR-072","source_chapter_ids":["FR-1376"],"tags":["共同情报","卧底隐私","保管争议"]},"retrieval_text":"一份情报有几位主人\n身份与秘密\n共同情报 卧底隐私 保管争议\n联合队伍找到一份卧底留下的材料，不同阵营都说其中可能有本方私讯，持有人尚未决定谁先查看或如何带走。\n共同任务需要完整情报，各方又要保护自己人的秘密；现场争夺会延长暴露时间，并增加材料被毁的机会。\n持有人：担心交出后被删改，要求保留取件证明。\n他方代表：怕本方卧底身份流入竞争者手中，不接受无监督阅读。\n情报确由多方共同参与的行动留下。\n材料尚未读取或分拣，现场不具备充分保密条件。\n情报已公开，或有各方认可且可立即执行的保管规则。\n原著玉简被毁是实际事件，游戏不保证重复这一结果；封存、分权阅读与防篡改都属于新增状态，跟踪者须有追踪依据。"},{"card":{"adaptation_notes":"目标物可替成构件或地图，避免集中药物；原著收服试验尚未发生，此卡所有服务分支均为游戏改编，不预写成功。","category":"交易与信用","choices":[{"action_hint":"custom:inspect_service_before_contract","continuation":"若实际风险可承受，可约定尝试费、完成条件与停止阈值。","label":"要求先勘验目标，再订分阶段服务约定","requires_extension":true,"tradeoff":"勘验可能收费，也可能暴露自己的应对能力。"},{"action_hint":"interact:ask","continuation":"明确标准后可比较是否值得承担，尚不因此自动订约。","label":"询问需要控制到何种程度才算履约","requires_extension":false,"tradeoff":"卖家可能坚持最终成果才付款，不接受仅作尝试。"},{"action_hint":"interact:decline","continuation":"卖家可另聘他人，不因拒绝而凭空降低价格或赠送货物。","label":"拒绝未知风险的服务交换","requires_extension":false,"tradeoff":"暂时得不到目标物，可继续寻找替代供应或方案。"}],"conflict":"卖家想解决自己办不到的控制难题，你需要确定付出到哪一步才可得报酬；能力展示不等于接受所有风险。","dedupe_key":"specialist_barter_acceptance_threshold","exclusions":["卖家拿不出物品或拒绝承认任何可检验的完成标准。"],"followups":[{"closure":"服务结算、双方取消或玩家放弃采购时结束。","development":"触发重新议价或停止条款，不用已付准备成本强迫继续。","trigger":"现场目标与事先说明有实质差别"}],"id":"WD-FR-073","npc_motives":["卖家：已请多人失败，担心泄露目标秘密却又缺合适帮手。","专业协助者：能处理某类力量，但对未知目标并无无限把握。"],"preconditions":["玩家确有可证明的相关能力与真实采购需求。","所需物品确在卖家控制之下，交易尚未成交。"],"situation":"卖家只肯以特殊材料、高价或一项专业服务换出所需物品；服务看似合你专长，却不肯先说明目标的全部性质。","tags":["能力换物","验收标准","风险披露"],"title":"代劳能否算完成交换","variation_slots":["需要的特殊技艺与服务目标","分阶段验收和停止条件"]},"content_version":"2026-10-31.1","id":"WD-FR-073","metadata":{"category":"交易与信用","dedupe_key":"specialist_barter_acceptance_threshold","source_card_id":"WD-FR-073","source_chapter_ids":["FR-1422"],"tags":["能力换物","验收标准","风险披露"]},"retrieval_text":"代劳能否算完成交换\n交易与信用\n能力换物 验收标准 风险披露\n卖家只肯以特殊材料、高价或一项专业服务换出所需物品；服务看似合你专长，却不肯先说明目标的全部性质。\n卖家想解决自己办不到的控制难题，你需要确定付出到哪一步才可得报酬；能力展示不等于接受所有风险。\n卖家：已请多人失败，担心泄露目标秘密却又缺合适帮手。\n专业协助者：能处理某类力量，但对未知目标并无无限把握。\n玩家确有可证明的相关能力与真实采购需求。\n所需物品确在卖家控制之下，交易尚未成交。\n卖家拿不出物品或拒绝承认任何可检验的完成标准。\n目标物可替成构件或地图，避免集中药物；原著收服试验尚未发生，此卡所有服务分支均为游戏改编，不预写成功。"},{"card":{"adaptation_notes":"敌群再生必须有可观察的空间条件，不提供无限刷取奖励；不要把离开林地等同击败守护者，转移和损耗需由战术状态处理。","category":"探索与禁制","choices":[{"action_hint":"custom:cover_environmental_disengagement","continuation":"若再生确受边界限制，可先完成通行，再决定是否从安全侧调查。","label":"以有限掩护集中转移队伍到边缘外","requires_extension":true,"tradeoff":"需要承担器械损耗，落后成员可能拖慢脱离。"},{"action_hint":"interact:observe","continuation":"若外侧碎片持续失活，可把这一证据用于下一步路线选择。","label":"观察破碎物在边缘两侧的反应","requires_extension":false,"tradeoff":"观察得到的只是一处局部现象，不能直接断定整片林地相同。"},{"action_hint":"evade:withdraw","continuation":"抵达安全侧后可自行决定修整或放弃，不强制再探再生源。","label":"停止深入，撤回先前已确认的入口外侧","requires_extension":false,"tradeoff":"本轮探索停滞，已经消耗的护卫资源不会恢复。"}],"conflict":"战斗者想清除所有威胁，领路者要保存资源继续前行；敌人的再生似乎来自地形，硬杀未必推进目标。","dedupe_key":"regenerating_guardians_environment_boundary","exclusions":["守卫并无环境依赖，或边界方向只是未经证实的猜测。"],"followups":[{"closure":"队伍脱离该区域并不再调查时结束。","development":"已有记录可供比较，但需重新确认是否同一机制。","trigger":"队伍再次接近同类环境或边界现象改变"}],"id":"WD-FR-074","npc_motives":["护卫操作者：担心损耗耗尽后无人掩护，主张尽快脱离。","探险者：怀疑林中有再生源，愿为了解机制多留片刻。"],"preconditions":["已多次观察到同一守卫在特定区域重组。","玩家能辨认区域边缘，且存在尚可抵达的安全侧。"],"situation":"一片林地的守卫被击碎后总会重组，队伍的护卫器械已开始损耗；少数碎片落到边缘外后出现不同反应。","tags":["环境依赖","消耗战","边界观察"],"title":"打不完的守林骸骨","variation_slots":["再生依赖的地形或能源","掩护资源与队伍移动能力"]},"content_version":"2026-10-31.1","id":"WD-FR-074","metadata":{"category":"探索与禁制","dedupe_key":"regenerating_guardians_environment_boundary","source_card_id":"WD-FR-074","source_chapter_ids":["FR-1492"],"tags":["环境依赖","消耗战","边界观察"]},"retrieval_text":"打不完的守林骸骨\n探索与禁制\n环境依赖 消耗战 边界观察\n一片林地的守卫被击碎后总会重组，队伍的护卫器械已开始损耗；少数碎片落到边缘外后出现不同反应。\n战斗者想清除所有威胁，领路者要保存资源继续前行；敌人的再生似乎来自地形，硬杀未必推进目标。\n护卫操作者：担心损耗耗尽后无人掩护，主张尽快脱离。\n探险者：怀疑林中有再生源，愿为了解机制多留片刻。\n已多次观察到同一守卫在特定区域重组。\n玩家能辨认区域边缘，且存在尚可抵达的安全侧。\n守卫并无环境依赖，或边界方向只是未经证实的猜测。\n敌群再生必须有可观察的空间条件，不提供无限刷取奖励；不要把离开林地等同击败守护者，转移和损耗需由战术状态处理。"},{"card":{"adaptation_notes":"原著后来遭控制不是本卡必然结果；应在仍可自主选择的阶段触发，追踪、同伴意愿和解印过程不能仅靠一句撤退完成。","category":"追逐与藏身","choices":[{"action_hint":"custom:coordinate_marked_escape","continuation":"若出现真实空隙且各人愿意，可分工争取足够的脱离距离。","label":"与同伴约定解印所需的安全时间与会合条件","requires_extension":true,"tradeoff":"协调本身可能被察觉，隐匿手段也未必能覆盖多人。"},{"action_hint":"custom:monitor_guard_handoff","continuation":"若有重复出现的空隙，可作为计划依据，不直接生成逃跑成功。","label":"观察监视者的交班和感知范围","requires_extension":true,"tradeoff":"可能只能发现常规习惯，不能保证下次仍照常。"},{"action_hint":"evade:withdraw","continuation":"可以保存手段等待新条件，也可另寻协商解除限制的途径。","label":"中止当前逃离尝试，退回公开行进位置","requires_extension":false,"tradeoff":"继续承受既有监视，放弃这一刻尚不可靠的机会。"}],"conflict":"独逃更容易却可能被再次定位，集体撤离需要协调并增加暴露风险；同伴也有自身意愿和能力限制。","dedupe_key":"escape_depends_on_mark_removal_companion","exclusions":["印记可由玩家随时自解，或同伴并不愿参与撤离。"],"followups":[{"closure":"所有参与者自愿脱困、解除印记或放弃共同计划时结束。","development":"按实际条件重新核对方案，不能让未同意者被自动带走。","trigger":"监视者离开、同伴受伤或印记开始报警"}],"id":"WD-FR-075","npc_motives":["解印同伴：愿共同脱困，但不能在追逐中立即施术。","监视者：奉命阻止人员失散，熟悉常见隐匿方式。"],"preconditions":["追索印记与监视来自已经发生的剧情状态。","同伴确有相关解印知识，玩家拥有可验证的短时脱离手段。"],"situation":"你有短暂避开监视的手段，却无法独自清除追索印记；懂解法的同伴也在队伍中，监视者几乎寸步不离。","tags":["互相依赖","监视","结伴撤离"],"title":"自己能逃，同伴才会解印","variation_slots":["定位机制与解印准备要求","短时隐匿手段的容量限制"]},"content_version":"2026-10-31.1","id":"WD-FR-075","metadata":{"category":"追逐与藏身","dedupe_key":"escape_depends_on_mark_removal_companion","source_card_id":"WD-FR-075","source_chapter_ids":["FR-1492"],"tags":["互相依赖","监视","结伴撤离"]},"retrieval_text":"自己能逃，同伴才会解印\n追逐与藏身\n互相依赖 监视 结伴撤离\n你有短暂避开监视的手段，却无法独自清除追索印记；懂解法的同伴也在队伍中，监视者几乎寸步不离。\n独逃更容易却可能被再次定位，集体撤离需要协调并增加暴露风险；同伴也有自身意愿和能力限制。\n解印同伴：愿共同脱困，但不能在追逐中立即施术。\n监视者：奉命阻止人员失散，熟悉常见隐匿方式。\n追索印记与监视来自已经发生的剧情状态。\n同伴确有相关解印知识，玩家拥有可验证的短时脱离手段。\n印记可由玩家随时自解，或同伴并不愿参与撤离。\n原著后来遭控制不是本卡必然结果；应在仍可自主选择的阶段触发，追踪、同伴意愿和解印过程不能仅靠一句撤退完成。"},{"card":{"adaptation_notes":"不把成为异类天然写成更坏的结局，冲突来自当事人的明确偏好；原章只提出可能兼解，不能替后文编造已经找到的秘法。","category":"师徒与控制","choices":[{"action_hint":"custom:negotiate_apprenticeship_priority","continuation":"若能明确保留调查时间及中止条件，再由受邀者决定是否拜师。","label":"协助当事人向导师提出复原优先的条件","requires_extension":true,"tradeoff":"导师可能拒绝降低近期要求，机缘因此错失。"},{"action_hint":"interact:ask","continuation":"若没有可靠依据，应保留未知，而不替当事人保证将来必能恢复。","label":"询问双方掌握哪些关于复原期限的证据","requires_extension":false,"tradeoff":"可能揭示同伴只凭愿望相信以后总能补救。"},{"action_hint":"interact:decline","continuation":"受邀者可自行选择求证、拒绝或再谈，同行者不自动替其承诺。","label":"拒绝代替当事人作决定，暂缓劝说","requires_extension":false,"tradeoff":"争议暂时没有结论，导师可能继续等待回应。"}],"conflict":"名师能提供安全和成长，当事人却担心错过恢复原状的时机；同伴看重的庇护未必等于其本人最想要的生活。","dedupe_key":"apprenticeship_identity_recovery_deadline","exclusions":["当事人已明确自愿接受且没有新条件，或变化可随时无代价逆转。"],"followups":[{"closure":"邀约被自愿接受、拒绝或延期约定形成时结束。","development":"更新权衡依据，由受邀者确认自身目标是否改变。","trigger":"导师明确时限或找到新的复原资料"}],"id":"WD-FR-076","npc_motives":["受邀者：希望保留原来的身份与身体，不愿以力量替代这个目标。","劝留同伴：害怕再度漂泊失去彼此，愿替她寻找办法却缺充分把握。"],"preconditions":["收徒邀约确实附带近期时间投入。","身份或体质变化已有可观察进程，而复原方法仍待寻找。"],"situation":"一位强者愿收你的同行者为徒，却要求其集中修炼以协助近期要事；对方原本计划远行解决正在加深的身体变化。","tags":["拜师代价","身份变化","目标冲突"],"title":"名师机缘挤占复原时机","variation_slots":["身份变化的机制与复原目标","导师近期需要的具体协助"]},"content_version":"2026-10-31.1","id":"WD-FR-076","metadata":{"category":"师徒与控制","dedupe_key":"apprenticeship_identity_recovery_deadline","source_card_id":"WD-FR-076","source_chapter_ids":["FR-1519"],"tags":["拜师代价","身份变化","目标冲突"]},"retrieval_text":"名师机缘挤占复原时机\n师徒与控制\n拜师代价 身份变化 目标冲突\n一位强者愿收你的同行者为徒，却要求其集中修炼以协助近期要事；对方原本计划远行解决正在加深的身体变化。\n名师能提供安全和成长，当事人却担心错过恢复原状的时机；同伴看重的庇护未必等于其本人最想要的生活。\n受邀者：希望保留原来的身份与身体，不愿以力量替代这个目标。\n劝留同伴：害怕再度漂泊失去彼此，愿替她寻找办法却缺充分把握。\n收徒邀约确实附带近期时间投入。\n身份或体质变化已有可观察进程，而复原方法仍待寻找。\n当事人已明确自愿接受且没有新条件，或变化可随时无代价逆转。\n不把成为异类天然写成更坏的结局，冲突来自当事人的明确偏好；原章只提出可能兼解，不能替后文编造已经找到的秘法。"},{"card":{"adaptation_notes":"保留告警与防护的能力差别，避免阵法凭空反制绝对强者；休息需要实际时间状态，普通结束互动不能自动恢复疲劳。","category":"身份与秘密","choices":[{"action_hint":"custom:request_guest_privacy_alarm","continuation":"若许可明确，告警只提供发现窥视的机会，不冒充能抵挡强者。","label":"先说明仅设置告警，再安排私人休整","requires_extension":true,"tradeoff":"会暴露你对主人的戒心，管事可能限制阵具使用。"},{"action_hint":"interact:ask","continuation":"若边界可核实，可据此选择会谈地点与离府安排。","label":"询问可活动范围与联系管事的方法","requires_extension":false,"tradeoff":"可能得到严格规则，仍有助于避免误入敏感区域。"},{"action_hint":"custom:defer_talk_for_rest","continuation":"只要主人的回复期限尚有余量，休整可以结束当前谈话而不失去自主选择。","label":"谢绝当晚讨论，延期到休息之后","requires_extension":true,"tradeoff":"会推迟做决定，同行者可能仍想单独商谈。"}],"conflict":"主人希望客人遵守府内秩序，客人需要基本隐私；过强防护可能被误解，完全不设防又使会谈难以安心。","dedupe_key":"guest_privacy_alarm_under_power_gap","exclusions":["现场正在战斗，或房间本身已被证明会造成持续伤害。"],"followups":[{"closure":"离府、双方确认新住宿规则或本次休整结束时结束。","development":"先核对原因和已获许可，不自动将来访判为谋害。","trigger":"告警触发或管事要求临时进入客房"}],"id":"WD-FR-077","npc_motives":["管事：愿满足合理需求，但不允许客人试探禁区。","疲惫同伴：想尽快商议去留，判断力却已受连日奔波影响。"],"preconditions":["玩家已获得临时住宿许可，主人没有即时伤害行为。","存在可说明用途的低强度窥视告警手段。"],"situation":"疲惫的队伍暂住在远强于自己的主人府中，管事划出可活动范围；你需要休整，也不想在不知情时被旁听。","tags":["客居规则","休整","监视告警"],"title":"强者客房中的有限隐私","variation_slots":["告警型阵具的感知能力","主人公开的客居禁区"]},"content_version":"2026-10-31.1","id":"WD-FR-077","metadata":{"category":"身份与秘密","dedupe_key":"guest_privacy_alarm_under_power_gap","source_card_id":"WD-FR-077","source_chapter_ids":["FR-1519"],"tags":["客居规则","休整","监视告警"]},"retrieval_text":"强者客房中的有限隐私\n身份与秘密\n客居规则 休整 监视告警\n疲惫的队伍暂住在远强于自己的主人府中，管事划出可活动范围；你需要休整，也不想在不知情时被旁听。\n主人希望客人遵守府内秩序，客人需要基本隐私；过强防护可能被误解，完全不设防又使会谈难以安心。\n管事：愿满足合理需求，但不允许客人试探禁区。\n疲惫同伴：想尽快商议去留，判断力却已受连日奔波影响。\n玩家已获得临时住宿许可，主人没有即时伤害行为。\n存在可说明用途的低强度窥视告警手段。\n现场正在战斗，或房间本身已被证明会造成持续伤害。\n保留告警与防护的能力差别，避免阵法凭空反制绝对强者；休息需要实际时间状态，普通结束互动不能自动恢复疲劳。"},{"card":{"adaptation_notes":"原文只确认复通和聚集，收费、船商与调度矛盾为改编扩展；须以世界实际存在的旅客、设施和订单为前提，不捏造原著修复细节。","category":"突破与远行","choices":[{"action_hint":"custom:coordinate_reopened_route_queue","continuation":"若相关方接受，可减少插队争执，并让未上阵者知道下一批依据。","label":"提出按承载能力分批并公开维护费用","requires_extension":true,"tradeoff":"需要协调人手与记录，不能让所有人立即通行。"},{"action_hint":"interact:ask","continuation":"若信息可核实，可向已有求询者说明实际限制，是否迁移由其决定。","label":"询问首批通行证据、终点和回程条件","requires_extension":false,"tradeoff":"可能拖慢宣传进度，也会让夸大承诺者难堪。"},{"action_hint":"interact:decline","continuation":"可以等待公开规则完善，或按原计划使用仍然存在的其他路线。","label":"拒绝承担调度职责，保留自己原有出行安排","requires_extension":false,"tradeoff":"可能仍需排队，且得不到管理服务的报酬。"}],"conflict":"旅客想尽快离开，守阵者要控制负荷并筹集维护费，船商担心运力与旧订单失去安排；抢先通行会挤压他人。","dedupe_key":"reopened_route_public_capacity_allocation","exclusions":["复通只属传言，或设施仍未通过任何有效测试。"],"followups":[{"closure":"管理职责交接或公共通行秩序稳定后结束。","development":"据实调整批次和费用，已售资格按公布规则退款或延期。","trigger":"首批返回报告出现负荷或落点问题"}],"id":"WD-FR-078","npc_motives":["守阵者：需要证明复通可靠，不愿首批人流压坏刚修好的设施。","滞留旅客：已付旧航路费用，希望得到清楚的改签或等待方案。"],"preconditions":["通路已完成至少一次真实成功通行。","当前已有排队需求，玩家具备被认可的协商或技术角色。","当地确有受到新通路影响的旧航线或既存运输订单。"],"situation":"孤立地区的旧传送路恢复可用，等待返乡的人突然涌来；守阵者请你协助首批通行安排，旧航路经营者也提出质疑。","tags":["公共通行","资源调度","地方利益"],"title":"旧通路复开后的拥挤队伍","variation_slots":["复开的公共交通设施","当地旧订单与维护成本"]},"content_version":"2026-10-31.1","id":"WD-FR-078","metadata":{"category":"突破与远行","dedupe_key":"reopened_route_public_capacity_allocation","source_card_id":"WD-FR-078","source_chapter_ids":["FR-1561"],"tags":["公共通行","资源调度","地方利益"]},"retrieval_text":"旧通路复开后的拥挤队伍\n突破与远行\n公共通行 资源调度 地方利益\n孤立地区的旧传送路恢复可用，等待返乡的人突然涌来；守阵者请你协助首批通行安排，旧航路经营者也提出质疑。\n旅客想尽快离开，守阵者要控制负荷并筹集维护费，船商担心运力与旧订单失去安排；抢先通行会挤压他人。\n守阵者：需要证明复通可靠，不愿首批人流压坏刚修好的设施。\n滞留旅客：已付旧航路费用，希望得到清楚的改签或等待方案。\n通路已完成至少一次真实成功通行。\n当前已有排队需求，玩家具备被认可的协商或技术角色。\n当地确有受到新通路影响的旧航线或既存运输订单。\n复通只属传言，或设施仍未通过任何有效测试。\n原文只确认复通和聚集，收费、船商与调度矛盾为改编扩展；须以世界实际存在的旅客、设施和订单为前提，不捏造原著修复细节。"},{"card":{"adaptation_notes":"原著涉及元神消散与轮回，改编采用可存续灵体的自由和记忆交付；不强迫自毁，分离技术、解除拘束和验收均须显式支持。","category":"交易与信用","choices":[{"action_hint":"custom:stage_release_information_exchange","continuation":"若每阶段证据符合约定，再进行下一步，不以新的隐性控制替换旧拘束。","label":"共同约定分阶段放行与内容核验","requires_extension":true,"tradeoff":"需投入安置时间，双方仍各承担一部分无法完全消除的风险。"},{"action_hint":"interact:ask","continuation":"若当事人不愿承担损失，应保留取消交换的权利。","label":"询问分离准备会造成哪些不可逆损失","requires_extension":false,"tradeoff":"可能发现原方案代价过高，需要另寻见证或保管办法。"},{"action_hint":"custom:release_without_secret_claim","continuation":"若不存在其他人的有效限制，灵体可自行去留，不自动转为忠诚随从。","label":"拒绝索取秘密，解除自己掌握的拘束","requires_extension":true,"tradeoff":"会放弃对知识的独占机会，仍需处理旧器的合法归属。"}],"conflict":"保管者想得到真实知识，灵体要保留最后的自主权；全部放行或全部交密，都把风险压在同一方身上。","dedupe_key":"release_information_sequential_exchange","exclusions":["灵体不能自主表达，或世界没有支持分步交付的技术。"],"followups":[{"closure":"双方履约、灵体自由离开或共同取消交换后结束。","development":"暂停后续交付并重谈，已经恢复的自主权不应暗中撤回。","trigger":"准备完成或记忆副本无法通过约定核验"}],"id":"WD-FR-079","npc_motives":["受困灵体：愿留下可核验的记忆副本，但不愿交出全部意识供操控。","器物保管者：担心副本空白或误导，也需承担准备期间的安置成本。"],"preconditions":["灵体具有明确意愿与可分离的记忆载体机制。","玩家确实控制一项可解除的拘束，交换尚未生效。"],"situation":"一位受困的有识灵体愿交出旧器中的秘密，条件是恢复自身自由；双方都怕先履行后失去让对方兑现的保障。","tags":["分步交付","受困灵体","信任保障"],"title":"放行与交密谁先一步","variation_slots":["记忆副本与见证方式","所附器物的所有权关系"]},"content_version":"2026-10-31.1","id":"WD-FR-079","metadata":{"category":"交易与信用","dedupe_key":"release_information_sequential_exchange","source_card_id":"WD-FR-079","source_chapter_ids":["FR-1667"],"tags":["分步交付","受困灵体","信任保障"]},"retrieval_text":"放行与交密谁先一步\n交易与信用\n分步交付 受困灵体 信任保障\n一位受困的有识灵体愿交出旧器中的秘密，条件是恢复自身自由；双方都怕先履行后失去让对方兑现的保障。\n保管者想得到真实知识，灵体要保留最后的自主权；全部放行或全部交密，都把风险压在同一方身上。\n受困灵体：愿留下可核验的记忆副本，但不愿交出全部意识供操控。\n器物保管者：担心副本空白或误导，也需承担准备期间的安置成本。\n灵体具有明确意愿与可分离的记忆载体机制。\n玩家确实控制一项可解除的拘束，交换尚未生效。\n灵体不能自主表达，或世界没有支持分步交付的技术。\n原著涉及元神消散与轮回，改编采用可存续灵体的自由和记忆交付；不强迫自毁，分离技术、解除拘束和验收均须显式支持。"},{"card":{"adaptation_notes":"战场必须由离开期间的既有势力行动形成，不是无因惊变；返回、受袭和支援分开处理，观察不得自动发动攻击或认定阵营。","category":"生存求道","choices":[{"action_hint":"custom:cover_return_arrivals","continuation":"若同伴实际到达且愿协作，可临时分担掩护后一起寻找安全点。","label":"只在可守范围内接应下一批归来者","requires_extension":true,"tradeoff":"需要消耗剩余防护，可能错过最快的个人撤离时机。"},{"action_hint":"interact:observe","continuation":"若看见可靠指挥或撤离信号，可据其更新行动，而不默认加入某方。","label":"观察阵区标识、兵力与尚存掩护","requires_extension":false,"tradeoff":"短暂观察不等于掌握全城形势，敌我身份也可能不完整。"},{"action_hint":"evade:withdraw","continuation":"安全后可另行通报位置或继续离城，不强制追回战场。","label":"脱离交火落点，撤向已经辨认的掩护区","requires_extension":false,"tradeoff":"暂时无法照顾所有后来者，也可能失去与旧队的即时联系。"}],"conflict":"守阵者需要有人保护陆续归来的旅客，你需要保住有限余力并辨认局势；仓促追击会离开可接应的位置。","dedupe_key":"return_portal_battlefield_reassessment","exclusions":["返程目的地没有战事依据，或场景无法提供任何可行动空间。"],"followups":[{"closure":"脱离交火区、完成有限接应或传送结束时结束。","development":"按实际余力重谈分工，境界变化不自动赋予领队权。","trigger":"新的归来者到达或守阵方发布可核实命令"}],"id":"WD-FR-080","npc_motives":["守阵者：想保住通路，急需知道归来者能承担多少支援。","归来同伴：经历不同消耗与成长，未必还能沿用出发时分工。"],"preconditions":["玩家已从真实远行或秘境返回。","目的地战事有既存原因，且现场仍有可观察的掩护路线。"],"situation":"返程把你送回曾经安全的阵区，却发现防护残破、双方交战；后续同伴还将出现，你尚不清楚城内指挥与撤离路线。","tags":["返程突变","落点确认","有限救援"],"title":"归来时落点已成战场","variation_slots":["远行期间已经发生的城内事件","返程批次与安全掩护位置"]},"content_version":"2026-10-31.1","id":"WD-FR-080","metadata":{"category":"生存求道","dedupe_key":"return_portal_battlefield_reassessment","source_card_id":"WD-FR-080","source_chapter_ids":["FR-1747"],"tags":["返程突变","落点确认","有限救援"]},"retrieval_text":"归来时落点已成战场\n生存求道\n返程突变 落点确认 有限救援\n返程把你送回曾经安全的阵区，却发现防护残破、双方交战；后续同伴还将出现，你尚不清楚城内指挥与撤离路线。\n守阵者需要有人保护陆续归来的旅客，你需要保住有限余力并辨认局势；仓促追击会离开可接应的位置。\n守阵者：想保住通路，急需知道归来者能承担多少支援。\n归来同伴：经历不同消耗与成长，未必还能沿用出发时分工。\n玩家已从真实远行或秘境返回。\n目的地战事有既存原因，且现场仍有可观察的掩护路线。\n返程目的地没有战事依据，或场景无法提供任何可行动空间。\n战场必须由离开期间的既有势力行动形成，不是无因惊变；返回、受袭和支援分开处理，观察不得自动发动攻击或认定阵营。"},{"card":{"adaptation_notes":"将雷法改成两项互补技能，偏差须由遗漏或条件不符产生。新增分期验收与知识交付状态，不能用询问动作直接获得完整技能。","category":"同盟与背叛","choices":[{"action_hint":"custom:reciprocal_technique_test","continuation":"若双方都能复现，可继续交换下一段；任一方失败则暂停。","label":"提议双方分段演示并交叉复现","requires_extension":true,"tradeoff":"耗费材料与时间，己方技巧也会逐步暴露。"},{"action_hint":"interact:ask","continuation":"若问题来自条件差异，可自行补足；若拒答，可重谈条件。","label":"先问清已传内容的适用限制","requires_extension":false,"tradeoff":"对方可能只给原则说明，暂时拿不到诀窍。"},{"action_hint":"interact:decline","continuation":"以后有新筹码或可靠见证时，双方可自愿重谈。","label":"拒绝本轮交换，保留各自技艺","requires_extension":false,"tradeoff":"短期无法补齐弱项，也不会自动结下仇怨。"}],"conflict":"双方都想学到完整技艺，又担心先交底会丧失唯一筹码，互相保留可能让交换一同失效。","dedupe_key":"mutual_knowhow_withholding","exclusions":["对方已明确不愿交流，或没有可交换的知识"],"followups":[{"closure":"双方验收完成、明确终止或不再往来即结束。","development":"可凭失败记录要求补充说明，或认定交易未完成而止损。","trigger":"已交换技巧在实用时出现可重复的偏差"}],"id":"WD-FR-081","npc_motives":["对手技师：想补齐自己的短板，但不愿免费暴露族传诀窍。","引荐人：希望争斗止息，不愿为未经检验的讲义担保。"],"preconditions":["双方各有对方确实需要的技术","实力接近，暂能停止冲突"],"situation":"一位曾与你交手的异乡技师提出交换两种独门技巧。双方均能展示成果，却无法直接判断对方交出的讲义是否足够复现。","tags":["技术互换","互不信任","验收","同阶对手"],"title":"互留一手的技艺交换","variation_slots":["双方掌握的技术","可验证的试验场地"]},"content_version":"2026-10-31.1","id":"WD-FR-081","metadata":{"category":"同盟与背叛","dedupe_key":"mutual_knowhow_withholding","source_card_id":"WD-FR-081","source_chapter_ids":["FR-1756"],"tags":["技术互换","互不信任","验收","同阶对手"]},"retrieval_text":"互留一手的技艺交换\n同盟与背叛\n技术互换 互不信任 验收 同阶对手\n一位曾与你交手的异乡技师提出交换两种独门技巧。双方均能展示成果，却无法直接判断对方交出的讲义是否足够复现。\n双方都想学到完整技艺，又担心先交底会丧失唯一筹码，互相保留可能让交换一同失效。\n对手技师：想补齐自己的短板，但不愿免费暴露族传诀窍。\n引荐人：希望争斗止息，不愿为未经检验的讲义担保。\n双方各有对方确实需要的技术\n实力接近，暂能停止冲突\n对方已明确不愿交流，或没有可交换的知识\n将雷法改成两项互补技能，偏差须由遗漏或条件不符产生。新增分期验收与知识交付状态，不能用询问动作直接获得完整技能。"},{"card":{"adaptation_notes":"下界与仙域改成两个有明确管辖范围的地区。监察感应须有既存检测能力；隐藏禁令只提供线索，不能突然判玩家违法或强制抓捕。","category":"身份与秘密","choices":[{"action_hint":"interact:ask","continuation":"若获得可核验条文，可据此另定路线或办理说明。","label":"向知情者核实禁令与申辩条件","requires_extension":false,"tradeoff":"会暴露自己对禁法的关心，回答也可能有偏差。"},{"action_hint":"custom:preclearance_disclosure","continuation":"若存在豁免程序，可进入审查；否则须另作安排。","label":"申请先行审核并公开必要信息","requires_extension":true,"tradeoff":"身份与修行记录可能留档，许可仍可能遭拒。"},{"action_hint":"interact:leave","continuation":"在规则、资质或行程需求变化时再评估。","label":"延期越境，结束本次咨询","requires_extension":false,"tradeoff":"失去近期出行机会，但仍可维持现有生活。"}],"conflict":"你希望保留已有本领并顺利过境，监察方要求识别禁法使用者，两地规则无法直接互认。","dedupe_key":"jurisdiction_delayed_prohibition","exclusions":["只是普通技艺，目的地并无对应禁令"],"followups":[{"closure":"取得明确处理结果，或玩家取消该目的地计划。","development":"对照先前情报确认适用范围，允许补件或取消行程。","trigger":"收到正式查验通知或新的禁令证据"}],"id":"WD-FR-082","npc_motives":["旧地传授者：认为本地修行合法，但不了解外境处罚程序。","边境知情人：愿解释查验项目，不肯承诺包过。"],"preconditions":["玩家已有某项可辨认的修行痕迹","计划前往规则不同的已知地区"],"situation":"你修炼已久的一门技艺在本地无人追究，近期却得知目的地将其列为禁法。边境验核可能辨认修炼痕迹，而消息尚待核实。","tags":["禁术","辖区","监察","远行准备"],"title":"越境才显现的禁令","variation_slots":["禁法对应的技能","边境审核机构"]},"content_version":"2026-10-31.1","id":"WD-FR-082","metadata":{"category":"身份与秘密","dedupe_key":"jurisdiction_delayed_prohibition","source_card_id":"WD-FR-082","source_chapter_ids":["FR-1762"],"tags":["禁术","辖区","监察","远行准备"]},"retrieval_text":"越境才显现的禁令\n身份与秘密\n禁术 辖区 监察 远行准备\n你修炼已久的一门技艺在本地无人追究，近期却得知目的地将其列为禁法。边境验核可能辨认修炼痕迹，而消息尚待核实。\n你希望保留已有本领并顺利过境，监察方要求识别禁法使用者，两地规则无法直接互认。\n旧地传授者：认为本地修行合法，但不了解外境处罚程序。\n边境知情人：愿解释查验项目，不肯承诺包过。\n玩家已有某项可辨认的修行痕迹\n计划前往规则不同的已知地区\n只是普通技艺，目的地并无对应禁令\n下界与仙域改成两个有明确管辖范围的地区。监察感应须有既存检测能力；隐藏禁令只提供线索，不能突然判玩家违法或强制抓捕。"},{"card":{"adaptation_notes":"宝鼎改成可追溯来历的器物，旧誓只在玩家确已立誓时启用。原著归还结果不预设为游戏结局，产权和承诺须单独记录。","category":"交易与信用","choices":[{"action_hint":"custom:selective_restitution_trade","continuation":"若归属核实且交付完成，对方可记下明确而有限的人情。","label":"只接受自己确实需要的一项回报","requires_extension":true,"tradeoff":"放弃更高售价，并失去旧器带来的便利。"},{"action_hint":"interact:ask","continuation":"若说明无法自洽，可停止议价而继续保管。","label":"先询问旧器用途与传承凭证","requires_extension":false,"tradeoff":"暂缓交易可能令对方焦急，也会暴露自己的疑虑。"},{"action_hint":"interact:decline","continuation":"对方若另寻替代物，事件可自然结束。","label":"拒绝此次转让，结束会谈","requires_extension":false,"tradeoff":"保留旧器，也可能失去本次报价与合作机会。"}],"conflict":"来客看重旧器的传承意义，你看重使用价值与过去恩情，高额报价未必符合双方真正所需。","dedupe_key":"restitution_with_selective_compensation","exclusions":["物品属于第三方寄存，玩家无权转让"],"followups":[{"closure":"物与报酬交接无争议，约定人情兑现或被放弃。","development":"对方按约提供信息或有限帮助，不凭人情无限输送资源。","trigger":"归还后对方找到传承线索，或玩家确有相关求助"}],"id":"WD-FR-083","npc_motives":["传人代表：想找回传承线索，愿付重价却承受不起反复加码。","家族管事：愿履行承诺，但担心赎物耗尽族中储备。"],"preconditions":["玩家合法持有有历史来历的物品","来客能提供与旧物有关的可核验信息"],"situation":"一名失散传人的代表认出你长期使用的旧器，愿倾尽家产赎回。此物仍归你合法持有，也确曾在危急时帮助过你。","tags":["物归原主","旧恩","报价","心愿"],"title":"归还旧物而不索尽价","variation_slots":["旧器的历史用途","可选择的补偿形式"]},"content_version":"2026-10-31.1","id":"WD-FR-083","metadata":{"category":"交易与信用","dedupe_key":"restitution_with_selective_compensation","source_card_id":"WD-FR-083","source_chapter_ids":["FR-1782"],"tags":["物归原主","旧恩","报价","心愿"]},"retrieval_text":"归还旧物而不索尽价\n交易与信用\n物归原主 旧恩 报价 心愿\n一名失散传人的代表认出你长期使用的旧器，愿倾尽家产赎回。此物仍归你合法持有，也确曾在危急时帮助过你。\n来客看重旧器的传承意义，你看重使用价值与过去恩情，高额报价未必符合双方真正所需。\n传人代表：想找回传承线索，愿付重价却承受不起反复加码。\n家族管事：愿履行承诺，但担心赎物耗尽族中储备。\n玩家合法持有有历史来历的物品\n来客能提供与旧物有关的可核验信息\n物品属于第三方寄存，玩家无权转让\n宝鼎改成可追溯来历的器物，旧誓只在玩家确已立誓时启用。原著归还结果不预设为游戏结局，产权和承诺须单独记录。"},{"card":{"adaptation_notes":"原著长期救治与搜寻条件改成明确疗程、能力门槛和复议期限。不得替玩家或后辈默认立誓；师徒身份、治疗进度需扩展状态。","category":"师徒与控制","choices":[{"action_hint":"custom:bounded_apprenticeship_care","continuation":"若后辈成年复议时仍愿参与，可按能力另订任务。","label":"协商有终止条件的分期师徒约定","requires_extension":true,"tradeoff":"医修可能降低投入，家人也需承担部分资源。"},{"action_hint":"interact:ask","continuation":"若替代方案可行，可解除救治与寻物的绑定。","label":"询问替代疗法与未来任务边界","requires_extension":false,"tradeoff":"核实会耗费时间，未必找到同等有效的办法。"},{"action_hint":"interact:decline","continuation":"只有家人或患者再次主动求助时才重开会谈。","label":"拒绝这份长约，结束议价","requires_extension":false,"tradeoff":"可能失去此人的治疗条件，仍可寻找其他援助。"}],"conflict":"医修需要回报长期投入，家人需要眼前救治，后辈未来的选择权不能由一句感恩无限抵押。","dedupe_key":"care_bargain_future_agency","exclusions":["无需治疗，或患者已清楚拒绝该方案"],"followups":[{"closure":"治疗、报偿和后续义务各自结清后结束。","development":"分别核算已付代价与新增义务，允许当事人重新选择。","trigger":"疗程阶段结束或后辈达到约定复议年龄"}],"id":"WD-FR-084","npc_motives":["医修：愿投入多年精力，希望日后得到独特能力的帮助。","监护者：担忧孩子活不过眼前难关，也怕许下无法兑现的义务。"],"preconditions":["确有持续治疗需求及可行治疗者","后辈或其监护者愿参与商谈"],"situation":"一位医修愿长期帮助受特殊体质困扰的后辈，却要求对方成年且学成后承担一次寻物任务。监护者希望立即获救，任务风险尚不清楚。","tags":["救治","监护","学徒","远期承诺"],"title":"救治之后的远期义务","variation_slots":["受困者年龄与身份","独特能力及任务距离"]},"content_version":"2026-10-31.1","id":"WD-FR-084","metadata":{"category":"师徒与控制","dedupe_key":"care_bargain_future_agency","source_card_id":"WD-FR-084","source_chapter_ids":["FR-1792"],"tags":["救治","监护","学徒","远期承诺"]},"retrieval_text":"救治之后的远期义务\n师徒与控制\n救治 监护 学徒 远期承诺\n一位医修愿长期帮助受特殊体质困扰的后辈，却要求对方成年且学成后承担一次寻物任务。监护者希望立即获救，任务风险尚不清楚。\n医修需要回报长期投入，家人需要眼前救治，后辈未来的选择权不能由一句感恩无限抵押。\n医修：愿投入多年精力，希望日后得到独特能力的帮助。\n监护者：担忧孩子活不过眼前难关，也怕许下无法兑现的义务。\n确有持续治疗需求及可行治疗者\n后辈或其监护者愿参与商谈\n无需治疗，或患者已清楚拒绝该方案\n原著长期救治与搜寻条件改成明确疗程、能力门槛和复议期限。不得替玩家或后辈默认立誓；师徒身份、治疗进度需扩展状态。"},{"card":{"adaptation_notes":"遮貌法器可换成化名、面纱或身份保密。观察仅给可见线索，不能强制揭面或读取记忆；相认和关系变化需明确互动结果。","category":"凡俗与旧情","choices":[{"action_hint":"custom:private_reunion_request","continuation":"若本人接受，可由她选择何时及透露多少。","label":"向本人提出私下传话的请求","requires_extension":true,"tradeoff":"可能被拒绝，也可能让陪同者注意到旧日关系。"},{"action_hint":"interact:ask","continuation":"若信息排除同一人，可停止追索；若相合仍需本人确认。","label":"询问引荐人公开的身份信息","requires_extension":false,"tradeoff":"只能得到公开说法，无法据此断定对方感情。"},{"action_hint":"interact:leave","continuation":"以后只有对方主动联络或新场合出现才再处理。","label":"暂不相认，结束这次关注","requires_extension":false,"tradeoff":"可能错过短暂见面机会，也保全双方当下隐私。"}],"conflict":"你想确认旧人是否安好，对方可能想保护现有身份，公开追认会让私人关系变成旁人的谈资。","dedupe_key":"unacknowledged_reunion_privacy","exclusions":["玩家从未认识此人，只有外貌相似"],"followups":[{"closure":"身份得到本人确认，或任一方明确不愿继续。","development":"核对私人记忆后再决定关系，不以沉默推定遗忘或敌意。","trigger":"本人回应传话或日后主动提起共同经历"}],"id":"WD-FR-085","npc_motives":["疑似旧识：需要减少外界纠缠，是否相认应由本人决定。","陪同长辈：重视后辈名声，未必愿公开身世细节。"],"preconditions":["玩家确有失联旧识及可信的相似线索","场合允许普通交谈但不保证私下会面"],"situation":"在公开集会上，你遇到一位与旧识同名、经历又隐约相合的人。她由强势长辈陪同，刻意遮住容貌，也没有主动与你相认。","tags":["旧识","改貌","隐私","身世"],"title":"旧识不愿当众相认","variation_slots":["旧日照顾关系","遮蔽身份的社会原因"]},"content_version":"2026-10-31.1","id":"WD-FR-085","metadata":{"category":"凡俗与旧情","dedupe_key":"unacknowledged_reunion_privacy","source_card_id":"WD-FR-085","source_chapter_ids":["FR-1804"],"tags":["旧识","改貌","隐私","身世"]},"retrieval_text":"旧识不愿当众相认\n凡俗与旧情\n旧识 改貌 隐私 身世\n在公开集会上，你遇到一位与旧识同名、经历又隐约相合的人。她由强势长辈陪同，刻意遮住容貌，也没有主动与你相认。\n你想确认旧人是否安好，对方可能想保护现有身份，公开追认会让私人关系变成旁人的谈资。\n疑似旧识：需要减少外界纠缠，是否相认应由本人决定。\n陪同长辈：重视后辈名声，未必愿公开身世细节。\n玩家确有失联旧识及可信的相似线索\n场合允许普通交谈但不保证私下会面\n玩家从未认识此人，只有外貌相似\n遮貌法器可换成化名、面纱或身份保密。观察仅给可见线索，不能强制揭面或读取记忆；相认和关系变化需明确互动结果。"},{"card":{"adaptation_notes":"提炼需求错配与同步验货，原著受困生灵不当作默认商品；可换成有争议的文书或自行同意转托的随行者。交割需专用事务支持。","category":"交易与信用","choices":[{"action_hint":"custom:atomic_three_party_barter","continuation":"若用途和权属都获确认，可执行互为条件的交换。","label":"提出三方同时验货再交割","requires_extension":true,"tradeoff":"需承担鉴定成本，任何一方不满意都可能流局。"},{"action_hint":"interact:ask","continuation":"若器具不合要求，可停止撮合而不先交出物品。","label":"询问卖家最低功能要求","requires_extension":false,"tradeoff":"可能耗尽剩余议价时间，但能避免只按名气估值。"},{"action_hint":"interact:decline","continuation":"只有展会续期或双方带来新条件时再相遇。","label":"退出撮合，保留自己的器具","requires_extension":false,"tradeoff":"可能错过稀有货物，其他两方仍可另找买家。"}],"conflict":"求购者追求救急资源，卖家拒收难变现货物，你须判断能否用自身需求补上交易缺口。","dedupe_key":"circular_barter_specific_utility","exclusions":["报价仅靠估值，没有任何实际需求匹配"],"followups":[{"closure":"三方交割完成或当场取消，未交割物各归原主。","development":"重新核对整条交换链，任一条件失效都应允许撤回。","trigger":"验货发现性能差异或交易方要求换掉某件货物"}],"id":"WD-FR-086","npc_motives":["求购者：急需指定物资，愿加价却无法凭价值说服卖家。","卖家：只认用途，不愿替别人承担转卖风险。"],"preconditions":["三方同时可接洽且至少两项需求互补","玩家拥有可自行处置的候选交换物"],"situation":"集市将散，一名求购者凑出多件贵重货物，卖家却坚持只换能立即使用的特定器具。你恰有相近器具，但尚未确认双方货物是否适用。","tags":["连环交换","期限","验货","需求错配"],"title":"三方各缺一种筹码","variation_slots":["各方急需的功能","封闭集市的散场条件"]},"content_version":"2026-10-31.1","id":"WD-FR-086","metadata":{"category":"交易与信用","dedupe_key":"circular_barter_specific_utility","source_card_id":"WD-FR-086","source_chapter_ids":["FR-1826"],"tags":["连环交换","期限","验货","需求错配"]},"retrieval_text":"三方各缺一种筹码\n交易与信用\n连环交换 期限 验货 需求错配\n集市将散，一名求购者凑出多件贵重货物，卖家却坚持只换能立即使用的特定器具。你恰有相近器具，但尚未确认双方货物是否适用。\n求购者追求救急资源，卖家拒收难变现货物，你须判断能否用自身需求补上交易缺口。\n求购者：急需指定物资，愿加价却无法凭价值说服卖家。\n卖家：只认用途，不愿替别人承担转卖风险。\n三方同时可接洽且至少两项需求互补\n玩家拥有可自行处置的候选交换物\n报价仅靠估值，没有任何实际需求匹配\n提炼需求错配与同步验货，原著受困生灵不当作默认商品；可换成有争议的文书或自行同意转托的随行者。交割需专用事务支持。"},{"card":{"adaptation_notes":"魔灾改成持续冲突，数十年改成世界中合理期限。不得默认玩家是无牵挂散修；条件承诺、保密约定与队伍席位需状态支持。","category":"突破与远行","choices":[{"action_hint":"custom:conditional_expedition_commitment","continuation":"若防卫交接完成且通道仍在，可重新确认出发。","label":"提出满足留守条件后才加入","requires_extension":true,"tradeoff":"队伍可能因此另找人，机会也可能提前消失。"},{"action_hint":"interact:ask","continuation":"若隐瞒关键风险，可要求补证或重新评估。","label":"询问路线、期限与撤回条件","requires_extension":false,"tradeoff":"只能降低信息缺口，不能把远征变成安全承诺。"},{"action_hint":"interact:decline","continuation":"仅当召集者带来重大新情报时可再次邀谈。","label":"暂不加入，结束本次邀约","requires_extension":false,"tradeoff":"放弃预留席位，不承担尚未接受的义务。"}],"conflict":"远征队希望尽早锁定稀缺专长，留守者需要稳定战力，出行收益与家园责任难在当前同时保证。","dedupe_key":"expedition_contingent_on_home_security","exclusions":["玩家正受不可移交的紧急任务约束"],"followups":[{"closure":"明确加入并转交执行事件，或远征离境而未参加。","development":"按原条件重新核对可行性，不把早先兴趣当成入队承诺。","trigger":"本地防卫转稳、留守者到位或通道期限改变"}],"id":"WD-FR-087","npc_motives":["召集者：需要具备通行专长的成员，担心队伍迟迟不能成形。","留守管事：不反对求道，但要求有人接替防卫与照料。"],"preconditions":["玩家有可被远征使用的明确专长","本地危机尚未平息且存在可讨论的接替安排"],"situation":"同道邀请你在大战趋稳后远赴敌境，寻找能改变修行前途的资源。往返可能很久，你所在聚落尚需人守护，邀请者只给出部分情报。","tags":["远征","守土责任","保密","机会窗口"],"title":"家园未稳的远征邀请","variation_slots":["远征所需专长","玩家必须照看的对象"]},"content_version":"2026-10-31.1","id":"WD-FR-087","metadata":{"category":"突破与远行","dedupe_key":"expedition_contingent_on_home_security","source_card_id":"WD-FR-087","source_chapter_ids":["FR-1842"],"tags":["远征","守土责任","保密","机会窗口"]},"retrieval_text":"家园未稳的远征邀请\n突破与远行\n远征 守土责任 保密 机会窗口\n同道邀请你在大战趋稳后远赴敌境，寻找能改变修行前途的资源。往返可能很久，你所在聚落尚需人守护，邀请者只给出部分情报。\n远征队希望尽早锁定稀缺专长，留守者需要稳定战力，出行收益与家园责任难在当前同时保证。\n召集者：需要具备通行专长的成员，担心队伍迟迟不能成形。\n留守管事：不反对求道，但要求有人接替防卫与照料。\n玩家有可被远征使用的明确专长\n本地危机尚未平息且存在可讨论的接替安排\n玩家正受不可移交的紧急任务约束\n魔灾改成持续冲突，数十年改成世界中合理期限。不得默认玩家是无牵挂散修；条件承诺、保密约定与队伍席位需状态支持。"},{"card":{"adaptation_notes":"虫王机制可改成器胚熔炼或种群筛选，成功率只能来自证据而非原著固定数值。保密条款须允许明确核验对象，不能锁死所有求助途径。","category":"机缘与代价","choices":[{"action_hint":"custom:reserve_seed_stock_trial","continuation":"若小批试验显示可控，再决定是否继续扩大。","label":"保留种源，只交付可承受的一部分","requires_extension":true,"tradeoff":"交换所得减少，专家可能不愿提供完整方法。"},{"action_hint":"interact:ask","continuation":"若允许独立核验，可寻找第三方确认风险。","label":"询问失败记录与保密边界","requires_extension":false,"tradeoff":"可能得不到核心机理，也需检验对方是否挑报结果。"},{"action_hint":"interact:decline","continuation":"后来出现低耗方法时可另行评估。","label":"拒绝试验，维持现有种群","requires_extension":false,"tradeoff":"暂不获得高阶成果，仍保留当前稳定用途。"}],"conflict":"专家需要成熟个体扩大尝试，你想得到进阶机会，却可能失去稳定种源及向他人请教的自由。","dedupe_key":"irreversible_cultivation_seed_reserve","exclusions":["材料不可再生且承担当前唯一生存保障"],"followups":[{"closure":"试验验收、资料结清或明确止损即结束。","development":"核算可用个体、失败原因与剩余义务，再决定是否停止。","trigger":"第一批培育结束或种群低于预定保留线"}],"id":"WD-FR-088","npc_motives":["专家：重视长期试验积累，愿给资料但禁止无条件外传。","照料者：希望保住可繁衍群体，担心一场尝试毁掉多年投入。"],"preconditions":["玩家确实拥有稳定培养的非人格化生物或器物群","存在已被展示的试验方法与有限成功证据"],"situation":"一位培育专家提出用你长期养成的种群换取稀有资源及进阶秘法。秘法需要大量同类消耗，成功并不确定，传授还附保密限制。","tags":["培育","不可逆投入","秘术","保留种源"],"title":"培养奇物要耗尽种群吗","variation_slots":["被消耗的培养对象","成功证据与资源补偿"]},"content_version":"2026-10-31.1","id":"WD-FR-088","metadata":{"category":"机缘与代价","dedupe_key":"irreversible_cultivation_seed_reserve","source_card_id":"WD-FR-088","source_chapter_ids":["FR-1873"],"tags":["培育","不可逆投入","秘术","保留种源"]},"retrieval_text":"培养奇物要耗尽种群吗\n机缘与代价\n培育 不可逆投入 秘术 保留种源\n一位培育专家提出用你长期养成的种群换取稀有资源及进阶秘法。秘法需要大量同类消耗，成功并不确定，传授还附保密限制。\n专家需要成熟个体扩大尝试，你想得到进阶机会，却可能失去稳定种源及向他人请教的自由。\n专家：重视长期试验积累，愿给资料但禁止无条件外传。\n照料者：希望保住可繁衍群体，担心一场尝试毁掉多年投入。\n玩家确实拥有稳定培养的非人格化生物或器物群\n存在已被展示的试验方法与有限成功证据\n材料不可再生且承担当前唯一生存保障\n虫王机制可改成器胚熔炼或种群筛选，成功率只能来自证据而非原著固定数值。保密条款须允许明确核验对象，不能锁死所有求助途径。"},{"card":{"adaptation_notes":"两座强城改成有差异的安全据点。旧交必须有权限和信用记录，不能一句保证免除风险；集体意见、迁徙和附庸义务需独立状态。","category":"势力博弈","choices":[{"action_hint":"custom:negotiate_refuge_terms","continuation":"若承诺可验证，可由族人决定是否前往。","label":"要求旧交落实安置与征用条款","requires_extension":true,"tradeoff":"可能需提供相应服务，也会把迁徙信息告知对方。"},{"action_hint":"interact:ask","continuation":"若发现征用或歧视记录，可调整选择与携带物资。","label":"先询问两城已迁入者的待遇","requires_extension":false,"tradeoff":"核实消耗撤离时间，见闻可能带有立场偏差。"},{"action_hint":"interact:decline","continuation":"若后来出现独立安全落脚点，此线就此结束。","label":"退出此次集体投靠，另行安置","requires_extension":false,"tradeoff":"需自行承担住宿与护送成本，不再享有团体名额。"}],"conflict":"族人想要最强防线，领队担心附庸被优先消耗，安全既取决于守城能力也取决于实际待遇。","dedupe_key":"refuge_strength_versus_patronage","exclusions":["危险迫在眼前，只剩一条可行逃生路"],"followups":[{"closure":"安置稳定且义务明确，或选择其他长期居所。","development":"检查承诺是否兑现，允许投诉、重谈或在可行时迁出。","trigger":"入城后首次分配住处或征召守卫时"}],"id":"WD-FR-089","npc_motives":["迁徙领队：要保存人口与传承，愿用旧交争取明确位置。","避难者代表：害怕关系承诺落空，希望知道为何舍强取弱。"],"preconditions":["聚落已有撤离必要与可用运力","两处目的地均已知且确有不同收容条件"],"situation":"战事逼近，聚落准备迁离。较强的城池承诺收容，却未说明征用规则；另一座防线稍弱的城中有可信旧交，愿为安置条件出面。","tags":["避难","依附","庇护","征用风险"],"title":"强城与熟门之间","variation_slots":["避难团体规模","可信旧交的实际权限"]},"content_version":"2026-10-31.1","id":"WD-FR-089","metadata":{"category":"势力博弈","dedupe_key":"refuge_strength_versus_patronage","source_card_id":"WD-FR-089","source_chapter_ids":["FR-1879"],"tags":["避难","依附","庇护","征用风险"]},"retrieval_text":"强城与熟门之间\n势力博弈\n避难 依附 庇护 征用风险\n战事逼近，聚落准备迁离。较强的城池承诺收容，却未说明征用规则；另一座防线稍弱的城中有可信旧交，愿为安置条件出面。\n族人想要最强防线，领队担心附庸被优先消耗，安全既取决于守城能力也取决于实际待遇。\n迁徙领队：要保存人口与传承，愿用旧交争取明确位置。\n避难者代表：害怕关系承诺落空，希望知道为何舍强取弱。\n聚落已有撤离必要与可用运力\n两处目的地均已知且确有不同收容条件\n危险迫在眼前，只剩一条可行逃生路\n两座强城改成有差异的安全据点。旧交必须有权限和信用记录，不能一句保证免除风险；集体意见、迁徙和附庸义务需独立状态。"},{"card":{"adaptation_notes":"封印能量改成维持禁制的资源，抽取影响必须可观测。停止接触含封存操作故标扩展；保留拒绝机会，不用囚徒叙述自动证明其无害。","category":"探索与禁制","choices":[{"action_hint":"custom:contained_seal_extraction_test","continuation":"若封印变化超出约定，可中止并封回试验区。","label":"设计少量抽取并隔离验证","requires_extension":true,"tradeoff":"会耗费防护材料，错误估计仍可能削弱禁制。"},{"action_hint":"interact:ask","continuation":"若能与外部遗留记载对照，可逐步缩小疑点。","label":"追问囚徒为何被封与脱困条件","requires_extension":false,"tradeoff":"回答可能真假混杂，无法仅靠其陈述判安全。"},{"action_hint":"custom:seal_contact_suspend","continuation":"以后取得可靠解释再决定是否重开。","label":"停止接触并封存器具","requires_extension":true,"tradeoff":"暂时得不到资源，也保留原有封印责任。"}],"conflict":"你想利用资源又不想放出未知威胁，囚徒需要削弱禁制才能脱身，因此关键资料都带有利益倾向。","dedupe_key":"seal_resource_prisoner_release_conflict","exclusions":["封印正在崩毁，已无余裕进行交易"],"followups":[{"closure":"器具被安全移交、永久封存或有限交易结清。","development":"对照先前记录重估共同利益，必要时转入保管或撤离事件。","trigger":"发现禁制损耗、原主人线索或囚徒说法矛盾"}],"id":"WD-FR-090","npc_motives":["囚徒：愿交出技术换自由，不会主动强调全部危险。","保管同伴：担忧原主人追索，希望先确认封印用途。"],"preconditions":["封印目前稳定且允许安全的有限交流","玩家已持有器具并发现可抽取资源"],"situation":"你在封存器具中发现一名仍能交谈的囚徒。他知道如何提取其中珍贵能量，同时承认这会削弱监牢；器具原主人可能仍在寻找它。","tags":["封印","囚徒交易","共同利益","核验"],"title":"取走封印燃料也会放出囚徒","variation_slots":["封印供能材料","囚徒可提供的专业知识"]},"content_version":"2026-10-31.1","id":"WD-FR-090","metadata":{"category":"探索与禁制","dedupe_key":"seal_resource_prisoner_release_conflict","source_card_id":"WD-FR-090","source_chapter_ids":["FR-1913"],"tags":["封印","囚徒交易","共同利益","核验"]},"retrieval_text":"取走封印燃料也会放出囚徒\n探索与禁制\n封印 囚徒交易 共同利益 核验\n你在封存器具中发现一名仍能交谈的囚徒。他知道如何提取其中珍贵能量，同时承认这会削弱监牢；器具原主人可能仍在寻找它。\n你想利用资源又不想放出未知威胁，囚徒需要削弱禁制才能脱身，因此关键资料都带有利益倾向。\n囚徒：愿交出技术换自由，不会主动强调全部危险。\n保管同伴：担忧原主人追索，希望先确认封印用途。\n封印目前稳定且允许安全的有限交流\n玩家已持有器具并发现可抽取资源\n封印正在崩毁，已无余裕进行交易\n封印能量改成维持禁制的资源，抽取影响必须可观测。停止接触含封存操作故标扩展；保留拒绝机会，不用囚徒叙述自动证明其无害。"},{"card":{"adaptation_notes":"将高阶化身追杀改成可恢复的追逐压力。退敌只是短暂窗口；信息留存必须有事前依据，不在废城凭空生成救援目标或奖励。","category":"追逐与藏身","choices":[{"action_hint":"custom:reconnoiter_old_rendezvous","continuation":"若标记显示撤离，可循已有备用方案行动；不明则继续谨慎。","label":"从远处核对既定接应标记","requires_extension":true,"tradeoff":"绕行会耗费恢复时间，观察点也可能被敌方监视。"},{"action_hint":"interact:observe","continuation":"若看到占领迹象，可放弃原接头点并记录威胁。","label":"只观察追兵退去方向与城防变化","requires_extension":false,"tradeoff":"能得的信息有限，不能由安静推断据点无人。"},{"action_hint":"evade:withdraw","continuation":"待伤势或情报改善后，玩家可自愿重新联络。","label":"撤离到已知安全区，放弃此次接应","requires_extension":false,"tradeoff":"旧信息可能失效，失联者需依自己的预案行动。"}],"conflict":"接应者需要知道你是否生还，你需要保存脱身所得的余裕，确认旧城情况与隐藏行踪难以兼顾。","dedupe_key":"lost_base_after_pursuit_break","exclusions":["玩家仍被直接包围，或旧据点已确认安全"],"followups":[{"closure":"确认人员去向、启用新接头点或主动终止旧约。","development":"重新核对彼此位置，避免自动把旧据点继续视为安全。","trigger":"备用联络日到来或出现原接应者的可信消息"}],"id":"WD-FR-091","npc_motives":["接应人：可能仍按旧约等候，也可能已经自行撤离。","追兵统领：需要修整与调度，短暂退却并不表示放弃搜捕。"],"preconditions":["近期追逐暂歇且玩家尚能自主移动","存在已约定的旧据点或联络标记"],"situation":"强敌刚刚退去，你仍有恢复余力的机会。旧据点可能已被占领，那里留有约定的接应信息；贸然返回或追击都可能重新进入敌方控制区。","tags":["战后撤离","旧据点","追兵","有限情报"],"title":"追兵退后，旧城已失","variation_slots":["旧据点类型","可从远处核对的标记"]},"content_version":"2026-10-31.1","id":"WD-FR-091","metadata":{"category":"追逐与藏身","dedupe_key":"lost_base_after_pursuit_break","source_card_id":"WD-FR-091","source_chapter_ids":["FR-1940"],"tags":["战后撤离","旧据点","追兵","有限情报"]},"retrieval_text":"追兵退后，旧城已失\n追逐与藏身\n战后撤离 旧据点 追兵 有限情报\n强敌刚刚退去，你仍有恢复余力的机会。旧据点可能已被占领，那里留有约定的接应信息；贸然返回或追击都可能重新进入敌方控制区。\n接应者需要知道你是否生还，你需要保存脱身所得的余裕，确认旧城情况与隐藏行踪难以兼顾。\n接应人：可能仍按旧约等候，也可能已经自行撤离。\n追兵统领：需要修整与调度，短暂退却并不表示放弃搜捕。\n近期追逐暂歇且玩家尚能自主移动\n存在已约定的旧据点或联络标记\n玩家仍被直接包围，或旧据点已确认安全\n将高阶化身追杀改成可恢复的追逐压力。退敌只是短暂窗口；信息留存必须有事前依据，不在废城凭空生成救援目标或奖励。"},{"card":{"adaptation_notes":"原著婚配胁迫可替换成结盟、入门或资源契约；核心是退出权被封锁。门禁、护送及公开见证需专门状态，询问不能自动解除禁制。","category":"宗门与派系","choices":[{"action_hint":"custom:invoke_neutral_venue_exit","continuation":"若当事人选择离开，可协商解除门禁及中立护送。","label":"要求馆方公开确认受邀者可自行离席","requires_extension":true,"tradeoff":"会使压力公开化，馆方可能拖延或偏袒强者。"},{"action_hint":"interact:ask","continuation":"若明确请求援助，再据此选择见证或脱困方案。","label":"向当事人询问真实意愿与求助范围","requires_extension":false,"tradeoff":"联系本身可能受监视，不能假定对方愿由你代谈。"},{"action_hint":"evade:withdraw","continuation":"在安全处遇到合法申诉渠道时，可自行决定是否作证。","label":"撤出危险楼层，不参与当场对峙","requires_extension":false,"tradeoff":"受邀者仍可能受压；你可保留已知事实。"}],"conflict":"受邀者想自由离席，施压者借人脉逼其表态，馆方既要维护信用又害怕得罪强势客人。","dedupe_key":"neutral_venue_coercive_confinement","exclusions":["只是正常闭门会谈，尚无拒绝离席证据"],"followups":[{"closure":"恢复自由离席并处理信用争议，或玩家明确退出。","development":"由本人确认是否自愿，不以施压方的口头和解替代。","trigger":"会馆宣称事情解决或受邀者再次出现"}],"id":"WD-FR-092","npc_motives":["受邀者：拒绝被他人代作承诺，希望有人见证自己的意愿。","会馆管事：担心招牌毁损，也不愿直接承受强者报复。"],"preconditions":["玩家有可信证据表明受邀者不能自由离开","现场存在可接洽的馆方或中立见证者"],"situation":"一名熟识修士被请进中立会馆谈事，却传出门户封闭、多人逼其接受依附的消息。主持者声称只是劝说，馆方规矩却未被执行。","tags":["会馆规矩","胁迫","庇护","见证"],"title":"中立会馆里的关门劝说","variation_slots":["被逼接受的关系","会馆真正能约束的权势范围"]},"content_version":"2026-10-31.1","id":"WD-FR-092","metadata":{"category":"宗门与派系","dedupe_key":"neutral_venue_coercive_confinement","source_card_id":"WD-FR-092","source_chapter_ids":["FR-1981"],"tags":["会馆规矩","胁迫","庇护","见证"]},"retrieval_text":"中立会馆里的关门劝说\n宗门与派系\n会馆规矩 胁迫 庇护 见证\n一名熟识修士被请进中立会馆谈事，却传出门户封闭、多人逼其接受依附的消息。主持者声称只是劝说，馆方规矩却未被执行。\n受邀者想自由离席，施压者借人脉逼其表态，馆方既要维护信用又害怕得罪强势客人。\n受邀者：拒绝被他人代作承诺，希望有人见证自己的意愿。\n会馆管事：担心招牌毁损，也不愿直接承受强者报复。\n玩家有可信证据表明受邀者不能自由离开\n现场存在可接洽的馆方或中立见证者\n只是正常闭门会谈，尚无拒绝离席证据\n原著婚配胁迫可替换成结盟、入门或资源契约；核心是退出权被封锁。门禁、护送及公开见证需专门状态，询问不能自动解除禁制。"},{"card":{"adaptation_notes":"将两界战争改成会改变通行难度的势力调动。推演不能等同事实，原著两日仅作可替换期限；多队确认和行程承诺须扩展支持。","category":"突破与远行","choices":[{"action_hint":"custom:reschedule_multigroup_expedition","continuation":"若各方都能完成最低准备，可重新锁定行程。","label":"提出先联络同行队，再确认共同时间","requires_extension":true,"tradeoff":"可能消耗窗口，却能避免单方面改变盟约。"},{"action_hint":"interact:ask","continuation":"若事实与推演分清，可判断哪些准备绝不能省略。","label":"追问敌方调动的来源与最坏情形","requires_extension":false,"tradeoff":"召集者可能无法给出更多证据，决策仍需承受不确定。"},{"action_hint":"interact:decline","continuation":"若计划取消或另有窗口，可再收到独立邀约。","label":"拒绝提前出发，放弃本轮席位","requires_extension":false,"tradeoff":"队伍可能照常离开，原时间也不保证保留。"}],"conflict":"抢窗口可能降低路途风险，却压缩准备与协调时间；等待消息又可能让原来的全部计划失去可行性。","dedupe_key":"opportunity_window_schedule_shock","exclusions":["没有新情报，只是召集者无故催促"],"followups":[{"closure":"新行程获共同确认，或原远征彻底取消。","development":"更新出发条件，允许因情报变化撤销未履行的承诺。","trigger":"敌方调动获证实或同行队回信"}],"id":"WD-FR-093","npc_motives":["召集者：怕战局一变两头落空，希望尽快得到明确人数。","外部同行队：承担同样风险，却尚未参与提前决策。"],"preconditions":["玩家已有待确认的远征邀约","出现足以改变窗口的可信但不完备情报"],"situation":"原定等战事平稳再执行的远征，因敌方主力将调动而被要求提前。召集者给出一套合理推演，但尚未与另一支同行队确认新时程。","tags":["时机变化","情报核验","提前出发","战局"],"title":"远征窗口突然提前","variation_slots":["敌方调动原因","必须完成的最低准备"]},"content_version":"2026-10-31.1","id":"WD-FR-093","metadata":{"category":"突破与远行","dedupe_key":"opportunity_window_schedule_shock","source_card_id":"WD-FR-093","source_chapter_ids":["FR-2011"],"tags":["时机变化","情报核验","提前出发","战局"]},"retrieval_text":"远征窗口突然提前\n突破与远行\n时机变化 情报核验 提前出发 战局\n原定等战事平稳再执行的远征，因敌方主力将调动而被要求提前。召集者给出一套合理推演，但尚未与另一支同行队确认新时程。\n抢窗口可能降低路途风险，却压缩准备与协调时间；等待消息又可能让原来的全部计划失去可行性。\n召集者：怕战局一变两头落空，希望尽快得到明确人数。\n外部同行队：承担同样风险，却尚未参与提前决策。\n玩家已有待确认的远征邀约\n出现足以改变窗口的可信但不完备情报\n没有新情报，只是召集者无故催促\n将两界战争改成会改变通行难度的势力调动。推演不能等同事实，原著两日仅作可替换期限；多队确认和行程承诺须扩展支持。"},{"card":{"adaptation_notes":"伪装凭据改成世界已支持的伪装条件，救援与暴露分别结算。原著紧急许诺不转化为无限役使，不能以一句求救自动绑定忠诚。","category":"身份与秘密","choices":[{"action_hint":"custom:disguised_limited_rescue","continuation":"若受困者成功脱身，可再由他们自愿履行引路约定。","label":"尝试开出撤离通道，只约定有限回报","requires_extension":true,"tradeoff":"消耗隐藏手段与体力，身份伪装可能受损。"},{"action_hint":"interact:observe","continuation":"若有安全缺口，可提出非正面救援方案。","label":"先观察包围缺口与撤退方向","requires_extension":false,"tradeoff":"等待可能使局面恶化，也不能保证发现可行路线。"},{"action_hint":"evade:withdraw","continuation":"只有以后确实再遇见生还者时才回收此事。","label":"撤离兽群边缘，放弃接触","requires_extension":false,"tradeoff":"失去本次线索机会，受困者将依靠自身或其他援助。"}],"conflict":"受困者急于活命，你需要当地线索与隐蔽身份，救援越充分越可能留下可追查的个人特征。","dedupe_key":"rescue_under_hostile_cover","exclusions":["玩家无力影响局面且没有安全联络办法"],"followups":[{"closure":"有限回报履行、双方解除约定或未能建立联系。","development":"核对回报是否越过原约，处理身份线索而非强制收人为仆。","trigger":"获救者开始报恩或有人追问救援者特征"}],"id":"WD-FR-094","npc_motives":["受困向导：愿偿还明确帮助，不了解救援者真实来历。","同行潜入者：希望维持伪装，担心为陌生人打乱路线。"],"preconditions":["玩家已有可用伪装与一定救援能力","危险来自明确可观察的兽群或灾害"],"situation":"你在敌境以当地身份行走，遇到两名被兽群困住的地方人士。他们愿以引路与消息报答救援，但动手会暴露能力，真身份也可能留下痕迹。","tags":["潜行身份","救援","偿还","当地向导"],"title":"披着敌方身份救人","variation_slots":["伪装所依赖的特征","受困者可提供的本地知识"]},"content_version":"2026-10-31.1","id":"WD-FR-094","metadata":{"category":"身份与秘密","dedupe_key":"rescue_under_hostile_cover","source_card_id":"WD-FR-094","source_chapter_ids":["FR-2028"],"tags":["潜行身份","救援","偿还","当地向导"]},"retrieval_text":"披着敌方身份救人\n身份与秘密\n潜行身份 救援 偿还 当地向导\n你在敌境以当地身份行走，遇到两名被兽群困住的地方人士。他们愿以引路与消息报答救援，但动手会暴露能力，真身份也可能留下痕迹。\n受困者急于活命，你需要当地线索与隐蔽身份，救援越充分越可能留下可追查的个人特征。\n受困向导：愿偿还明确帮助，不了解救援者真实来历。\n同行潜入者：希望维持伪装，担心为陌生人打乱路线。\n玩家已有可用伪装与一定救援能力\n危险来自明确可观察的兽群或灾害\n玩家无力影响局面且没有安全联络办法\n伪装凭据改成世界已支持的伪装条件，救援与暴露分别结算。原著紧急许诺不转化为无限役使，不能以一句求救自动绑定忠诚。"},{"card":{"adaptation_notes":"原著施术获取记忆只记在来源中，游戏使用同意与证词边界。移动界面可换季节道路；不能询问一次便自动定位、确认亲属或获得通行能力。","category":"凡俗与旧情","choices":[{"action_hint":"custom:consensual_missing_person_evidence","continuation":"若线索能与航图或传送记录相合，可另开寻路任务。","label":"征得同意后只记录可公开的路径线索","requires_extension":true,"tradeoff":"能获得的信息有限，安置对方也需投入资源。"},{"action_hint":"interact:ask","continuation":"若能排除部分地区，仍须等待独立证据确认。","label":"询问她愿公开的故乡环境与出行经过","requires_extension":false,"tradeoff":"对方可拒答，叙述也可能因见识有限而不精确。"},{"action_hint":"interact:leave","continuation":"对方以后主动补充消息时，才重新核对。","label":"结束追问，暂缓寻找这条线索","requires_extension":false,"tradeoff":"可能错过短期窗口，但不剥夺对方接受普通援助的资格。"}],"conflict":"你想尽快寻找故人，知情者要保护家人和隐私，强求完整供述也无法凭空补上她不知道的路线。","dedupe_key":"castaway_testimony_missing_person_lead","exclusions":["已有确切相反证据，或仅有泛泛外貌相似"],"followups":[{"closure":"确认故人所在、排除线索或玩家主动停止调查。","development":"区分证实部分与个人猜测，入口不明时保留未解决状态。","trigger":"出现独立地图、入口活动记录或故人特征证据"}],"id":"WD-FR-095","npc_motives":["漂流者：希望安全安置，不愿救助变成交出家人信息的代价。","寻路人：重视任何线索，但容易把相似技艺误当成身份确证。"],"preconditions":["玩家确有失联对象和可核对的独特关联","知情者能交谈且没有被强制搜查"],"situation":"一名流落异境的人掌握与你失联故人相关的技艺，却不愿透露亲人细节。她记得故乡生活，未必知道返乡入口，相关线索仍是推测。","tags":["失联","证词边界","移动入口","知情者"],"title":"漂流者带来的故人线索","variation_slots":["可辨认的传承特征","故乡与外界连接方式"]},"content_version":"2026-10-31.1","id":"WD-FR-095","metadata":{"category":"凡俗与旧情","dedupe_key":"castaway_testimony_missing_person_lead","source_card_id":"WD-FR-095","source_chapter_ids":["FR-2055"],"tags":["失联","证词边界","移动入口","知情者"]},"retrieval_text":"漂流者带来的故人线索\n凡俗与旧情\n失联 证词边界 移动入口 知情者\n一名流落异境的人掌握与你失联故人相关的技艺，却不愿透露亲人细节。她记得故乡生活，未必知道返乡入口，相关线索仍是推测。\n你想尽快寻找故人，知情者要保护家人和隐私，强求完整供述也无法凭空补上她不知道的路线。\n漂流者：希望安全安置，不愿救助变成交出家人信息的代价。\n寻路人：重视任何线索，但容易把相似技艺误当成身份确证。\n玩家确有失联对象和可核对的独特关联\n知情者能交谈且没有被强制搜查\n已有确切相反证据，或仅有泛泛外貌相似\n原著施术获取记忆只记在来源中，游戏使用同意与证词边界。移动界面可换季节道路；不能询问一次便自动定位、确认亲属或获得通行能力。"},{"card":{"adaptation_notes":"特殊坐骑改成耐险交通工具或当地驾驶资格，禁止凭加价必然成交。运输服务、路线权限和担保都是新状态，现有旅行只负责去已知地点。","category":"势力博弈","choices":[{"action_hint":"custom:bounded_transport_service","continuation":"若双方确认终点、返程与货物边界，可能达成有限通行。","label":"改谈雇用向导与往返运输服务","requires_extension":true,"tradeoff":"需接受随队监督和行程限制，不能永久获得运力。"},{"action_hint":"interact:ask","continuation":"若能够证明只过境，可提出更贴合顾虑的担保。","label":"询问对方真正担心的竞争方式","requires_extension":false,"tradeoff":"可能暴露你对当地资源的兴趣，未必换来信任。"},{"action_hint":"interact:decline","continuation":"以后发现其他通道或获得公开运输资格再来。","label":"放弃本次路线，退出议价","requires_extension":false,"tradeoff":"需重新规划行程，已花的准备时间难以收回。"}],"conflict":"远行者只想借路，家族却要保住长期生计；一次高价交易无法补偿将垄断能力永久交出的风险。","dedupe_key":"mobility_monopoly_service_conversion","exclusions":["玩家已有等效交通能力，或路障并不限制通行"],"followups":[{"closure":"约定运输完成、双方解除合同或行程取消。","development":"重新确认服务边界，不能把雇用默认为坐骑所有权转移。","trigger":"运力提供者要求增加货物限制或归还保证"}],"id":"WD-FR-096","npc_motives":["家族管事：担心坐骑繁育与路线外流，愿考虑可控制的服务。","队伍召集者：希望早日启程，不愿无限加价或卷入本地争斗。"],"preconditions":["目的地和荒地障碍已经明确","本地确有专门运力并以此经营"],"situation":"队伍需穿越一片普通行旅无法通过的荒地，本地家族独占适用坐骑。对方并非嫌报价太低，而是担心出售运力会培养新的采运竞争者。","tags":["运力垄断","资源控制","服务交换","远行"],"title":"不能出售的通行坐骑","variation_slots":["被垄断的交通手段","本地赖以生存的产业"]},"content_version":"2026-10-31.1","id":"WD-FR-096","metadata":{"category":"势力博弈","dedupe_key":"mobility_monopoly_service_conversion","source_card_id":"WD-FR-096","source_chapter_ids":["FR-2072"],"tags":["运力垄断","资源控制","服务交换","远行"]},"retrieval_text":"不能出售的通行坐骑\n势力博弈\n运力垄断 资源控制 服务交换 远行\n队伍需穿越一片普通行旅无法通过的荒地，本地家族独占适用坐骑。对方并非嫌报价太低，而是担心出售运力会培养新的采运竞争者。\n远行者只想借路，家族却要保住长期生计；一次高价交易无法补偿将垄断能力永久交出的风险。\n家族管事：担心坐骑繁育与路线外流，愿考虑可控制的服务。\n队伍召集者：希望早日启程，不愿无限加价或卷入本地争斗。\n目的地和荒地障碍已经明确\n本地确有专门运力并以此经营\n玩家已有等效交通能力，或路障并不限制通行\n特殊坐骑改成耐险交通工具或当地驾驶资格，禁止凭加价必然成交。运输服务、路线权限和担保都是新状态，现有旅行只负责去已知地点。"},{"card":{"adaptation_notes":"分魂显现改为授权信物或远程谈判，专属资源改成守关者确需的筹码。第三方承诺需记录覆盖对象，不凭私约自动保护整队。","category":"同盟与背叛","choices":[{"action_hint":"custom:negotiate_collective_exit_scope","continuation":"若同意扩大保障，可继续合作；若拒绝则各方须重估关系。","label":"要求先明确所有人的离场条件","requires_extension":true,"tradeoff":"可能令对方嫌条件过多，甚至失去短暂谈判窗口。"},{"action_hint":"interact:ask","continuation":"若明确不包括你，可据此准备独立方案而不误信。","label":"询问盟友私约究竟覆盖谁","requires_extension":false,"tradeoff":"对方可能避答，短暂停火也不保证持续。"},{"action_hint":"evade:withdraw","continuation":"生还后可按已知事实清算合作，毋须再次入险。","label":"趁尚有通路撤离，放弃共同争取机缘","requires_extension":false,"tradeoff":"可能失去队伍支援与既定收益，但避免继续押注私约。"}],"conflict":"赞助者只想救回自己的投入，其他队员要求共同风险得到共同保障，私下议价可能拆散现有防线。","dedupe_key":"private_patron_clause_excludes_allies","exclusions":["队伍事前已明确各自独立议价并获共同认可"],"followups":[{"closure":"共同离开、独立撤离或该次合作被明确终止。","development":"核对谁得到保障、谁承担新增风险，不能把沉默当作全员同意。","trigger":"守关者要求拆队或赞助方开始兑现条件"}],"id":"WD-FR-097","npc_motives":["受保盟友：想抓住生机，但担心被其余队员视为背弃。","守关者：只看交换利益，也可能借谈判寻找分割队伍的机会。"],"preconditions":["玩家属于临时联合队伍且面临同一威胁","盟友确有此前未披露的独立担保或筹码"],"situation":"联合队伍被守关者拦住，一名盟友突然启用赞助者留下的议价凭证。新条件只提到他所属一方，你与其余成员是否被包括在内尚无人说明。","tags":["隐秘赞助","排除条款","共同风险","谈判"],"title":"同盟背后另有一份私约","variation_slots":["赞助者可交换的利益","队伍事前约定范围"]},"content_version":"2026-10-31.1","id":"WD-FR-097","metadata":{"category":"同盟与背叛","dedupe_key":"private_patron_clause_excludes_allies","source_card_id":"WD-FR-097","source_chapter_ids":["FR-2096"],"tags":["隐秘赞助","排除条款","共同风险","谈判"]},"retrieval_text":"同盟背后另有一份私约\n同盟与背叛\n隐秘赞助 排除条款 共同风险 谈判\n联合队伍被守关者拦住，一名盟友突然启用赞助者留下的议价凭证。新条件只提到他所属一方，你与其余成员是否被包括在内尚无人说明。\n赞助者只想救回自己的投入，其他队员要求共同风险得到共同保障，私下议价可能拆散现有防线。\n受保盟友：想抓住生机，但担心被其余队员视为背弃。\n守关者：只看交换利益，也可能借谈判寻找分割队伍的机会。\n玩家属于临时联合队伍且面临同一威胁\n盟友确有此前未披露的独立担保或筹码\n队伍事前已明确各自独立议价并获共同认可\n分魂显现改为授权信物或远程谈判，专属资源改成守关者确需的筹码。第三方承诺需记录覆盖对象，不凭私约自动保护整队。"},{"card":{"adaptation_notes":"高阶傀儡改成有自主目标的特殊同伴，能源周期按世界设定。维护、战斗报酬与离队权限分别存储，不能把供能直接写成收服。","category":"交易与信用","choices":[{"action_hint":"custom:independent_companion_service_contract","continuation":"若稳定履约，对方可按范围同行；目标达成则办理离队。","label":"商定维护、出手与结束期限的分项约定","requires_extension":true,"tradeoff":"须长期留出资源，危急时也未必能免费调用。"},{"action_hint":"interact:ask","continuation":"若维护上限清楚，可据此缩小所需服务。","label":"询问损耗、转换速度与拒绝出手条件","requires_extension":false,"tradeoff":"可能发现对方远不适合当前路线，也会延后出发。"},{"action_hint":"interact:decline","continuation":"以后有短期、明确报酬的需求时可重新协商。","label":"拒绝长期同行，仅结束本次商谈","requires_extension":false,"tradeoff":"失去持续援助，仍可按双方原有关系往来。"}],"conflict":"你希望稳定获得帮助，对方却把同行视为实现自身目标的阶段安排，供养不能自动换取终身服从。","dedupe_key":"maintenance_service_independent_departure","exclusions":["对方只是普通无意志器具，或供给根本无法持续"],"followups":[{"closure":"所有已发生费用结清且同行关系结束。","development":"按不同条款处理暂停、加价或离队，不混成忠诚下降。","trigger":"资源短缺、额外出手请求或返乡储备达到约定条件"}],"id":"WD-FR-098","npc_motives":["随行者：需要能源与返乡储备，希望额外风险另算报酬。","物资管理者：担心常规消耗挤占队伍预算，反对随意调用。"],"preconditions":["玩家有可持续供应的真实资源来源","对方具有自主意愿且维护需求已被说明"],"situation":"一位强大却缺少维持能源的独立随行者愿暂伴你远行。它需要逐步积蓄返乡所需资源，平日维护与危险行动并非同一笔报酬。","tags":["雇佣","维护费用","独立目标","期限"],"title":"随行者要的是续航与自由","variation_slots":["随行者的维护资源","其独立返乡目标"]},"content_version":"2026-10-31.1","id":"WD-FR-098","metadata":{"category":"交易与信用","dedupe_key":"maintenance_service_independent_departure","source_card_id":"WD-FR-098","source_chapter_ids":["FR-2115"],"tags":["雇佣","维护费用","独立目标","期限"]},"retrieval_text":"随行者要的是续航与自由\n交易与信用\n雇佣 维护费用 独立目标 期限\n一位强大却缺少维持能源的独立随行者愿暂伴你远行。它需要逐步积蓄返乡所需资源，平日维护与危险行动并非同一笔报酬。\n你希望稳定获得帮助，对方却把同行视为实现自身目标的阶段安排，供养不能自动换取终身服从。\n随行者：需要能源与返乡储备，希望额外风险另算报酬。\n物资管理者：担心常规消耗挤占队伍预算，反对随意调用。\n玩家有可持续供应的真实资源来源\n对方具有自主意愿且维护需求已被说明\n对方只是普通无意志器具，或供给根本无法持续\n高阶傀儡改成有自主目标的特殊同伴，能源周期按世界设定。维护、战斗报酬与离队权限分别存储，不能把供能直接写成收服。"},{"card":{"adaptation_notes":"备用化身可换成高危替班或强制役使，功法后门要有明确可核验证据。不得一句废功即可无代价脱困，也不预设必须救出才算完成。","category":"师徒与控制","choices":[{"action_hint":"custom:dependency_exit_transition","continuation":"若能先建立替代技艺与庇护，再由本人决定是否脱离。","label":"协助制定分阶段摆脱依赖的方案","requires_extension":true,"tradeoff":"转修与生活过渡耗费资源，仍可能被师门察觉。"},{"action_hint":"interact:ask","continuation":"若目标明确，可只提供信息、过渡资源或谈判帮助。","label":"询问本人最想保留什么及可承担何种代价","requires_extension":false,"tradeoff":"她可能选择暂留，援助者不能替她定义成功。"},{"action_hint":"interact:decline","continuation":"日后她提出范围更小的援助请求时再独立决定。","label":"拒绝介入脱离行动，结束这次商谈","requires_extension":false,"tradeoff":"当事人仍需自己权衡，不应因拒绝而被新增威胁。"}],"conflict":"授业者用供养换取备用人手，弟子想保留修行成果又获得自主，简单离门无法抹去技术依赖。","dedupe_key":"patronage_embedded_replacement_clause","exclusions":["仅凭传闻怀疑师门，尚无控制证据"],"followups":[{"closure":"控制解除且独立生活成立，或本人停止这次求助。","development":"以本人意愿更新方案，资源来源变化不等于控制已解除。","trigger":"备用条款将被启用、替代修法可用或授业者提出新条件"}],"id":"WD-FR-099","npc_motives":["受制弟子：珍惜已有成就，也担心自己成为随时可替换的消耗品。","授业者：认为投入换取服役合理，不愿承认弟子单方脱离。"],"preconditions":["师承确有已验证的控制机制或契约条款","当事人主动求助且尚有商谈或筹备时间"],"situation":"同门向你透露，丰厚资源附带一项不易被启用的替身义务，所修功法也让授业者能干预法力。离开可以保命，却可能失去多年修为与生计。","tags":["传承依赖","控制后门","资源保障","脱离代价"],"title":"丰厚传承里的替身条款","variation_slots":["控制依赖的技术类型","退出后缺少的生存资源"]},"content_version":"2026-10-31.1","id":"WD-FR-099","metadata":{"category":"师徒与控制","dedupe_key":"patronage_embedded_replacement_clause","source_card_id":"WD-FR-099","source_chapter_ids":["FR-2128"],"tags":["传承依赖","控制后门","资源保障","脱离代价"]},"retrieval_text":"丰厚传承里的替身条款\n师徒与控制\n传承依赖 控制后门 资源保障 脱离代价\n同门向你透露，丰厚资源附带一项不易被启用的替身义务，所修功法也让授业者能干预法力。离开可以保命，却可能失去多年修为与生计。\n授业者用供养换取备用人手，弟子想保留修行成果又获得自主，简单离门无法抹去技术依赖。\n受制弟子：珍惜已有成就，也担心自己成为随时可替换的消耗品。\n授业者：认为投入换取服役合理，不愿承认弟子单方脱离。\n师承确有已验证的控制机制或契约条款\n当事人主动求助且尚有商谈或筹备时间\n仅凭传闻怀疑师门，尚无控制证据\n备用化身可换成高危替班或强制役使，功法后门要有明确可核验证据。不得一句废功即可无代价脱困，也不预设必须救出才算完成。"},{"card":{"adaptation_notes":"压抑情绪设定改成带心境代价的技艺，不把冷淡直接判成失去人格。修法变更与关系恢复分开，评估结果不能保证重拾原先感情。","category":"生存求道","choices":[{"action_hint":"custom:voluntary_mind_method_review","continuation":"若发现可调整的部分，可在本人同意后小范围试行。","label":"提议由本人决定是否做可逆的修法评估","requires_extension":true,"tradeoff":"可能影响近期进境，也需要可信的中立专家。"},{"action_hint":"interact:ask","continuation":"若需求只是减少干涉，可协商新的相处边界。","label":"先问她真正困扰的是什么","requires_extension":false,"tradeoff":"她可能没有改变意愿，旧关系也未必恢复。"},{"action_hint":"interact:leave","continuation":"只有本人再次求助或出现明确新问题才重开。","label":"停止劝改，结束本次谈话","requires_extension":false,"tradeoff":"保留眼下的疏离感，但不继续以关心施加压力。"}],"conflict":"长辈想挽回过去判断，旧友看重修行成果与自主，关心她的人可能把恢复旧关系误当成唯一正确结局。","dedupe_key":"emotional_cultivation_autonomy_review","exclusions":["缺乏相关修法证据，只因对方不再亲近而猜测异常"],"followups":[{"closure":"本人确认当前方案并结束求助，或完成自愿调整。","development":"比较她自述与可验证表现，避免替她规定应有的情绪。","trigger":"本人提出修法困扰或约定评估期到来"}],"id":"WD-FR-100","npc_motives":["修法者：认为自己从中受益，不愿被视为失去判断力。","长辈：担忧副作用，却夹杂对旧选择的内疚和新的期待。"],"preconditions":["已有能影响心境的明确修法及可观察变化","本人能清楚表达选择且关系尚可交谈"],"situation":"旧友借一门压抑情绪的法诀越过困境，如今对往日关系显得疏淡。她的长辈因新局势而后悔推荐此法，你却不知本人是否真想改变。","tags":["心境","功法副作用","长辈期待","自主选择"],"title":"压住情感是否仍是自己的路","variation_slots":["情绪变化的表现","长辈与旧友的关系"]},"content_version":"2026-10-31.1","id":"WD-FR-100","metadata":{"category":"生存求道","dedupe_key":"emotional_cultivation_autonomy_review","source_card_id":"WD-FR-100","source_chapter_ids":["FR-2152"],"tags":["心境","功法副作用","长辈期待","自主选择"]},"retrieval_text":"压住情感是否仍是自己的路\n生存求道\n心境 功法副作用 长辈期待 自主选择\n旧友借一门压抑情绪的法诀越过困境，如今对往日关系显得疏淡。她的长辈因新局势而后悔推荐此法，你却不知本人是否真想改变。\n长辈想挽回过去判断，旧友看重修行成果与自主，关心她的人可能把恢复旧关系误当成唯一正确结局。\n修法者：认为自己从中受益，不愿被视为失去判断力。\n长辈：担忧副作用，却夹杂对旧选择的内疚和新的期待。\n已有能影响心境的明确修法及可观察变化\n本人能清楚表达选择且关系尚可交谈\n缺乏相关修法证据，只因对方不再亲近而猜测异常\n压抑情绪设定改成带心境代价的技艺，不把冷淡直接判成失去人格。修法变更与关系恢复分开，评估结果不能保证重拾原先感情。"},{"card":{"adaptation_notes":"圣树改成阵心、水源或传承核心；重建资源须预先存在。大规模撤退、通报回执和毁阵单独记录，不能因主事者下令直接判全员死亡。","category":"宗门与派系","choices":[{"action_hint":"custom:allied_evacuation_before_scuttle","continuation":"若各阵位完成确认，可按共同期限回收人员与设备。","label":"先协商分批通报与撤离确认，再废弃防线","requires_extension":true,"tradeoff":"会暴露撤军意图，也可能给敌方反应时间。"},{"action_hint":"interact:ask","continuation":"若发现失联阵位，可单独评估援助而不默认全军已撤。","label":"询问哪些阵位仍有人以及通讯是否畅通","requires_extension":false,"tradeoff":"无法代替实际救援，主事者也可能隐瞒数字。"},{"action_hint":"evade:withdraw","continuation":"安全后可按真实经过处理盟约责任。","label":"带自己的人员撤离，不再承担毁阵任务","requires_extension":false,"tradeoff":"可能失去部分公用物资，也不再控制全局方案。"}],"conflict":"本方要避免恐慌并保全种子，盟友有权及时脱险；保密拖得越久，撤军越可能变成被动牺牲。","dedupe_key":"collapse_scuttle_allied_notice","exclusions":["只是未经核实的败亡传闻，或防线已即时崩塌"],"followups":[{"closure":"人员去向得到交代，防线责任移交或撤离完成。","development":"重算可救范围并明确选择，不能以时间到自动抹掉失联者。","trigger":"到达弃守期限、出现未回执阵位或撤退受阻"}],"id":"WD-FR-101","npc_motives":["临时主事者：想保存人员与重建资源，害怕公开败局引发溃散。","外援领队：愿履行约定，却拒绝在不知情下替已弃防线陪葬。"],"preconditions":["核心失守消息已获可信确认","存在可通知的分散盟军与明确弃守方案"],"situation":"联军前线尚能支撑，后方赖以立足的核心设施却已毁坏。主事者想封锁消息争取撤离时间，并准备废弃防线，但外援仍分散在各处阵位。","tags":["败局善后","盟军撤离","族群延续","消息封锁"],"title":"根基已毁，盟军尚在阵中","variation_slots":["族群赖以生存的核心设施","撤离确认的通讯方式"]},"content_version":"2026-10-31.1","id":"WD-FR-101","metadata":{"category":"宗门与派系","dedupe_key":"collapse_scuttle_allied_notice","source_card_id":"WD-FR-101","source_chapter_ids":["FR-2175"],"tags":["败局善后","盟军撤离","族群延续","消息封锁"]},"retrieval_text":"根基已毁，盟军尚在阵中\n宗门与派系\n败局善后 盟军撤离 族群延续 消息封锁\n联军前线尚能支撑，后方赖以立足的核心设施却已毁坏。主事者想封锁消息争取撤离时间，并准备废弃防线，但外援仍分散在各处阵位。\n本方要避免恐慌并保全种子，盟友有权及时脱险；保密拖得越久，撤军越可能变成被动牺牲。\n临时主事者：想保存人员与重建资源，害怕公开败局引发溃散。\n外援领队：愿履行约定，却拒绝在不知情下替已弃防线陪葬。\n核心失守消息已获可信确认\n存在可通知的分散盟军与明确弃守方案\n只是未经核实的败亡传闻，或防线已即时崩塌\n圣树改成阵心、水源或传承核心；重建资源须预先存在。大规模撤退、通报回执和毁阵单独记录，不能因主事者下令直接判全员死亡。"},{"card":{"adaptation_notes":"不复制原著斩杀幻象的固定破局法；识破可通过矛盾与锚点。幻境不能偷改真实亲人经历，退出能力必须在触发前建立。","category":"生存求道","choices":[{"action_hint":"interact:observe","continuation":"若矛盾得到确认，可辨认诱惑所在而寻找出口。","label":"沿既有记忆核对一个关键矛盾","requires_extension":false,"tradeoff":"会打破安稳感，也可能暂时加重幻境干扰。"},{"action_hint":"custom:activate_reality_anchor","continuation":"若锚点有效，可恢复清醒并记录这次心境弱处。","label":"主动唤起事先留下的现实锚点","requires_extension":true,"tradeoff":"可能终止部分试炼收益，并暴露锚点给施术者。"},{"action_hint":"evade:withdraw","continuation":"在自愿且准备更充分时，才考虑再次尝试。","label":"按预先方法退出试炼","requires_extension":false,"tradeoff":"放弃本轮可能的领悟，仍保留对愿望的记忆。"}],"conflict":"幻境用真实愿望换取持续认同，你既想理解未竟心愿，又不能把舒适感当作现实已经被改写。","dedupe_key":"ideal_life_illusion_identity_anchor","exclusions":["普通梦境或真实团聚，没有已知幻术依据"],"followups":[{"closure":"玩家确认现实并不再接受幻境互动。","development":"区分幻象满足的愿望与现实人物的意愿，允许只留下反思。","trigger":"醒来后再次遇见相关现实人物或准备下一次试炼"}],"id":"WD-FR-102","npc_motives":["幻境中的亲近者：按试炼规则回应愿望，未必具有现实身份。","外部护法：只知你尚未醒来，无法替你判断内心经历。"],"preconditions":["玩家已自愿进入有明确退出办法的心境试炼","至少有一项此前建立的现实记忆锚点"],"situation":"试炼让你置身一段安稳的人生：亲人仍在、旧伤未生，身边人期待你自然留下。只有几个名字和记忆细节彼此矛盾，退出方式尚未消失。","tags":["幻境","记忆锚点","凡俗愿望","退出试炼"],"title":"过于圆满的另一种人生","variation_slots":["被满足的凡俗愿望","已建立的现实锚点"]},"content_version":"2026-10-31.1","id":"WD-FR-102","metadata":{"category":"生存求道","dedupe_key":"ideal_life_illusion_identity_anchor","source_card_id":"WD-FR-102","source_chapter_ids":["FR-2188"],"tags":["幻境","记忆锚点","凡俗愿望","退出试炼"]},"retrieval_text":"过于圆满的另一种人生\n生存求道\n幻境 记忆锚点 凡俗愿望 退出试炼\n试炼让你置身一段安稳的人生：亲人仍在、旧伤未生，身边人期待你自然留下。只有几个名字和记忆细节彼此矛盾，退出方式尚未消失。\n幻境用真实愿望换取持续认同，你既想理解未竟心愿，又不能把舒适感当作现实已经被改写。\n幻境中的亲近者：按试炼规则回应愿望，未必具有现实身份。\n外部护法：只知你尚未醒来，无法替你判断内心经历。\n玩家已自愿进入有明确退出办法的心境试炼\n至少有一项此前建立的现实记忆锚点\n普通梦境或真实团聚，没有已知幻术依据\n不复制原著斩杀幻象的固定破局法；识破可通过矛盾与锚点。幻境不能偷改真实亲人经历，退出能力必须在触发前建立。"},{"card":{"adaptation_notes":"特殊灵根改成稀缺专业能力，强提境界改成已证实的透支机制。不可直接继承原著角色的权势解法；必须记录本人同意和支出上限。","category":"势力博弈","choices":[{"action_hint":"custom:conscription_informed_limits","continuation":"若后辈自主接受可承受方案，再以书面范围参加。","label":"要求知情同意并提出限制消耗的替代方案","requires_extension":true,"tradeoff":"可能增加公共支出，机构也可能拒绝降低目标。"},{"action_hint":"interact:ask","continuation":"若承诺只覆盖短期生存，可据此揭示未获同意的部分。","label":"追问提升手段、长期后患及替代人选","requires_extension":false,"tradeoff":"会使谈判紧张，仍需独立证据验证说明。"},{"action_hint":"interact:decline","continuation":"若公共危机另有办法解决，此事无需再重提。","label":"拒绝本次征召，结束议价","requires_extension":false,"tradeoff":"可能失去机构奖励与部分关系便利，但不默认遭报复。"}],"conflict":"机构追求迫切的集体安全，后辈需要完整了解终身代价，资源奖励无法直接补回被消耗的未来。","dedupe_key":"collective_need_hidden_lifetime_cost","exclusions":["对方只凭传闻锁定人选，或任务不依赖该天赋"],"followups":[{"closure":"任务按约完成、征召撤回或当事人明确拒绝。","development":"让被征者重新确认，不将先前有限同意延伸为无限奉献。","trigger":"机构带来改良方案或要求扩大原定投入"}],"id":"WD-FR-103","npc_motives":["使者：确有公共危机压力，也希望尽快完成征召。","被征者：可能愿尽力，但不愿把未说明的后患当成既定义务。"],"preconditions":["后辈具有已确认且与任务直接相关的天赋","任务确有代价并允许讨论执行条件"],"situation":"权威机构发现一名后辈具备稀缺天赋，要求征用以支持族群防卫，并保证事后补偿。任务却需先透支成长潜力，对方只承诺当场不会致命。","tags":["征召","寿元代价","稀缺天赋","集体利益"],"title":"以大局为名的天赋征召","variation_slots":["后辈的独特天赋","无法用普通物资补偿的代价"]},"content_version":"2026-10-31.1","id":"WD-FR-103","metadata":{"category":"势力博弈","dedupe_key":"collective_need_hidden_lifetime_cost","source_card_id":"WD-FR-103","source_chapter_ids":["FR-2199"],"tags":["征召","寿元代价","稀缺天赋","集体利益"]},"retrieval_text":"以大局为名的天赋征召\n势力博弈\n征召 寿元代价 稀缺天赋 集体利益\n权威机构发现一名后辈具备稀缺天赋，要求征用以支持族群防卫，并保证事后补偿。任务却需先透支成长潜力，对方只承诺当场不会致命。\n机构追求迫切的集体安全，后辈需要完整了解终身代价，资源奖励无法直接补回被消耗的未来。\n使者：确有公共危机压力，也希望尽快完成征召。\n被征者：可能愿尽力，但不愿把未说明的后患当成既定义务。\n后辈具有已确认且与任务直接相关的天赋\n任务确有代价并允许讨论执行条件\n对方只凭传闻锁定人选，或任务不依赖该天赋\n特殊灵根改成稀缺专业能力，强提境界改成已证实的透支机制。不可直接继承原著角色的权势解法；必须记录本人同意和支出上限。"},{"card":{"adaptation_notes":"虫母与上古封印改成可调查的灾害和控制设施。不能凭专家身份自动认定两目标互斥，探查风险、职责与撤退条件均须实际支持。","category":"同盟与背叛","choices":[{"action_hint":"custom:disaster_rescue_priority_protocol","continuation":"若关键限制得到确认，可在知情下分配救人与封印资源。","label":"提出有限复核，再划定两组职责与停止条件","requires_extension":true,"tradeoff":"复核会消耗时间，分组也可能让每方力量不足。"},{"action_hint":"interact:ask","continuation":"若分歧源于假设，可先调整计划而非直接质疑动机。","label":"要求专家区分亲见事实与推测","requires_extension":false,"tradeoff":"可能暴露情报空白，但未必能获得第二次探查机会。"},{"action_hint":"interact:decline","continuation":"可以在安全区域自行选择普通后援工作。","label":"拒绝参与此次深入行动","requires_extension":false,"tradeoff":"无法亲自保护被困者，也不承担未接受的队伍职责。"}],"conflict":"亲属与盟友急于救人，守土者要压住持续扩散的灾害；有限窗口里，两类目标可能争用相同力量。","dedupe_key":"disaster_rescue_containment_priority","exclusions":["专家声称绝对正确却没有任何可核验材料"],"followups":[{"closure":"队伍撤回、目标阶段完成或玩家正式退出职责。","development":"重新比较原假设，必要时缩减目标或撤回队伍。","trigger":"封印波动进入窗口或获得新的被困者消息"}],"id":"WD-FR-104","npc_motives":["首席专家：希望团队采用自己的路线，但无法提供每个细节的独立证明。","救援代表：担心亲友被当成可牺牲代价，要求说明不能兼顾的原因。"],"preconditions":["灾源、被困者及行动窗口均有基本证据","玩家参加的是行动前商议，尚可拒绝任务"],"situation":"跨势力救援会将开始，唯一探查过灾区的专家称必须在救人和重新封印之间分配主力。她有证据与经验，也与部分被困者存在旧日利益冲突。","tags":["灾变合作","专家信用","行动窗口","目标分歧"],"title":"救人还是先封住灾源","variation_slots":["灾源的控制方式","专家与被困者的利益关系"]},"content_version":"2026-10-31.1","id":"WD-FR-104","metadata":{"category":"同盟与背叛","dedupe_key":"disaster_rescue_containment_priority","source_card_id":"WD-FR-104","source_chapter_ids":["FR-2220"],"tags":["灾变合作","专家信用","行动窗口","目标分歧"]},"retrieval_text":"救人还是先封住灾源\n同盟与背叛\n灾变合作 专家信用 行动窗口 目标分歧\n跨势力救援会将开始，唯一探查过灾区的专家称必须在救人和重新封印之间分配主力。她有证据与经验，也与部分被困者存在旧日利益冲突。\n亲属与盟友急于救人，守土者要压住持续扩散的灾害；有限窗口里，两类目标可能争用相同力量。\n首席专家：希望团队采用自己的路线，但无法提供每个细节的独立证明。\n救援代表：担心亲友被当成可牺牲代价，要求说明不能兼顾的原因。\n灾源、被困者及行动窗口均有基本证据\n玩家参加的是行动前商议，尚可拒绝任务\n专家声称绝对正确却没有任何可核验材料\n虫母与上古封印改成可调查的灾害和控制设施。不能凭专家身份自动认定两目标互斥，探查风险、职责与撤退条件均须实际支持。"},{"card":{"adaptation_notes":"神识强化技艺的专属层数与年限改成该世界已存在的修行记录和风险证据。不可突然补设必死倒计时；缓解、续篇和专家恩情须分别记录。","category":"机缘与代价","choices":[{"action_hint":"custom:staged_remedial_knowledge_exchange","continuation":"若机理获证实，可限定交换范围而不一次许诺全部。","label":"先核验一个可逆改良，再分阶段交换帮助","requires_extension":true,"tradeoff":"试验耗时且有失败风险，专家可能不接受先示范。"},{"action_hint":"interact:ask","continuation":"若说法能与修炼记录吻合，可继续寻找独立来源。","label":"询问后患证据、时间依据与他不知道的部分","requires_extension":false,"tradeoff":"可能发现对方也不懂完整办法，不能立即解除压力。"},{"action_hint":"interact:decline","continuation":"若找到其他研究线索，本次专家交易可永久搁置。","label":"拒绝这份交换，结束接触并另寻资料","requires_extension":false,"tradeoff":"原有修法问题仍须处理，但拒绝不会新增惩罚。"}],"conflict":"你需要可靠的后续知识，专家需要你罕见的能力；他既可能救急，也有利用信息不对称扩大依赖的动机。","dedupe_key":"incomplete_method_continuation_dependency","exclusions":["玩家从未接触此法，或只有陌生人的无证恐吓"],"followups":[{"closure":"问题获独立处理、交易结清或双方终止合作。","development":"据实际证据更新缓解期限与代价，防止无尽追加义务。","trigger":"出现可验证的新症兆、续篇或专家提出追加条件"}],"id":"WD-FR-105","npc_motives":["受困专家：知道部分机理，想以知识换取自身脱困条件。","旧法研究者：愿核验问题，但未必掌握完整续篇。"],"preconditions":["玩家确已修炼相关技艺且残缺有可核对迹象","后患有准备窗口，并非即时必死"],"situation":"一名受困专家指出，你一直当作完整传承的秘法只是前半部，旧日增益可能带来延迟后患。他能提供缓解思路，但希望你先替他处理一件专门难题。","tags":["残卷","续修压力","期限","知识交换"],"title":"残缺秘法带来的长期依赖","variation_slots":["长期反噬的具体机制","专家需要的专业协助"]},"content_version":"2026-10-31.1","id":"WD-FR-105","metadata":{"category":"机缘与代价","dedupe_key":"incomplete_method_continuation_dependency","source_card_id":"WD-FR-105","source_chapter_ids":["FR-2249"],"tags":["残卷","续修压力","期限","知识交换"]},"retrieval_text":"残缺秘法带来的长期依赖\n机缘与代价\n残卷 续修压力 期限 知识交换\n一名受困专家指出，你一直当作完整传承的秘法只是前半部，旧日增益可能带来延迟后患。他能提供缓解思路，但希望你先替他处理一件专门难题。\n你需要可靠的后续知识，专家需要你罕见的能力；他既可能救急，也有利用信息不对称扩大依赖的动机。\n受困专家：知道部分机理，想以知识换取自身脱困条件。\n旧法研究者：愿核验问题，但未必掌握完整续篇。\n玩家确已修炼相关技艺且残缺有可核对迹象\n后患有准备窗口，并非即时必死\n玩家从未接触此法，或只有陌生人的无证恐吓\n神识强化技艺的专属层数与年限改成该世界已存在的修行记录和风险证据。不可突然补设必死倒计时；缓解、续篇和专家恩情须分别记录。"},{"card":{"adaptation_notes":"去魔气等设定改成迁居、职业或修行路线转换成本。旧友最终留下是来源事实，游戏可改变；不能因援助足够就自动改变其目标。","category":"凡俗与旧情","choices":[{"action_hint":"custom:autonomous_friend_support","continuation":"若她自主接受，可支持近期所需而保留各自生活。","label":"尊重留下决定，商量有限而无附加关系的支持","requires_extension":true,"tradeoff":"资源可能无法收回，未来也不能保证常常相见。"},{"action_hint":"interact:ask","continuation":"若顾虑能解决，可共同重估；不能则明确相处边界。","label":"询问她的长期目标与改变道路的具体代价","requires_extension":false,"tradeoff":"谈话可能确认双方方向不同，无法消除分别的不舍。"},{"action_hint":"interact:leave","continuation":"以后双方自愿联系时，再讨论彼此的新处境。","label":"结束劝返，按自己的计划离开会面","requires_extension":false,"tradeoff":"暂时分别，关系不因此自动破裂或变淡。"}],"conflict":"你希望团聚并提供庇护，她希望以自己的方式追求长远目标，安全相伴未必等同于对她最合适的生活。","dedupe_key":"reunion_respects_independent_path","exclusions":["当事人仍被胁迫，所谓留下只是对方代答"],"followups":[{"closure":"本次团聚与去留安排明确，后续仅按真实联络开启。","development":"依据她现在的选择回应，不拿过去援助要求随行或归属。","trigger":"旧友完成一个修行阶段或主动请求新的帮助"}],"id":"WD-FR-106","npc_motives":["旧友：珍惜重逢，却不愿把全部前途交给他人保障。","故乡引路人：愿提供落脚处，也需要知道对方是否真心回归。"],"preconditions":["旧有控制已实际解除","返回与留下都是可行方案，代价已有基本说明"],"situation":"长期受制的旧友终于获得自由，你有能力陪她返回故乡。她却认为异乡的修行环境更合自身道路，改变体质回归可能损失多年积累。","tags":["独立道路","团聚","体质选择","长期目标"],"title":"获救之后仍想留在异乡","variation_slots":["异乡的独特优势","改变生活道路的实际损失"]},"content_version":"2026-10-31.1","id":"WD-FR-106","metadata":{"category":"凡俗与旧情","dedupe_key":"reunion_respects_independent_path","source_card_id":"WD-FR-106","source_chapter_ids":["FR-2252"],"tags":["独立道路","团聚","体质选择","长期目标"]},"retrieval_text":"获救之后仍想留在异乡\n凡俗与旧情\n独立道路 团聚 体质选择 长期目标\n长期受制的旧友终于获得自由，你有能力陪她返回故乡。她却认为异乡的修行环境更合自身道路，改变体质回归可能损失多年积累。\n你希望团聚并提供庇护，她希望以自己的方式追求长远目标，安全相伴未必等同于对她最合适的生活。\n旧友：珍惜重逢，却不愿把全部前途交给他人保障。\n故乡引路人：愿提供落脚处，也需要知道对方是否真心回归。\n旧有控制已实际解除\n返回与留下都是可行方案，代价已有基本说明\n当事人仍被胁迫，所谓留下只是对方代答\n去魔气等设定改成迁居、职业或修行路线转换成本。旧友最终留下是来源事实，游戏可改变；不能因援助足够就自动改变其目标。"},{"card":{"adaptation_notes":"血誓仅作来源，不默认迁入族群成为可交易资产。工具权属、知情同意、自治和安置成本需扩展；拒绝永久依附不等于必须拒绝一切救助。","category":"宗门与派系","choices":[{"action_hint":"custom:bounded_refugee_autonomy_compact","continuation":"若成员知情同意，可按家庭登记安置并设置复议期。","label":"将效忠改成有期限的安置与互助契约","requires_extension":true,"tradeoff":"要承担更明确的供养责任，不能永久索取族群服务。"},{"action_hint":"interact:ask","continuation":"若有人选择留下，应另行核对可行性与个人财物。","label":"询问族内各方对去留与报偿的意见","requires_extension":false,"tradeoff":"意见可能分歧，集中迁移的效率会下降。"},{"action_hint":"interact:decline","continuation":"若以后只需运输等有限协助，可另谈新约。","label":"拒绝担任长期庇护者，退出这份约定","requires_extension":false,"tradeoff":"族群需寻找其他安置方，你也失去工具交换条件。"}],"conflict":"族长用最大承诺争取安全，救援者需要承担安置成本；一代人的危急选择不应自动替所有后代决定生活。","dedupe_key":"inherited_subordination_renegotiation","exclusions":["迁移工具不足以救人，或族群内部尚无人愿意离开"],"followups":[{"closure":"迁移和安置义务结清，或双方依法解除合作。","development":"按既定权利处理劳务与退出，不把出生视为自动承担效忠。","trigger":"抵达安置地、有人要求迁出或首个约期届满"}],"id":"WD-FR-107","npc_motives":["族长：担心承诺不够重便失去离境机会，希望族群延续。","年轻族人代表：愿承担迁移费用，却想保留未来迁居与择业权。"],"preconditions":["族群确有离开困地的需求和可用迁移手段","玩家有接纳或协调安置的现实能力"],"situation":"一支受困小族愿拿出关键迁移工具换取离境帮助，族长还主动提出世代效忠。运输可以实现，长期安置、自治与后辈义务却尚未谈清。","tags":["族群迁移","庇护条件","集体承诺","自治"],"title":"安置族群不等于承接永世效忠","variation_slots":["族群专长","安置地可承受的人口规模"]},"content_version":"2026-10-31.1","id":"WD-FR-107","metadata":{"category":"宗门与派系","dedupe_key":"inherited_subordination_renegotiation","source_card_id":"WD-FR-107","source_chapter_ids":["FR-2305"],"tags":["族群迁移","庇护条件","集体承诺","自治"]},"retrieval_text":"安置族群不等于承接永世效忠\n宗门与派系\n族群迁移 庇护条件 集体承诺 自治\n一支受困小族愿拿出关键迁移工具换取离境帮助，族长还主动提出世代效忠。运输可以实现，长期安置、自治与后辈义务却尚未谈清。\n族长用最大承诺争取安全，救援者需要承担安置成本；一代人的危急选择不应自动替所有后代决定生活。\n族长：担心承诺不够重便失去离境机会，希望族群延续。\n年轻族人代表：愿承担迁移费用，却想保留未来迁居与择业权。\n族群确有离开困地的需求和可用迁移手段\n玩家有接纳或协调安置的现实能力\n迁移工具不足以救人，或族群内部尚无人愿意离开\n血誓仅作来源，不默认迁入族群成为可交易资产。工具权属、知情同意、自治和安置成本需扩展；拒绝永久依附不等于必须拒绝一切救助。"},{"card":{"adaptation_notes":"古灯效果改成系统允许的意识载体，不默认复制完整人格。分离、养护、回收和控制权均需扩展；观察动作只揭示外观，不完成安全鉴定。","category":"探索与禁制","choices":[{"action_hint":"custom:isolated_consciousness_vessel_trial","continuation":"若养护和回收均有效，再决定是否扩大投入。","label":"先以可放弃的微弱片段做隔离测试","requires_extension":true,"tradeoff":"消耗恢复精力与防护资源，测试不能证明所有后患。"},{"action_hint":"interact:observe","continuation":"若发现原主权限仍在，可先寻找解除方法。","label":"观察已有铭文、残迹与能量流向","requires_extension":false,"tradeoff":"只得到外部线索，不能直接证明没有控制后门。"},{"action_hint":"custom:defer_consciousness_vessel_use","continuation":"日后有更完整说明或研究能力时再开启。","label":"拒绝投入意识，暂时封存研究","requires_extension":true,"tradeoff":"暂得不到新助手，也避免追加难以撤回的投入。"}],"conflict":"你想增加可独立行动的助手，器物却可能成为控制核心；一旦投入重要意识，失窃与残留机制都会放大代价。","dedupe_key":"soul_vessel_control_audit","exclusions":["没有意识承载设定，或器物来源与能力皆凭空出现"],"followups":[{"closure":"器物用途确认且试验结束，或被安全移交封存。","development":"核验片段是否可安全回收，发现疑点则停止扩大。","trigger":"出现异常回声、控制权变化或试验到达回收阶段"}],"id":"WD-FR-108","npc_motives":["器物研究者：希望弄懂运行方式，但不愿替未知长期效果作保。","保管同伴：担心所有控制权集中在易被夺走的一件物品上。"],"preconditions":["玩家已合法取得器物且具备基础辨识能力","世界已有分魂或意识承载机制"],"situation":"你从有明确来历的战利品中找到一件可保存意识片段的器物，或能弥补现有助手不足。但它的控制关系、长久养护和原主残留都尚未查清。","tags":["旧物核验","分身","控制媒介","长期试验"],"title":"能养分魂的旧灯","variation_slots":["被承载的意识形式","控制媒介的保管方式"]},"content_version":"2026-10-31.1","id":"WD-FR-108","metadata":{"category":"探索与禁制","dedupe_key":"soul_vessel_control_audit","source_card_id":"WD-FR-108","source_chapter_ids":["FR-2307"],"tags":["旧物核验","分身","控制媒介","长期试验"]},"retrieval_text":"能养分魂的旧灯\n探索与禁制\n旧物核验 分身 控制媒介 长期试验\n你从有明确来历的战利品中找到一件可保存意识片段的器物，或能弥补现有助手不足。但它的控制关系、长久养护和原主残留都尚未查清。\n你想增加可独立行动的助手，器物却可能成为控制核心；一旦投入重要意识，失窃与残留机制都会放大代价。\n器物研究者：希望弄懂运行方式，但不愿替未知长期效果作保。\n保管同伴：担心所有控制权集中在易被夺走的一件物品上。\n玩家已合法取得器物且具备基础辨识能力\n世界已有分魂或意识承载机制\n没有意识承载设定，或器物来源与能力皆凭空出现\n古灯效果改成系统允许的意识载体，不默认复制完整人格。分离、养护、回收和控制权均需扩展；观察动作只揭示外观，不完成安全鉴定。"},{"card":{"adaptation_notes":"渡劫改成任何需要闭锁保护的过程；源剧情的守候不强迫玩家照做。外侧守护、结束信号和访问授权分别记录，不把旧恩直接兑换权限。","category":"同盟与背叛","choices":[{"action_hint":"custom:perimeter_guard_with_access_boundary","continuation":"若信号按时出现，可再正式会面；若异常则另问是否求助。","label":"提出在外侧临时守候并约定结束信号","requires_extension":true,"tradeoff":"需要继续承担外部风险，暂时得不到回报与休整。"},{"action_hint":"interact:ask","continuation":"若建立可信信号，可减少误会而维持封闭。","label":"询问安危及无需开门的联络办法","requires_extension":false,"tradeoff":"只能获取对方愿意透露的信息，不能确认内部全部情形。"},{"action_hint":"evade:withdraw","continuation":"日后普通会面时再谈感谢或偿还。","label":"撤离谷口，结束自己的护援","requires_extension":false,"tradeoff":"对方需自行接替外部守护，已提供的帮助仍可被记住。"}],"conflict":"你想确认故人安危并安置随行者，守门者必须保护最脆弱时刻；救援之恩不能立刻替代进入禁地的授权。","dedupe_key":"rescue_does_not_override_access_boundary","exclusions":["对方已明确邀请入内，或禁地正需立即救命进入"],"followups":[{"closure":"当事人安全出关、护援交接或玩家明确撤离。","development":"由内部主动开启后续会面，未获许可不得把感谢当成通行令。","trigger":"闭关结束信号传出或约定等待期届满"}],"id":"WD-FR-109","npc_motives":["守门弟子：感谢援助，却怕错放人导致护法失败。","闭关者：希望有人挡敌，同时需要维持原定安全边界。"],"preconditions":["玩家确实提供过可被确认的外部援助","禁制内有人处于不能分心的修行阶段"],"situation":"你刚替旧识赶走外敌，对方正在重要修炼阶段，守门弟子只肯隔阵传话。你的帮助已被承认，但入口仍闭合，双方都带着消耗与戒心。","tags":["护法","信任边界","救援回报","危机中会面"],"title":"救过你，也不要求立刻开门","variation_slots":["无法分心的活动","外侧能提供的有限协助"]},"content_version":"2026-10-31.1","id":"WD-FR-109","metadata":{"category":"同盟与背叛","dedupe_key":"rescue_does_not_override_access_boundary","source_card_id":"WD-FR-109","source_chapter_ids":["FR-2325"],"tags":["护法","信任边界","救援回报","危机中会面"]},"retrieval_text":"救过你，也不要求立刻开门\n同盟与背叛\n护法 信任边界 救援回报 危机中会面\n你刚替旧识赶走外敌，对方正在重要修炼阶段，守门弟子只肯隔阵传话。你的帮助已被承认，但入口仍闭合，双方都带着消耗与戒心。\n你想确认故人安危并安置随行者，守门者必须保护最脆弱时刻；救援之恩不能立刻替代进入禁地的授权。\n守门弟子：感谢援助，却怕错放人导致护法失败。\n闭关者：希望有人挡敌，同时需要维持原定安全边界。\n玩家确实提供过可被确认的外部援助\n禁制内有人处于不能分心的修行阶段\n对方已明确邀请入内，或禁地正需立即救命进入\n渡劫改成任何需要闭锁保护的过程；源剧情的守候不强迫玩家照做。外侧守护、结束信号和访问授权分别记录，不把旧恩直接兑换权限。"},{"card":{"adaptation_notes":"所拍卖的稀有宝材改成已在交易中的资产，报酬高来自商誉损失。不得凭接单自动获知嫌疑人所在；悬赏条件、证据与承诺需专门记录。","category":"交易与信用","choices":[{"action_hint":"custom:bounded_bounty_evidence_contract","continuation":"若证据可交叉核对，可按阶段结算，不自动负责追杀。","label":"只接受范围明确的线索核验委托","requires_extension":true,"tradeoff":"报酬可能低于抓捕全赏，仍需花费调查资源。"},{"action_hint":"interact:ask","continuation":"若标准含糊，可要求书面说明后再决定。","label":"询问嫌疑依据、通行凭证与赏格验收标准","requires_extension":false,"tradeoff":"商会未必愿公布内部漏洞，可能无法消除误判。"},{"action_hint":"interact:decline","continuation":"以后偶然取得真实证据时可选择是否提供。","label":"拒绝悬赏，继续原定行程","requires_extension":false,"tradeoff":"放弃潜在厚酬，也避免拖延已有目标。"}],"conflict":"商会要证明规则有效，求赏者想获得收益；追查耗时与误指无辜的风险不能因赏格惊人而消失。","dedupe_key":"reputation_bounty_exceeds_asset_value","exclusions":["只有传闻赏格，发布者无力兑现承诺"],"followups":[{"closure":"证据结算、悬赏撤销或案件公开了结。","development":"核对证据来源与承诺时间，避免多人争功变成自动敌对。","trigger":"有人交来同一嫌疑人的证据或商会更改赏格"}],"id":"WD-FR-110","npc_motives":["商会主事：愿付超出失物价值的代价，以维护今后交易秩序。","查案管事：急需线索，也担忧假证据与趁机勒索。"],"preconditions":["公开事件、失物与悬赏权限均已确认","玩家可能掌握独特线索或愿承担调查成本"],"situation":"大型商会在公开交易中遭人夺物，愿把追回之物本身交给协助者，只求捉到责任人并恢复信用。悬赏极厚，但现有线索不足且可能与内应有关。","tags":["悬赏","商誉","证据","机会成本"],"title":"赔出失物也要追回信誉","variation_slots":["商会真正受损的信用","可核验的内应或逃离线索"]},"content_version":"2026-10-31.1","id":"WD-FR-110","metadata":{"category":"交易与信用","dedupe_key":"reputation_bounty_exceeds_asset_value","source_card_id":"WD-FR-110","source_chapter_ids":["FR-2338"],"tags":["悬赏","商誉","证据","机会成本"]},"retrieval_text":"赔出失物也要追回信誉\n交易与信用\n悬赏 商誉 证据 机会成本\n大型商会在公开交易中遭人夺物，愿把追回之物本身交给协助者，只求捉到责任人并恢复信用。悬赏极厚，但现有线索不足且可能与内应有关。\n商会要证明规则有效，求赏者想获得收益；追查耗时与误指无辜的风险不能因赏格惊人而消失。\n商会主事：愿付超出失物价值的代价，以维护今后交易秩序。\n查案管事：急需线索，也担忧假证据与趁机勒索。\n公开事件、失物与悬赏权限均已确认\n玩家可能掌握独特线索或愿承担调查成本\n只有传闻赏格，发布者无力兑现承诺\n所拍卖的稀有宝材改成已在交易中的资产，报酬高来自商誉损失。不得凭接单自动获知嫌疑人所在；悬赏条件、证据与承诺需专门记录。"},{"card":{"adaptation_notes":"反射禁制要能用有限试验识别，不复制超强攻击必破的结果。救援与取宝分成两份同意；宝物归属、停手阈值与入口状态需扩展。","category":"探索与禁制","choices":[{"action_hint":"custom:bounded_rescue_side_objective","continuation":"若机制在能力范围内可再议；若超限则按约撤离。","label":"限定一次低强度探测并约定停止信号","requires_extension":true,"tradeoff":"探测会消耗安全窗口，反噬仍可能损伤工具。"},{"action_hint":"interact:ask","continuation":"若有替代器具或以后重入办法，可减少眼下争执。","label":"询问以往失败方式及缺少器具的实际影响","requires_extension":false,"tradeoff":"对方可能因执念低估代价，问清也不保证可取。"},{"action_hint":"evade:withdraw","continuation":"若双方安全离开且未来再有条件，可另立寻回计划。","label":"撤离危险区域，拒绝追加取宝","requires_extension":false,"tradeoff":"关键器具可能留在原处，受困者仍须自行选择去留。"}],"conflict":"救援者要把握安全窗口，受困者不愿放弃多年所得；她愿分宝，却无法替全队承担错过出口的风险。","dedupe_key":"rescue_exit_incomplete_legacy_detour","exclusions":["没有安全出口，或寻宝只是营救者强加要求"],"followups":[{"closure":"安全撤离、目标取出或救援职责明确移交。","development":"按事前约定停止追加尝试，受困者不因失宝自动倒戈。","trigger":"禁制反应超出估计、入口告警或停止期限到来"}],"id":"WD-FR-111","npc_motives":["受困者：希望带着完整传承离开，而非让多年苦修留下永久缺口。","入口守望者：担忧后来者进入，需要可执行的撤离期限。"],"preconditions":["已建立真实可用的出口","目标物确与受困者已有能力相关且位置可见"],"situation":"你终于打通救援入口，受困者却请求稍作停留，取回能补全多年修行的关键器具。禁制曾反噬过她，后方入口也不能保证一直不被别人发现。","tags":["营救","沉没投入","反射禁制","撤离时机"],"title":"出口已开，传承却差最后一件","variation_slots":["传承缺失的功能","入口暴露的可观察迹象"]},"content_version":"2026-10-31.1","id":"WD-FR-111","metadata":{"category":"探索与禁制","dedupe_key":"rescue_exit_incomplete_legacy_detour","source_card_id":"WD-FR-111","source_chapter_ids":["FR-2368"],"tags":["营救","沉没投入","反射禁制","撤离时机"]},"retrieval_text":"出口已开，传承却差最后一件\n探索与禁制\n营救 沉没投入 反射禁制 撤离时机\n你终于打通救援入口，受困者却请求稍作停留，取回能补全多年修行的关键器具。禁制曾反噬过她，后方入口也不能保证一直不被别人发现。\n救援者要把握安全窗口，受困者不愿放弃多年所得；她愿分宝，却无法替全队承担错过出口的风险。\n受困者：希望带着完整传承离开，而非让多年苦修留下永久缺口。\n入口守望者：担忧后来者进入，需要可执行的撤离期限。\n已建立真实可用的出口\n目标物确与受困者已有能力相关且位置可见\n没有安全出口，或寻宝只是营救者强加要求\n反射禁制要能用有限试验识别，不复制超强攻击必破的结果。救援与取宝分成两份同意；宝物归属、停手阈值与入口状态需扩展。"},{"card":{"adaptation_notes":"小界通道改成有明确容量的远行渠道，不沿用原著人口规模。名额、本人意愿与留守防卫分别处理；不能仅宣布公平便自动安置所有人。","category":"势力博弈","choices":[{"action_hint":"custom:phased_migration_public_continuity","continuation":"若最低保护条件落实，可让首批自愿者成行。","label":"协商分批迁出与防卫交接","requires_extension":true,"tradeoff":"部分人需等候，设置防护和培养接替者也耗资源。"},{"action_hint":"interact:ask","continuation":"若需求可由设备或互助补足，可减少必须留人的数量。","label":"询问留守者最迫切的防卫缺口","requires_extension":false,"tradeoff":"可能暴露长期分配不公，不能只靠解释安抚。"},{"action_hint":"interact:decline","continuation":"以后若只需某项有限协助，可独立决定是否参与。","label":"拒绝替当地分配名额，退出协调","requires_extension":false,"tradeoff":"通道机会仍受期限影响，各方需另找可信协调者。"}],"conflict":"报名者有追求前途的权利，留下者需要基本保护，单按实力或潜力选人可能扩大原地的生存风险。","dedupe_key":"selective_migration_defense_brain_drain","exclusions":["可以无成本带走所有愿意离开者"],"followups":[{"closure":"迁出与留守保障得到交接，或通道计划终止。","development":"重新审视受影响者与自愿名单，不把年轻后辈默认为可带走资源。","trigger":"第一批名单公布、交接未完成或通道容量改变"}],"id":"WD-FR-112","npc_motives":["迁出代表：长期受限于环境，不愿放弃难得机会。","留守居民代表：不要求别人永远留下，但希望有可行的交接保障。"],"preconditions":["通道可用且容量或稳定性确有限制","拟迁出者确实承担当前公共防卫职责"],"situation":"一条稀有通道可以让部分人离开资源贫乏的地区，强者和有潜力的后辈都想报名。通道容量有限，他们同时也是留下者抵御外敌的重要力量。","tags":["人才迁出","弱势群体","通道容量","公共责任"],"title":"能带走精英，带不走所有人","variation_slots":["受限地区的公共职能","可替代留守人力的设施"]},"content_version":"2026-10-31.1","id":"WD-FR-112","metadata":{"category":"势力博弈","dedupe_key":"selective_migration_defense_brain_drain","source_card_id":"WD-FR-112","source_chapter_ids":["FR-2399"],"tags":["人才迁出","弱势群体","通道容量","公共责任"]},"retrieval_text":"能带走精英，带不走所有人\n势力博弈\n人才迁出 弱势群体 通道容量 公共责任\n一条稀有通道可以让部分人离开资源贫乏的地区，强者和有潜力的后辈都想报名。通道容量有限，他们同时也是留下者抵御外敌的重要力量。\n报名者有追求前途的权利，留下者需要基本保护，单按实力或潜力选人可能扩大原地的生存风险。\n迁出代表：长期受限于环境，不愿放弃难得机会。\n留守居民代表：不要求别人永远留下，但希望有可行的交接保障。\n通道可用且容量或稳定性确有限制\n拟迁出者确实承担当前公共防卫职责\n可以无成本带走所有愿意离开者\n小界通道改成有明确容量的远行渠道，不沿用原著人口规模。名额、本人意愿与留守防卫分别处理；不能仅宣布公平便自动安置所有人。"},{"card":{"adaptation_notes":"真仙威胁可换成流寇、疫兽或失控兵器，强度须适配地区。私人关联只增加待核验线索；预警、资源共享和军事承诺需分开存储。","category":"势力博弈","choices":[{"action_hint":"custom:limited_joint_early_warning","continuation":"若共同监测证实风险，可再议援军与指挥权限。","label":"先共享有限预警情报，保留战力承诺","requires_extension":true,"tradeoff":"会暴露部分本地布防，尚不能获得全部盟约待遇。"},{"action_hint":"interact:ask","continuation":"若追踪链成立，可通知相关旧识并调整防范。","label":"要求区分灾害规律与私人关联证据","requires_extension":false,"tradeoff":"可能令联络者不快，但有助防止把推测变成归责。"},{"action_hint":"interact:decline","continuation":"若商盟改变条件或新证据出现，可重新协商。","label":"拒绝当前同盟条件，结束会谈","requires_extension":false,"tradeoff":"无法立即共享全部防卫资源，仍需承担本地准备。"}],"conflict":"商盟需要更多力量承担防卫，你要判断本地实际风险；私人关系可能是真线索，也可能被用来压低你的议价空间。","dedupe_key":"shared_threat_personal_link_pressure","exclusions":["灾害仅有单方传闻，或无任何可核对追踪线索"],"followups":[{"closure":"威胁离境、合作正式签订或本轮磋商结束。","development":"按已共享证据重估责任，不能用旧识关系推定玩家制造灾害。","trigger":"共同预警发现真实踪迹或出现要求出兵的正式请求"}],"id":"WD-FR-113","npc_motives":["商盟联络者：担忧灾祸跨境，希望关键势力尽快表态。","地方守备者：不愿盲目外调战力，也不能假装人口聚集地没有风险。"],"preconditions":["已有多个独立地点的灾害证据","玩家能影响一部分真实防卫资源"],"situation":"一个游荡灾祸已破坏多个强大势力，商盟希望你加入共同防卫，还指出你的旧识可能被追踪而把危险带来。公事警告与谈判施压交织在一起。","tags":["跨地灾害","情报共享","私人关联","共同防卫"],"title":"共同危机与借机施压","variation_slots":["灾害选择目标的规律","旧识可能携带的追踪线索"]},"content_version":"2026-10-31.1","id":"WD-FR-113","metadata":{"category":"势力博弈","dedupe_key":"shared_threat_personal_link_pressure","source_card_id":"WD-FR-113","source_chapter_ids":["FR-2404"],"tags":["跨地灾害","情报共享","私人关联","共同防卫"]},"retrieval_text":"共同危机与借机施压\n势力博弈\n跨地灾害 情报共享 私人关联 共同防卫\n一个游荡灾祸已破坏多个强大势力，商盟希望你加入共同防卫，还指出你的旧识可能被追踪而把危险带来。公事警告与谈判施压交织在一起。\n商盟需要更多力量承担防卫，你要判断本地实际风险；私人关系可能是真线索，也可能被用来压低你的议价空间。\n商盟联络者：担忧灾祸跨境，希望关键势力尽快表态。\n地方守备者：不愿盲目外调战力，也不能假装人口聚集地没有风险。\n已有多个独立地点的灾害证据\n玩家能影响一部分真实防卫资源\n灾害仅有单方传闻，或无任何可核对追踪线索\n真仙威胁可换成流寇、疫兽或失控兵器，强度须适配地区。私人关联只增加待核验线索；预警、资源共享和军事承诺需分开存储。"},{"card":{"adaptation_notes":"只提炼被隐瞒的消耗条款，不复制原著必死结局。触发前必须给出可观察异常和实际退路，献祭与全局胜败不能预先写死。","category":"同盟与背叛","choices":[{"action_hint":"custom:expose_sacrificial_position","continuation":"若警报及时传达，各方可选择撤离或自愿留下。","label":"公开异常并组织同阵人员撤离","requires_extension":true,"tradeoff":"会失去隐蔽优势，指挥者可能提前改变启动顺序。"},{"action_hint":"custom:interrupt_sacrifice_conduit","continuation":"若中断成功，可争取撤离时间，但主战场也可能失去支援。","label":"尝试隔断已确认的献祭支路","requires_extension":true,"tradeoff":"需懂得相关结构，失败可能损坏防护并暴露自己。"},{"action_hint":"evade:withdraw","continuation":"安全后可凭证据处理盟约背弃，不必再次返回战场。","label":"沿已有退路立即撤出阵位","requires_extension":false,"tradeoff":"可能来不及救助全部同伴，也放弃此处战利与职务。"}],"conflict":"指挥者想以少数人补足缺失力量，守阵者从未同意充当燃料；战时命令不能消除被骗承担的死亡风险。","dedupe_key":"allied_position_hidden_sacrifice","exclusions":["陷阱已无任何可行动窗口，或仅为无法验证的直觉"],"followups":[{"closure":"脱险、阵位停用或玩家完成愿意承担的作证。","development":"区分知情自愿者与受骗者，按真实行动记录责任。","trigger":"启动命令下达、其他阵位回应或战后追责开始"}],"id":"WD-FR-114","npc_motives":["指挥者：确信非常手段必要，担心消息传开使整个计划瓦解。","同阵守卫：最初相信盟约，如今需要清晰警报和可用撤路。"],"preconditions":["阵位异常可在封闭前被玩家察觉","至少存在一条事前建立的撤离或中断手段"],"situation":"你受盟军安排守护关键阵位，启动前却发现能源流向指向守阵者，承诺配置的核心器物也不在。指挥部声称这是保全全局所需的最后手段。","tags":["战时背叛","献祭","阵地权限","紧急撤离"],"title":"阵眼下藏着献祭名单","variation_slots":["被替代的核心资源","可提前发现的异常流向"]},"content_version":"2026-10-31.1","id":"WD-FR-114","metadata":{"category":"同盟与背叛","dedupe_key":"allied_position_hidden_sacrifice","source_card_id":"WD-FR-114","source_chapter_ids":["FR-2429"],"tags":["战时背叛","献祭","阵地权限","紧急撤离"]},"retrieval_text":"阵眼下藏着献祭名单\n同盟与背叛\n战时背叛 献祭 阵地权限 紧急撤离\n你受盟军安排守护关键阵位，启动前却发现能源流向指向守阵者，承诺配置的核心器物也不在。指挥部声称这是保全全局所需的最后手段。\n指挥者想以少数人补足缺失力量，守阵者从未同意充当燃料；战时命令不能消除被骗承担的死亡风险。\n指挥者：确信非常手段必要，担心消息传开使整个计划瓦解。\n同阵守卫：最初相信盟约，如今需要清晰警报和可用撤路。\n阵位异常可在封闭前被玩家察觉\n至少存在一条事前建立的撤离或中断手段\n陷阱已无任何可行动窗口，或仅为无法验证的直觉\n只提炼被隐瞒的消耗条款，不复制原著必死结局。触发前必须给出可观察异常和实际退路，献祭与全局胜败不能预先写死。"},{"card":{"adaptation_notes":"特殊契约改成世界有执行依据的强约束合同，不继承仙界契约排名。新增安全义务必须可判定，签约、供给与遗留权利需扩展状态。","category":"交易与信用","choices":[{"action_hint":"custom:incentive_aligned_service_pact","continuation":"若能将行为范围写清并获得独立核验，可再考虑签订。","label":"要求加入风险披露及不得诱导受害的条款","requires_extension":true,"tradeoff":"对方可能提高日常报酬，也可能拒绝接受宽泛义务。"},{"action_hint":"interact:ask","continuation":"若发现已知漏洞，可要求补充限制或放弃交易。","label":"向鉴证者核实守约范围与失踪记录","requires_extension":false,"tradeoff":"历史记录可能不完整，不能由相关性直接断定谋害。"},{"action_hint":"interact:decline","continuation":"以后只有新条件和安全会面机会同时出现才重谈。","label":"拒绝缔约，结束合作商谈","requires_extension":false,"tradeoff":"失去特殊服务，也不因拒绝自动恢复敌对。"}],"conflict":"对方愿守字面条款，你需要真实的安全利益一致；它不必直接违约，也可能乐于见你选择过度危险的道路。","dedupe_key":"binding_pact_misaligned_survival_incentive","exclusions":["玩家无拒绝余地，或契约内容无法被理解"],"followups":[{"closure":"契约期满结清、双方解除或玩家明确不签。","development":"检查建议利益冲突及披露义务，不能只问是否触犯契约。","trigger":"服务者建议冒险、索取额外报酬或触发遗留权益争议"}],"id":"WD-FR-115","npc_motives":["契约服务者：希望取得稳定供给，对雇主遗留利益同样垂涎。","中立鉴证者：只能证明约束有效，不能担保对方动机或全部建议。"],"preconditions":["双方已能停战或平等谈判","世界已有可验证的契约约束且允许附加条款"],"situation":"一名危险但有用的异类提出严格守约的服务合同，报酬包括日常供给及你身败后的遗留力量。第三方认可契约效力，却无法解释过往雇主常遭不测。","tags":["契约","利益错位","第三方核验","附加限制"],"title":"守约者也可能盼你败亡","variation_slots":["服务者可获得的身后利益","可独立验证的约束范围"]},"content_version":"2026-10-31.1","id":"WD-FR-115","metadata":{"category":"交易与信用","dedupe_key":"binding_pact_misaligned_survival_incentive","source_card_id":"WD-FR-115","source_chapter_ids":["FR-2434"],"tags":["契约","利益错位","第三方核验","附加限制"]},"retrieval_text":"守约者也可能盼你败亡\n交易与信用\n契约 利益错位 第三方核验 附加限制\n一名危险但有用的异类提出严格守约的服务合同，报酬包括日常供给及你身败后的遗留力量。第三方认可契约效力，却无法解释过往雇主常遭不测。\n对方愿守字面条款，你需要真实的安全利益一致；它不必直接违约，也可能乐于见你选择过度危险的道路。\n契约服务者：希望取得稳定供给，对雇主遗留利益同样垂涎。\n中立鉴证者：只能证明约束有效，不能担保对方动机或全部建议。\n双方已能停战或平等谈判\n世界已有可验证的契约约束且允许附加条款\n玩家无拒绝余地，或契约内容无法被理解\n特殊契约改成世界有执行依据的强约束合同，不继承仙界契约排名。新增安全义务必须可判定，签约、供给与遗留权利需扩展状态。"},{"card":{"adaptation_notes":"数千年改成足以发生代际更替的时间，生死近况须由既有世界记录支撑。相认、传承和宗门控制分开，不因先辈身份强制收回产业。","category":"凡俗与旧情","choices":[{"action_hint":"custom:discreet_legacy_check","continuation":"若生活稳定，可留下资料或不再介入；有求助则另议。","label":"隐去身份核查近况，只处理明确请求","requires_extension":true,"tradeoff":"可能无法立刻获知隐情，也得不到公开尊崇。"},{"action_hint":"interact:ask","continuation":"若发现不同分支，可分别了解而不强行归并。","label":"向知情人询问传承的实际去向","requires_extension":false,"tradeoff":"所得仍是他人视角，不能凭名号判断后辈善恶。"},{"action_hint":"interact:leave","continuation":"以后只有新的真实求助或自愿相认才开启后续。","label":"结束探访，不主动与后辈相认","requires_extension":false,"tradeoff":"放下当面重建联系的机会，也保留他们现有秩序。"}],"conflict":"你想确认旧事与传承是否安好，后辈已形成自己的生活和权力安排，公开身份可能重新改变他们之间的平衡。","dedupe_key":"returning_founder_nonintervention","exclusions":["后辈正面临已向玩家请求救助的即时危机"],"followups":[{"closure":"近况核实且本次探访结束，或请求独立结清。","development":"在当事人同意下提供有限协助，旧渊源不自动赋予统治权。","trigger":"后辈主动寻根、传承资料受损或旧友转达具体请求"}],"id":"WD-FR-116","npc_motives":["知情旧友：愿讲真实近况，也担心返乡强者把旧恩变成新命令。","传承后辈：重视祖辈名望，却未必希望被一个突然出现的前辈接管。"],"preconditions":["玩家确有长期离乡与曾传授的技艺或关系","中间人可提供多方核验的近况"],"situation":"久别返乡，你发现熟悉的人多已不在，昔日传下的技艺却由后辈延续，甚至形成新的地方势力。中间人可以证明渊源，后辈尚不知道你归来。","tags":["返乡","传承","代际变化","有限介入"],"title":"道统还在，故人已远","variation_slots":["曾传下的技艺或器物","后辈形成的新组织"]},"content_version":"2026-10-31.1","id":"WD-FR-116","metadata":{"category":"凡俗与旧情","dedupe_key":"returning_founder_nonintervention","source_card_id":"WD-FR-116","source_chapter_ids":["FR-2448"],"tags":["返乡","传承","代际变化","有限介入"]},"retrieval_text":"道统还在，故人已远\n凡俗与旧情\n返乡 传承 代际变化 有限介入\n久别返乡，你发现熟悉的人多已不在，昔日传下的技艺却由后辈延续，甚至形成新的地方势力。中间人可以证明渊源，后辈尚不知道你归来。\n你想确认旧事与传承是否安好，后辈已形成自己的生活和权力安排，公开身份可能重新改变他们之间的平衡。\n知情旧友：愿讲真实近况，也担心返乡强者把旧恩变成新命令。\n传承后辈：重视祖辈名望，却未必希望被一个突然出现的前辈接管。\n玩家确有长期离乡与曾传授的技艺或关系\n中间人可提供多方核验的近况\n后辈正面临已向玩家请求救助的即时危机\n数千年改成足以发生代际更替的时间，生死近况须由既有世界记录支撑。相认、传承和宗门控制分开，不因先辈身份强制收回产业。"},{"card":{"adaptation_notes":"飞升改成无法久候的远行窗口，源中的突然离别只启发筹备冲突。不能保证突破成功；同行许可、物品交接和联络约定需显式支持。","category":"突破与远行","choices":[{"action_hint":"custom:predeparture_affairs_handover","continuation":"若各方确认，成功时可按既定安排行动而减少遗留争议。","label":"预先交接职责、物品与未竟约定","requires_extension":true,"tradeoff":"需暴露部分计划，也可能发现有人无法同行。"},{"action_hint":"custom:farewell_and_contact_arrangement","continuation":"若众人愿意，可留下可执行的联络方式而不许诺必定回来。","label":"安排一次不保证重逢的正式告别","requires_extension":true,"tradeoff":"会直接面对分别，并占用本可用于准备的心力。"},{"action_hint":"interact:decline","continuation":"等职责与个人意愿更清楚时，再自主决定是否启动。","label":"延期尝试，结束本轮突破筹备","requires_extension":false,"tradeoff":"错过当前便利条件，后续准备可能需要重做。"}],"conflict":"你希望把握突破机会，亲友希望见证并告别；成功后的窗口可能极短，不能指望届时再把未竟之事全部交代。","dedupe_key":"ascension_window_predeparture_closure","exclusions":["突破已经不可逆启动，无法再进行平静筹备"],"followups":[{"closure":"出行与留守事项完成移交，或玩家取消此次突破。","development":"按实际去向交接后续，未能告别不自动变成怨恨或惩罚。","trigger":"成功触发通道、尝试中止或已留约定到达期限"}],"id":"WD-FR-117","npc_motives":["同行者：需要提前知道随行资格与集合方式，不能临时冒险闯入。","留守亲友：希望得到真实安排，不愿只被告知一切以后再说。"],"preconditions":["世界已确认成功后会触发难以延缓的远行机制","玩家仍处于可暂停的准备阶段"],"situation":"你的突破准备接近完成，成功后可能立刻开启单向远行通道。亲友只能在安全距离外守候，哪些同伴能同行、哪些物事须留下，都还需要事先安排。","tags":["不可逆远行","告别","同伴安排","传承"],"title":"门开之前把告别说完","variation_slots":["单向远行的触发方式","可同行者的真实条件"]},"content_version":"2026-10-31.1","id":"WD-FR-117","metadata":{"category":"突破与远行","dedupe_key":"ascension_window_predeparture_closure","source_card_id":"WD-FR-117","source_chapter_ids":["FR-2451"],"tags":["不可逆远行","告别","同伴安排","传承"]},"retrieval_text":"门开之前把告别说完\n突破与远行\n不可逆远行 告别 同伴安排 传承\n你的突破准备接近完成，成功后可能立刻开启单向远行通道。亲友只能在安全距离外守候，哪些同伴能同行、哪些物事须留下，都还需要事先安排。\n你希望把握突破机会，亲友希望见证并告别；成功后的窗口可能极短，不能指望届时再把未竟之事全部交代。\n同行者：需要提前知道随行资格与集合方式，不能临时冒险闯入。\n留守亲友：希望得到真实安排，不愿只被告知一切以后再说。\n世界已确认成功后会触发难以延缓的远行机制\n玩家仍处于可暂停的准备阶段\n突破已经不可逆启动，无法再进行平静筹备\n飞升改成无法久候的远行窗口，源中的突然离别只启发筹备冲突。不能保证突破成功；同行许可、物品交接和联络约定需显式支持。"},{"card":{"adaptation_notes":"外传仙牌改成当地通行凭证，飞升优待不能直接移植为固定规则。公开身份手续与私人招揽分开；记录更正、权限和副本需扩展。","category":"身份与秘密","choices":[{"action_hint":"custom:correct_arrival_identity_record","continuation":"若记录完成，可再分别判断公共凭证与私人邀约。","label":"提出补记可核验的故乡特征并保留副本","requires_extension":true,"tradeoff":"手续可能延长，对方也可能嫌麻烦而转交他人。"},{"action_hint":"interact:ask","continuation":"若确认招揽并非登记条件，可保持独立选择。","label":"询问凭证权利、登记义务与接待员所属","requires_extension":false,"tradeoff":"回答仍需对照公开规则，不能只凭热情判断中立。"},{"action_hint":"interact:leave","continuation":"取得清楚说明或新窗口后再自愿办理。","label":"暂不领取凭证，结束本次交谈","requires_extension":false,"tradeoff":"尚不能使用对应通行便利，仍需在许可区域等候。"}],"conflict":"接待员要快速完成流程并争取人才，你既需要合法身份，也须弄清记录错误与私人邀约是否会影响未来选择。","dedupe_key":"arrival_registry_dual_role_recruiter","exclusions":["玩家已有有效登记，或接待者没有任何授权证明"],"followups":[{"closure":"记录获确认且基本规则明确，或另换正式办理途径。","development":"以保存记录核对实际权利，不把登记错误自动变成罪名。","trigger":"首次使用凭证、发现来源记录不符或被要求加入某方"}],"id":"WD-FR-118","npc_motives":["接待员：想减少核对工作，也希望新人接受其所属势力邀请。","登记主管：要求记录可追溯，但通常不在现场逐人检查。"],"preconditions":["玩家刚进入规则不同且实行身份登记的地区","现场有已允许停留的候验区和可询问人员"],"situation":"你抵达陌生地区，接待员因故乡重名而打算略记来源，再发放便利通行凭证。他代办公共差事，却同时代表一家招揽新人的私人势力。","tags":["入境登记","身份凭证","规则认知","代理利益"],"title":"同名故乡与随手登记","variation_slots":["造成登记歧义的地名或称谓","公共接待的承包势力"]},"content_version":"2026-10-31.1","id":"WD-FR-118","metadata":{"category":"身份与秘密","dedupe_key":"arrival_registry_dual_role_recruiter","source_card_id":"WD-FR-118","source_chapter_ids":["FR-2452"],"tags":["入境登记","身份凭证","规则认知","代理利益"]},"retrieval_text":"同名故乡与随手登记\n身份与秘密\n入境登记 身份凭证 规则认知 代理利益\n你抵达陌生地区，接待员因故乡重名而打算略记来源，再发放便利通行凭证。他代办公共差事，却同时代表一家招揽新人的私人势力。\n接待员要快速完成流程并争取人才，你既需要合法身份，也须弄清记录错误与私人邀约是否会影响未来选择。\n接待员：想减少核对工作，也希望新人接受其所属势力邀请。\n登记主管：要求记录可追溯，但通常不在现场逐人检查。\n玩家刚进入规则不同且实行身份登记的地区\n现场有已允许停留的候验区和可询问人员\n玩家已有有效登记，或接待者没有任何授权证明\n外传仙牌改成当地通行凭证，飞升优待不能直接移植为固定规则。公开身份手续与私人招揽分开；记录更正、权限和副本需扩展。"},{"card":{"adaptation_notes":"外传境界与修炼年限不沿用，改成地区适应成本。旅行仅前往已知地点，不自动入门；客卿身份、教学领取和退出债务需另有状态。","category":"突破与远行","choices":[{"action_hint":"travel:road","continuation":"若看到真实教学和生活条件，可再决定是否谈约。","label":"按邀请前往已标明驻地查看","requires_extension":false,"tradeoff":"会耗费行程与食宿资源，参观也可能遭遇密集劝说。"},{"action_hint":"interact:ask","continuation":"若标准可核验，可将试住与长期学习分阶段谈。","label":"询问等价偿还如何计算、由谁裁定","requires_extension":false,"tradeoff":"对方可能无法即刻给出清单，优惠也不保证长期保留。"},{"action_hint":"interact:decline","continuation":"以后找到其他落脚点或新报价再独立选择。","label":"拒绝此次依附邀约，结束会谈","requires_extension":false,"tradeoff":"需自行解决适应期成本，也失去当前赠课条件。"}],"conflict":"你需要暂时依托，招揽者想留住人才；看似自由的退出条款若没有估价办法，仍可能变成长期负担。","dedupe_key":"newcomer_residency_service_lockin","exclusions":["条款直接要求终身效忠，或途中已存在已知伏击"],"followups":[{"closure":"明确拒绝、签订独立合同或按约偿还离开。","development":"核对哪项资源需要偿还以及估价依据，防止事后无限抬价。","trigger":"参观后提出签约、开始领取资源或准备退出"}],"id":"WD-FR-119","npc_motives":["招揽者：愿投入稀缺教学资源，希望新人最终留下贡献。","驻地现任客卿：了解日常义务，却可能不清楚真正离开者的经历。"],"preconditions":["玩家确有环境适应或学习需求","驻地已明确可前往且参观不等于签约"],"situation":"你初到新地，需要一段适应与学习期。接引者提出提供住处和完整技艺，称可先任客卿、日后等价偿还即可退出，并已标明驻地位置邀请参观。","tags":["新地适应","有限依附","退出成本","实地考察"],"title":"先看驻地，再谈依附","variation_slots":["适应新地所需知识","偿还资源的估价与仲裁方式"]},"content_version":"2026-10-31.1","id":"WD-FR-119","metadata":{"category":"突破与远行","dedupe_key":"newcomer_residency_service_lockin","source_card_id":"WD-FR-119","source_chapter_ids":["FR-2453"],"tags":["新地适应","有限依附","退出成本","实地考察"]},"retrieval_text":"先看驻地，再谈依附\n突破与远行\n新地适应 有限依附 退出成本 实地考察\n你初到新地，需要一段适应与学习期。接引者提出提供住处和完整技艺，称可先任客卿、日后等价偿还即可退出，并已标明驻地位置邀请参观。\n你需要暂时依托，招揽者想留住人才；看似自由的退出条款若没有估价办法，仍可能变成长期负担。\n招揽者：愿投入稀缺教学资源，希望新人最终留下贡献。\n驻地现任客卿：了解日常义务，却可能不清楚真正离开者的经历。\n玩家确有环境适应或学习需求\n驻地已明确可前往且参观不等于签约\n条款直接要求终身效忠，或途中已存在已知伏击\n外传境界与修炼年限不沿用，改成地区适应成本。旅行仅前往已知地点，不自动入门；客卿身份、教学领取和退出债务需另有状态。"},{"card":{"adaptation_notes":"养魂设定改成可验证的生命维持或意识保管需求，不能保证永久延命。材料、图谱、授艺与传人同意分别存储，原著附带广告不作为事件。","category":"师徒与控制","choices":[{"action_hint":"custom:legacy_craft_staged_apprenticeship","continuation":"若作品进展可验证，双方可继续履约并让传人自主拜师。","label":"约定先稳定匠师处境，再按作品阶段换授艺","requires_extension":true,"tradeoff":"需承担材料与工期风险，未完成时只能获得已约定部分。"},{"action_hint":"interact:ask","continuation":"若核心只是保留图谱，可另谈更可行的传承形式。","label":"询问作品、延命与传承三项的真正优先级","requires_extension":false,"tradeoff":"可能发现时间不足以全做，必须接受目标缩减。"},{"action_hint":"interact:decline","continuation":"若以后只求一项有限协助，可重新订立新约。","label":"拒绝承担整套遗愿，结束交易","requires_extension":false,"tradeoff":"暂时得不到后续技艺，匠师仍可另寻合作人。"}],"conflict":"你想补齐所学，匠师想让作品和道统真正存续；单付材料既不能保证作品完成，也不能替未来传人作决定。","dedupe_key":"dying_artisan_legacy_staged_exchange","exclusions":["匠师已拒绝一切传授，或只剩无法沟通的遗物"],"followups":[{"closure":"约定作品与传承安置完成，或双方结清后终止。","development":"按实际完成部分授艺与结算，不以潜在传人的拒绝判玩家背誓。","trigger":"首件养护器具交付、作品达到阶段或传人明确表态"}],"id":"WD-FR-120","npc_motives":["老匠师：知道余日有限，愿分期传授但不肯先交全部心血。","潜在传人：可能适合技艺，却有自己的生活与拜师选择。"],"preconditions":["双方已停止冲突且确认各自需要","玩家有相关基础，能承担部分材料或寻找工作"],"situation":"你找到掌握失传技艺的衰弱匠师，普通财物无法打动他。能延缓衰亡的器具也只解决一部分心愿，他更想完成最后设计，并找到愿意继承的人。","tags":["技艺传承","未竟之作","分期履约","继承人"],"title":"晚年匠师要的不止延命","variation_slots":["匠师未竟的作品","愿意而适合继承的人选"]},"content_version":"2026-10-31.1","id":"WD-FR-120","metadata":{"category":"师徒与控制","dedupe_key":"dying_artisan_legacy_staged_exchange","source_card_id":"WD-FR-120","source_chapter_ids":["FR-2454"],"tags":["技艺传承","未竟之作","分期履约","继承人"]},"retrieval_text":"晚年匠师要的不止延命\n师徒与控制\n技艺传承 未竟之作 分期履约 继承人\n你找到掌握失传技艺的衰弱匠师，普通财物无法打动他。能延缓衰亡的器具也只解决一部分心愿，他更想完成最后设计，并找到愿意继承的人。\n你想补齐所学，匠师想让作品和道统真正存续；单付材料既不能保证作品完成，也不能替未来传人作决定。\n老匠师：知道余日有限，愿分期传授但不肯先交全部心血。\n潜在传人：可能适合技艺，却有自己的生活与拜师选择。\n双方已停止冲突且确认各自需要\n玩家有相关基础，能承担部分材料或寻找工作\n匠师已拒绝一切传授，或只剩无法沟通的遗物\n养魂设定改成可验证的生命维持或意识保管需求，不能保证永久延命。材料、图谱、授艺与传人同意分别存储，原著附带广告不作为事件。"}];
